func.func @main(%arg0: tensor<f32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg3: input x, shape [6,7]
  // %arg1: linear.weight, shape [7,7]
  // %arg2: linear.bias, shape [7]
  // %arg0: constant scalar, shape [], but passed as tensor<f32>

  // Linear layer: y = x * W^T + b
  // PyTorch Linear: output = input @ weight.T + bias
  // weight shape: [out_features, in_features] = [7,7]
  // input shape: [6,7]
  // So we do dot_general with contracting dims: input dim 1 and weight dim 1
  // But weight needs to be transposed to [in_features, out_features] for dot_general
  // Actually, PyTorch weight is [out_features, in_features], so to do input @ weight.T,
  // we can do dot_general with lhs=input [6,7], rhs=weight [7,7], contracting dims (1,1)
  // So no transpose needed, just contract dim 1 of lhs and rhs.

  %dot = stablehlo.dot_general %arg3, %arg1 {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [1]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias [7] to [6,7]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %add = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Compute minimum with constant scalar
  // constant scalar is %arg0: tensor<f32> shape []
  // Broadcast constant scalar to [6,7]
  %const_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<f32> to tensor<6x7xf32> broadcast_dimensions = []

  %min = stablehlo.minimum %add, %const_broadcast : tensor<6x7xf32>

  // Subtract constant scalar broadcasted
  %sub = stablehlo.subtract %min, %const_broadcast : tensor<6x7xf32>

  stablehlo.return %sub : tensor<6x7xf32>
}

