  // %arg3: input x, shape [6,7]
  // %arg1: linear.weight, shape [7,7]
  // %arg2: linear.bias, shape [7]
  // %arg0: constant scalar, shape []

  // Perform linear layer: x * W^T + b
  // dot_general with batch dims [0] and contracting dims [1]
  %0 = "stablehlo.dot_general"(%arg3, %arg1) {
    lhs_batching_dimensions = [0],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias from [7] to [6,7]
  %1 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // Broadcast constant scalar to [6,7]
  %3 = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = [], output_shape = [6,7]} : (tensor<f32>) -> tensor<6x7xf32>

  // Apply minimum: min(x, constant)
  %4 = stablehlo.minimum %2, %3 : tensor<6x7xf32>

  // Subtract constant: x - constant
  %5 = stablehlo.subtract %4, %3 : tensor<6x7xf32>

  return %5 : tensor<6x7xf32>
}

