  // 1) transpose %arg0 from [6,7,3,3,3] to [7,6,3,3,3]
  // 2) perform convolution with lhs_dilation = [1,1,1], rhs_dilation = [1,1,1], padding = [[2,2],[2,2],[2,2]]
  // 3) return result

  %weight_transposed = stablehlo.transpose %arg0 {permutation = [1, 0, 2, 3, 4]} : tensor<6x7x3x3x3xf32> to tensor<7x6x3x3x3xf32>

