  %zero_tensor = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x6x5x5xf32> broadcast_dimensions = []

  %max_part = stablehlo.maximum %mul, %zero_tensor : tensor<6x6x5x5xf32>
  %min_part = stablehlo.minimum %mul, %zero_tensor : tensor<6x6x5x5xf32>

