  // Scale and shift: normalized * bn_weight + bn_bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_scaled = stablehlo.multiply %normalized, %bn_weight_broadcast : tensor<6x7xf32>
  %bn_shifted = stablehlo.add %bn_scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // Multiply by scale parameter (broadcast scale shape (1,) to (6,7))
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<1xf32>) -> tensor<6x7xf32>
