  // Compute mean over batch dim 0: mean shape [7]
  %mean = stablehlo.reduce %x1, %cst0 = stablehlo.constant 0.0 : tensor<f32> {
    dimensions = [0]
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // Above is pseudocode, we must write reduce with add and then divide by 6

  // Implement mean = reduce_sum / 6
  %zero = stablehlo.constant 0.0 : tensor<f32>
  %one = stablehlo.constant 1.0 : tensor<f32>
  %six = stablehlo.constant 6.0 : tensor<f32>

  %mean = stablehlo.reduce %x1, %zero {
    dimensions = [0]
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
