  // Broadcast mean to [6x7]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_div : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %diff = stablehlo.subtract %x1, %mean_broadcast : tensor<6x7xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  %var_sum = stablehlo.reduce %sq, %zero {
