    body {
      %a = stablehlo.max %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast max to [6x7]
  %max_broadcast = stablehlo.broadcast_in_dim %max : tensor<6xf32> to tensor<6x7xf32> broadcast_dimensions = [0]

  // Subtract max for numerical stability
  %shifted_logits = stablehlo.subtract %scaled2, %max_broadcast : tensor<6x7xf32>

