  %sum_exp = stablehlo.reduce %exp, %zero {
    dimensions = [1]
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast sum_exp to [6x7]
  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp : tensor<6xf32> to tensor<6x7xf32> broadcast_dimensions = [0]

  // Divide exp by sum_exp to get softmax
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x7xf32>

  func.return %softmax : tensor<6x7xf32>
}

