  %c6 = stablehlo.constant dense<6> : tensor<i32>
  %c7 = stablehlo.constant dense<7> : tensor<i32>
  %c1f = stablehlo.constant dense<1.0> : tensor<f32>
  %c0f = stablehlo.constant dense<0.0> : tensor<f32>
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>

  // Reduce mean over dims 2 and 3 (H,W)
  %mean = stablehlo.reduce(%3, %c0f) (
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  ) {dimensions = [2,3]} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x1x7xf32>

  // Compute divisor = H*W = 1*1=1
  %divisor = stablehlo.constant dense<1.0> : tensor<f32>

  %mean_scaled = stablehlo.div %mean, %divisor : tensor<6x1x7xf32>

  // Compute variance = mean((x - mean)^2) over dims 2 and 3
  // Broadcast mean to shape of x for subtraction
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_scaled 
    {broadcast_dimensions = [0,1,3]} : tensor<6x1x7xf32> to tensor<6x1x1x7xf32>

  %diff = stablehlo.sub %3, %mean_broadcast : tensor<6x1x1x7xf32>

  %sq = stablehlo.mul %diff, %diff : tensor<6x1x1x7xf32>

  %var_sum = stablehlo.reduce(%sq, %c0f) (
    ^bb1(%arg_a: f32, %arg_b: f32):
      %add2 = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add2 : f32
  ) {dimensions = [2,3]} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x1x7xf32>

  %var = stablehlo.div %var_sum, %divisor : tensor<6x1x7xf32>

  // Compute rsqrt(variance + eps)
  %var_eps = stablehlo.add %var, %eps : tensor<6x1x7xf32>

  %rsqrt = stablehlo.rsqrt %var_eps : tensor<6x1x7xf32>

  // Normalize: (x - mean) * rsqrt
  %norm = stablehlo.mul %diff, stablehlo.broadcast_in_dim %rsqrt {broadcast_dimensions = [0,1,3]} : tensor<6x1x1x7xf32>

  // InstanceNorm2d has no affine transform (weight=1, bias=0), so output = norm

  // Squeeze dims 1 and 2: from [6,1,1,7] to [6,7]
  %norm_reshaped = stablehlo.reshape %norm : tensor<6x1x1x7xf32> into tensor<6x7xf32>

  // Step 3: x = x + y
  %add_xy = stablehlo.add %norm_reshaped, %arg3 : tensor<6x7xf32>

  // Step 4: x = x * y
  %mul_xy = stablehlo.mul %add_xy, %arg3 : tensor<6x7xf32>

  stablehlo.return %mul_xy : tensor<6x7xf32>
}

