func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = bmm.weight (7x7)
  // %arg1 = bmm.bias (7)
  // %arg2 = input x (6x7)
  // %arg3 = input y (6x7)

  // Step 1: Linear layer: x @ weight^T + bias
  // We need to do dot_general with batch dimension 0, contracting dimension 1 of x and dimension 1 of weight.
  // weight shape: 7x7, but PyTorch Linear weight is (out_features x in_features),
  // so to do x (6x7) * weight^T (7x7), we do dot_general with contracting dims (1,1)
  // Actually, PyTorch Linear does x @ weight^T + bias, so weight is (out_features x in_features),
  // so weight^T is (in_features x out_features).
  // So dot_general contracting x dim 1 and weight^T dim 0.
  // We'll transpose weight to get weight^T.

  %weight_t = stablehlo.transpose %arg0 {permutation = dense<[1, 0]>} : tensor<7x7xf32> -> tensor<7x7xf32>

  %bmm = "stablehlo.dot_general"(%arg2, %weight_t) {
    lhs_batching_dimensions = dense<[0]>,
    rhs_batching_dimensions = dense<[]>,
    lhs_contracting_dimensions = dense<[1]>,
    rhs_contracting_dimensions = dense<[0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = dense<[1]>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %bmm_bias = stablehlo.add %bmm, %bias_broadcast : tensor<6x7xf32>

  // Step 2: InstanceNorm2d on x.unsqueeze(1).unsqueeze(1)
  // x shape: (6,7)
  // unsqueeze(1) twice -> shape (6,1,1,7)
  // InstanceNorm2d normalizes over spatial dims (H,W) per channel per batch.
  // Here, channel dimension is 3rd dim (index 3), spatial dims are dims 1 and 2.
  // So for each batch and channel, normalize over dims 1 and 2.
  // Since dims 1 and 2 are size 1, mean and variance are just the value itself.
  // But we must implement the formula:
  // y = (x - mean) / sqrt(var + eps)
  // eps = 1e-5

  // Reshape to (6,1,1,7)
  %x_4d = stablehlo.reshape %bmm_bias : tensor<6x7xf32> -> tensor<6x1x1x7xf32>

  // Compute mean over dims 1 and 2 (the spatial dims)
  // Reduce dims = [1, 2]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%x_4d, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = dense<[1, 2]>} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x1x7xf32>

  // Compute divisor for mean: size of dims 1 and 2 = 1*1=1
  %count = stablehlo.constant dense<1.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %count : tensor<6x1x7xf32>

  // Broadcast mean back to shape (6,1,1,7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = dense<[0,1,3]>} : (tensor<6x1x7xf32>) -> tensor<6x1x1x7xf32>

  // Compute variance: mean of (x - mean)^2 over dims 1 and 2
  %diff = stablehlo.subtract %x_4d, %mean_broadcast : tensor<6x1x1x7xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<6x1x1x7xf32>

  %var_sum = "stablehlo.reduce"(%sq_diff, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = dense<[1, 2]>} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x1x7xf32>

  %var = stablehlo.divide %var_sum, %count : tensor<6x1x7xf32>

  // Broadcast var back to (6,1,1,7)
  %var_broadcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = dense<[0,1,3]>} : (tensor<6x1x7xf32>) -> tensor<6x1x1x7xf32>

  // eps constant
  %eps = stablehlo.constant dense<1.000000e-5> : tensor<f32>
  // Broadcast eps to var shape
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = dense<>} : (tensor<f32>) -> tensor<f32>

  // Add eps to var
  %var_eps = stablehlo.add %var_broadcast, %eps_broadcast : tensor<6x1x1x7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x1x1x7xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev : tensor<6x1x1x7xf32>

  // Step 3: squeeze dims 1 and 2 to get back to (6x7)
  // reshape from (6,1,1,7) to (6,7)
  %norm_2d = stablehlo.reshape %norm : tensor<6x1x1x7xf32> -> tensor<6x7xf32>

  // Step 4: x = x + y
  %add = stablehlo.add %norm_2d, %arg3 : tensor<6x7xf32>

  // Step 5: x = x * y
  %mul = stablehlo.multiply %add, %arg3 : tensor<6x7xf32>

  // Return result
  return %mul : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Linear layer: y = x * W^T + b
  // %arg0 is weight of shape [7,7], but PyTorch Linear weight shape is [out_features, in_features]
  // Input %arg2 shape is [6,7], batch_size=6, in_features=7
  // We want to do dot_general with contracting dims: input dim 1 and weight dim 1 (in_features)
  // So we transpose weight to [7,7] (same shape), but we need to contract input dim 1 with weight dim 1
  // Actually, PyTorch Linear does x @ W^T + b, so we need to transpose weight to [7,7] (already 7x7)
  // But to do x @ W^T, we do dot_general with lhs %arg2 [6x7], rhs %arg0 [7x7], contracting lhs dim 1 and rhs dim 0
  // So contracting dims: lhs dim 1, rhs dim 0
  // Result shape: [6,7]

  %0 = "stablehlo.dot_general"(%arg2, %arg0) {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias %arg1 [7] to [6,7]
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>

  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %3 = stablehlo.exponential %2 : tensor<6x7xf32>
  %4 = stablehlo.add %3, %cst_1 : tensor<6x7xf32> // cst_1 is constant 1.0
  %5 = stablehlo.log %4 : tensor<6x7xf32>
  %6 = stablehlo.tanh %5 : tensor<6x7xf32>
  %7 = stablehlo.multiply %2, %6 : tensor<6x7xf32>

  // Apply Mish again
  %8 = stablehlo.exponential %7 : tensor<6x7xf32>
  %9 = stablehlo.add %8, %cst_1 : tensor<6x7xf32>
  %10 = stablehlo.log %9 : tensor<6x7xf32>
  %11 = stablehlo.tanh %10 : tensor<6x7xf32>
  %12 = stablehlo.multiply %7, %11 : tensor<6x7xf32>

  return %12 : tensor<6x7xf32>
}

# Constant 1.0 of shape scalar
stablehlo.constant dense<1.0> : tensor<f32> {sym_name = "cst_1"}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Linear layer: y = x * W^T + b
  // %arg0 is weight of shape [7,7], but PyTorch Linear weight shape is [out_features, in_features]
  // Input x shape: [6,7]
  // We want to do dot_general with contracting dims: input's last dim and weight's last dim (in_features)
  // So we transpose weight to [7,7] (same shape), but we need to contract input's last dim with weight's last dim.
  // Actually, PyTorch Linear does x @ W^T + b, so we do dot_general with lhs=%arg2, rhs=%arg0, contracting lhs dim 1 and rhs dim 1,
  // but weight is [out_features, in_features], so to do x @ W^T, we need to transpose weight to [in_features, out_features].
  // So transpose weight from [7,7] to [7,7] swapping dims 0 and 1.
  %weight_t = stablehlo.transpose %arg0 : tensor<7x7xf32> to tensor<7x7xf32> {permutation = [1, 0]}
  %dot = stablehlo.dot_general %arg2, %weight_t : tensor<6x7xf32>, tensor<7x7xf32>
    {lhs_batching_dimensions = [], rhs_batching_dimensions = [],
     lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]} -> tensor<6x7xf32>
  // Add bias: broadcast bias from [7] to [6,7]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  // Compute exp(linear_out)
  %exp = stablehlo.exponential %linear_out : tensor<6x7xf32>
  // Compute 1 + exp(linear_out)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x7xf32> broadcast_dimensions = []
  %exp_plus_one = stablehlo.add %exp, %one_broadcast : tensor<6x7xf32>
  // Compute log(1 + exp(linear_out))
  %softplus = stablehlo.log %exp_plus_one : tensor<6x7xf32>
  // Compute tanh(softplus)
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7xf32>
  // Compute mish = linear_out * tanh(softplus)
  %mish1 = stablehlo.multiply %linear_out, %tanh_softplus : tensor<6x7xf32>

  // Apply Mish again on mish1
  // Compute exp(mish1)
  %exp2 = stablehlo.exponential %mish1 : tensor<6x7xf32>
  // Compute 1 + exp(mish1)
  %exp2_plus_one = stablehlo.add %exp2, %one_broadcast : tensor<6x7xf32>
  // Compute log(1 + exp(mish1))
  %softplus2 = stablehlo.log %exp2_plus_one : tensor<6x7xf32>
  // Compute tanh(softplus2)
  %tanh_softplus2 = stablehlo.tanh %softplus2 : tensor<6x7xf32>
  // Compute mish2 = mish1 * tanh(softplus2)
  %mish2 = stablehlo.multiply %mish1, %tanh_softplus2 : tensor<6x7xf32>

  stablehlo.return %mish2 : tensor<6x7xf32>
}

func.func @main(%linear_weight: tensor<7x7xf32>, %linear_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Linear layer: output = input * weight^T + bias
  // weight shape: [7,7], input shape: [6,7]
  // We want to do dot_general with contracting dims input:1 and weight:1 (weight transposed)
  // So dot_general dims: lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[1]
  // lhs_batching_dimensions and rhs_batching_dimensions empty
  %linear_out = "stablehlo.dot_general"(%input, %linear_weight) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: bias shape [7], broadcast to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%linear_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out_bias = stablehlo.add %linear_out, %bias_broadcast : tensor<6x7xf32>

  // Mish activation function: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  // First Mish application
  %exp1 = stablehlo.exponential %linear_out_bias : tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %exp1_plus_one = stablehlo.add %one_tensor, %exp1 : tensor<6x7xf32>
  %softplus1 = stablehlo.log %exp1_plus_one : tensor<6x7xf32>
  %tanh_softplus1 = stablehlo.tanh %softplus1 : tensor<6x7xf32>
  %mish1 = stablehlo.multiply %linear_out_bias, %tanh_softplus1 : tensor<6x7xf32>

  // Second Mish application
  %exp2 = stablehlo.exponential %mish1 : tensor<6x7xf32>
  %exp2_plus_one = stablehlo.add %one_tensor, %exp2 : tensor<6x7xf32>
  %softplus2 = stablehlo.log %exp2_plus_one : tensor<6x7xf32>
  %tanh_softplus2 = stablehlo.tanh %softplus2 : tensor<6x7xf32>
  %mish2 = stablehlo.multiply %mish1, %tanh_softplus2 : tensor<6x7xf32>

  return %mish2 : tensor<6x7xf32>
}

func.func @main(%linear_weight: tensor<7x7xf32>, %linear_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %matmul = input @linear_weight^T
  // linear.weight shape: [7,7], input shape: [6,7]
  // We want to do input * linear.weight^T to get [6,7]
  // So lhs: input [6,7], rhs: linear_weight [7,7]
  // Contract lhs dim 1 with rhs dim 1 (rhs contracting dim is 1), batch dims none
  // But linear.weight is [7,7], we want to contract rhs dim 1, so rhs_contracting_dimensions=[1]
  // lhs_contracting_dimensions=[1]
  // So dot_general with lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[1]
  // Result shape: [6,7]
  %matmul = "stablehlo.dot_general"(%input, %linear_weight) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias [7] to [6,7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%linear_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out = stablehlo.add %matmul, %bias_broadcast : tensor<6x7xf32>

  // Define Mish function: mish(x) = x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
  // Compute exp(x)
  %exp_linear_out = stablehlo.exponential %linear_out : tensor<6x7xf32>
  // Compute 1 + exp(x)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %exp_plus_one = stablehlo.add %one_broadcast, %exp_linear_out : tensor<6x7xf32>
  // Compute log(1 + exp(x)) = softplus(x)
  %softplus = stablehlo.log %exp_plus_one : tensor<6x7xf32>
  // Compute tanh(softplus(x))
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7xf32>
  // Compute mish(x) = x * tanh(softplus(x))
  %mish1 = stablehlo.multiply %linear_out, %tanh_softplus : tensor<6x7xf32>

  // Apply Mish again on %mish1
  %exp_mish1 = stablehlo.exponential %mish1 : tensor<6x7xf32>
  %exp_plus_one_2 = stablehlo.add %one_broadcast, %exp_mish1 : tensor<6x7xf32>
  %softplus_2 = stablehlo.log %exp_plus_one_2 : tensor<6x7xf32>
  %tanh_softplus_2 = stablehlo.tanh %softplus_2 : tensor<6x7xf32>
  %mish2 = stablehlo.multiply %mish1, %tanh_softplus_2 : tensor<6x7xf32>

  return %mish2 : tensor<6x7xf32>
}

func.func @main(%x: tensor<7x8xf32>, %i: tensor<i32>) -> tensor<3x8xf32> {
