  // Broadcast scalar 2.0 to [6x7]
  %t4 = "stablehlo.broadcast_in_dim"(%c_sub) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %t5 = stablehlo.subtract %t3, %t4 : tensor<6x7xf32>

  // Multiply by 1.5 (constant)
  %c_mul = stablehlo.constant dense<1.5> : tensor<f32>
  // Broadcast scalar 1.5 to [6x7]
  %t6 = "stablehlo.broadcast_in_dim"(%c_mul) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %t7 = stablehlo.multiply %t5, %t6 : tensor<6x7xf32>

