  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %t8 = "stablehlo.broadcast_in_dim"(%c_zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %t9 = stablehlo.maximum %t7, %t8 : tensor<6x7xf32>

