  %c_sub = stablehlo.constant dense<2.0> : tensor<f32>
  %c_sub_bcast = "stablehlo.broadcast_in_dim"(%c_sub) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %t4 = stablehlo.subtract %t3, %c_sub_bcast : tensor<6x7xf32>

  // Multiply by 1.5 (constant)
  %c_mul = stablehlo.constant dense<1.5> : tensor<f32>
  %c_mul_bcast = "stablehlo.broadcast_in_dim"(%c_mul) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
