func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<7x6x4x4xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x7x7x7xf32>) -> tensor<6x6x15x15xf32> {
