  %scaling_factor = constant dense<2.0> : tensor<f32>
  %scaling_broadcast = stablehlo.broadcast_in_dim %scaling_factor : tensor<f32> to tensor<6x6x15x15xf32> broadcast_dimensions = []
  %scaled = stablehlo.multiply %biased, %scaling_broadcast : tensor<6x6x15x15xf32>

