  // Dimension numbers for conv:
  // lhs (input): [N, C_in, H, W] = [6,7,7,7]
  // rhs (weight): [C_in, C_out, KH, KW] = [7,6,4,4]
  // output: [N, C_out, H_out, W_out] = [6,6,15,15]
  //
