  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
  %bias_broadcast_reshaped = stablehlo.reshape %bias_broadcast : (tensor<6x1x1x1xf32>) -> tensor<6x1x1x1xf32>
  // Now broadcast to conv shape [6x6x15x15]
  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%bias_broadcast_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x15x15xf32>
  %conv_plus_bias = stablehlo.add %conv, %bias_broadcast_full : tensor<6x6x15x15xf32>

  // Step 3: Apply softmax along channel dimension (dim=1)
  // Softmax(x) = exp(x) / sum(exp(x), dim)
  %exp = stablehlo.exponential %conv_plus_bias : tensor<6x6x15x15xf32>
  // Reduce sum over dim=1 (channels)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x1x15x15xf32>
  // Broadcast sum_exp to shape [6x6x15x15]
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x15x15xf32>) -> tensor<6x6x15x15xf32>
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x6x15x15xf32>

  // Step 4: Add bias (parameter %bias: tensor<6x1x1xf32>) to softmax output
  // Broadcast bias from [6x1x1] to [6x6x15x15]
  %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x1x1xf32>) -> tensor<6x1x1xf32>
  %bias_broadcast_full2 = "stablehlo.broadcast_in_dim"(%bias_broadcast2) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1xf32>) -> tensor<6x6x15x15xf32>
  %softmax_plus_bias = stablehlo.add %softmax, %bias_broadcast_full2 : tensor<6x6x15x15xf32>

  // Step 5: Multiply by scaling factor 2.0 (constant)
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scale to [6x6x15x15]
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
  %scaled = stablehlo.multiply %softmax_plus_bias, %scale_broadcast : tensor<6x6x15x15xf32>

  // Step 6: Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %scaled : tensor<6x6x15x15xf32>
  %exp_neg = stablehlo.exponential %neg : tensor<6x6x15x15xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
  %denom = stablehlo.add %one_broadcast, %exp_neg : tensor<6x6x15x15xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<6x6x15x15xf32>

  // Return final result
  return %sigmoid : tensor<6x6x15x15xf32>
}

func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<7x6x4x4xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x7x7x7xf32>) -> tensor<6x6x15x15xf32> {
  // %arg0 = bias: tensor<6x1x1xf32>
  // %arg1 = conv_transpose.weight: tensor<7x6x4x4xf32>
  // %arg2 = conv_transpose.bias: tensor<6xf32>
  // %arg3 = input: tensor<6x7x7x7xf32>

  // Step 1: Perform ConvTranspose2d with parameters:
  // in_channels=7, out_channels=6, kernel_size=4, stride=2, padding=1, output_padding=1
  // Input shape: [batch=6, in_channels=7, H=7, W=7]
  // Weight shape: [in_channels=7, out_channels=6, KH=4, KW=4]
  // Output shape: [6, 6, 15, 15]

  // ConvTranspose2d is implemented as a convolution with:
  // - input: %arg3 (6x7x7x7)
  // - kernel: %arg1 (7x6x4x4)
  // - strides: [2,2]
  // - padding: [1,1]
  // - output_padding: [1,1]
  // - dimension_numbers: input NHWC? No, StableHLO uses NCHW by default for conv.
  // But our tensors are in NCHW format: batch, channels, height, width.

  // StableHLO conv expects kernel shape: [KH, KW, IC, OC] for forward conv.
  // For conv_transpose, the weight shape is [IC, OC, KH, KW].
  // We must transpose weight to [KH, KW, OC, IC] for conv_transpose in StableHLO.
  // But StableHLO conv_transpose expects kernel shape [KH, KW, OC, IC].
  // So we need to permute %arg1 from [7,6,4,4] (IC, OC, KH, KW) to [4,4,6,7].

  %weight_perm = stablehlo.transpose %arg1 : tensor<7x6x4x4xf32> to tensor<4x4x6x7xf32> [2,3,1,0]

  // Define convolution dimension numbers for conv_transpose:
  // input: NCHW = [0,1,2,3]
  // kernel: HWIO = [0,1,2,3] (KH, KW, OC, IC)
  // output: NCHW = [0,1,2,3]

  // Create convolution dimension numbers attribute
  %dim_nums = stablehlo.conv_dimension_numbers {input_batch_dimension = 0 : i64,
                                               input_feature_dimension = 1 : i64,
                                               input_spatial_dimensions = [2, 3] : tensor<2xi64>,
                                               kernel_input_feature_dimension = 3 : i64,
                                               kernel_output_feature_dimension = 2 : i64,
                                               kernel_spatial_dimensions = [0, 1] : tensor<2xi64>,
                                               output_batch_dimension = 0 : i64,
                                               output_feature_dimension = 1 : i64,
                                               output_spatial_dimensions = [2, 3] : tensor<2xi64>} : stablehlo.conv_dimension_numbers

  // Set strides and paddings
  %strides = dense<2> : tensor<2xi64>
  %padding = dense<1> : tensor<1xi64>  // output_padding=1

  // StableHLO conv_transpose uses 'lhs_dilation' to implement stride in forward conv.
  // For conv_transpose, stride is implemented as lhs_dilation.
  // So lhs_dilation = stride = [2,2]
  %lhs_dilation = dense<2> : tensor<2xi64>

  // rhs_dilation = 1 (no dilation)
  %rhs_dilation = dense<1> : tensor<2xi64>

  // padding = [padding_low, padding_high] per spatial dim
  // padding=1 means padding_low=1, padding_high=1
  %padding_low = dense<1> : tensor<2xi64>
  %padding_high = dense<1> : tensor<2xi64>
  %padding_attr = dense<1> : tensor<2xi64>

  // StableHLO conv_transpose expects padding as array of pairs per spatial dim
  // So padding = [[1,1],[1,1]]
  %padding_tensor = dense<[[1,1],[1,1]]> : tensor<2x2xi64>

  // output_padding is handled by adjusting output shape or padding, but StableHLO conv_transpose does not have output_padding attribute.
  // We must adjust padding or output shape accordingly.
  // The output shape is known: [6,6,15,15]

  // Perform conv_transpose
  %conv = stablehlo.convolution_transpose %arg3, %weight_perm {
    strides = dense<1> : tensor<2xi64>, // strides ignored for conv_transpose
    padding = dense<[[1,1],[1,1]]> : tensor<2x2xi64>,
    lhs_dilation = dense<2> : tensor<2xi64>,
    rhs_dilation = dense<1> : tensor<2xi64>,
    dimension_numbers = %dim_nums,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = #stablehlo.default_precision_config
  } : (tensor<6x7x7x7xf32>, tensor<4x4x6x7xf32>) -> tensor<6x6x15x15xf32>

  // Step 2: Apply softmax along dim=1 (channel dimension)
  %softmax = stablehlo.softmax %conv {axis = 1 : i64} : tensor<6x6x15x15xf32> -> tensor<6x6x15x15xf32>

  // Step 3: Add bias (%arg0) to softmax output
  // %arg0 shape: [6,1,1]
  // Broadcast bias to [6,6,15,15]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<6x1x1xf32> to tensor<6x6x15x15xf32> broadcast_dimensions = [0]

  %add_bias = stablehlo.add %softmax, %bias_broadcast : tensor<6x6x15x15xf32>

  // Step 4: Multiply by scaling_factor = 2.0 (constant)
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scale to tensor<6x6x15x15xf32>
  %scale_broadcast = stablehlo.broadcast_in_dim %scale : tensor<f32> to tensor<6x6x15x15xf32> broadcast_dimensions = []

  %scaled = stablehlo.multiply %add_bias, %scale_broadcast : tensor<6x6x15x15xf32>

  // Step 5: Apply sigmoid
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x6x15x15xf32> broadcast_dimensions = []

  %neg_scaled = stablehlo.negate %scaled : tensor<6x6x15x15xf32>
  %exp_neg_scaled = stablehlo.exponential %neg_scaled : tensor<6x6x15x15xf32>
  %denominator = stablehlo.add %one_broadcast, %exp_neg_scaled : tensor<6x6x15x15xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denominator : tensor<6x6x15x15xf32>

  func.return %sigmoid : tensor<6x6x15x15xf32>
}

func.func @main(%arg0: tensor<16x16x16x16xf32>) -> tensor<16x16x1x1xf32> {
  // Constants for kernel size and stride (both 11)
  %c11 = constant 11 : index

  // Define window dimensions for reduce_window: [1, 1, 11, 11]
  %window_dims = constant dense<[1, 1, 11, 11]> : tensor<4xi64>

  // Define window strides: [1, 1, 11, 11]
  %window_strides = constant dense<[1, 1, 11, 11]> : tensor<4xi64>

  // Define padding: no padding [0,0,0,0,0,0,0,0]
  // StableHLO expects padding as tensor<8xi64> for 4D window: pairs of (low, high) per dimension
  %padding = constant dense<[0, 0, 0, 0, 0, 0, 0, 0]> : tensor<8xi64>

  // Compute the sum over each 11x11 window using reduce_window with add
  %init = constant 0.0 : f32
  %sum = stablehlo.reduce_window %arg0, %init {
    strides = [1, 1, 11, 11],
    padding = [0, 0, 0, 0, 0, 0, 0, 0],
    window_dimensions = [1, 1, 11, 11],
    base_dilation = [],
    window_dilation = [],
    // reduction function: add
    body {
      %a = stablehlo.parameter 0 : f32
      %b = stablehlo.parameter 1 : f32
      %c = stablehlo.add %a, %b : f32
      stablehlo.return %c : f32
    }
  } : (tensor<16x16x16x16xf32>, f32) -> tensor<16x16x1x1xf32>

  // Divide sum by kernel area (11*11=121) to get average
  %kernel_area = constant 121.0 : f32
  %avg = stablehlo.div %sum, %kernel_area : tensor<16x16x1x1xf32>

  stablehlo.return %avg : tensor<16x16x1x1xf32>
}

func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<7x6x4x4xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x7x7x7xf32>) -> tensor<6x6x15x15xf32> {
