  // %arg1 = conv_transpose.weight (7x6x4x4)
  // %arg2 = conv_transpose.bias (6)
  // %arg3 = input (6x7x7x7)

  // Step 1: Perform ConvTranspose2d with stride=2, padding=1, output_padding=1
  // ConvTranspose2d is implemented as a convolution with lhs_dilation=stride,
  // rhs_dilation=1, padding adjusted for output_padding.
  // Given:
  // input shape: [6,7,7,7] (N, C_in, H_in, W_in)
  // weight shape: [7,6,4,4] (C_in, C_out, KH, KW)
  // output shape: [6,6,15,15] (N, C_out, H_out, W_out)
  //
  // dimension_numbers for convolution:
  // input: [N, C_in, H, W] -> [b, i, h, w]
  // kernel: [C_in, C_out, KH, KW] -> [i, o, kh, kw]
  // output: [N, C_out, H_out, W_out] -> [b, o, h, w]
  //
  // For conv_transpose, lhs_dilation = stride = [2,2]
  // padding = [1,1] (padding on input)
  // output_padding = 1 means we add 1 to output size, so padding is adjusted accordingly.
  //
  // padding attribute is a dense tensor of shape [2,2] with low and high padding for height and width.
  // For conv_transpose, padding is usually:
  // padding = [[padding_top, padding_bottom], [padding_left, padding_right]]
  // Here, padding = 1 means padding 1 on both sides.
  //
  // We set:
  // window_strides = [1,1]
  // lhs_dilation = [2,2]
  // rhs_dilation = [1,1]
  // padding = [[1,1],[1,1]]
  //
