    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x7x7xf32>, tensor<7x6x4x4xf32>) -> tensor<6x6x15x15xf32>

  // Step 2: Apply softmax along dim=1 (channel dimension)
