  // Compute exp(x)
  %exp = stablehlo.exponential %conv : tensor<6x6x15x15xf32>

  // Compute sum of exp(x) along dim=1
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x15x15xf32>

  // Broadcast sum_exp back to shape of exp for division
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 2, 3>} : tensor<6x15x15xf32> -> tensor<6x6x15x15xf32>

  // Divide exp by sum_exp to get softmax
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x6x15x15xf32>

  // Step 3: Add bias (parameter %arg0) to softmax output
  // %arg0 shape: [6,1,1], need to broadcast to [6,6,15,15]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0, 1, 2>} : tensor<6x1x1xf32> -> tensor<6x6x15x15xf32>
  %add_bias = stablehlo.add %softmax, %bias_broadcast : tensor<6x6x15x15xf32>

  // Step 4: Multiply by scaling factor (2.0)
  // scaling_factor = 2.0, create constant scalar tensor
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scale to output shape
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : tensor<f32> -> tensor<6x6x15x15xf32>
  %scaled = stablehlo.multiply %add_bias, %scale_broadcast : tensor<6x6x15x15xf32>

  // Step 5: Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %scaled : tensor<6x6x15x15xf32>
  %exp_neg = stablehlo.exponential %neg : tensor<6x6x15x15xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : tensor<f32> -> tensor<6x6x15x15xf32>
  %denom = stablehlo.add %one_broadcast, %exp_neg : tensor<6x6x15x15xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<6x6x15x15xf32>

  return %sigmoid : tensor<6x6x15x15xf32>
}

