func.func @main(%arg0: tensor<16x16x16x16xf32>) -> tensor<16x16x1x1xf32> {
  // Constants for pooling parameters
  %c11_i32 = constant 11 : i32
  %c0_i32 = constant 0 : i32
  %c1_i32 = constant 1 : i32

  // Convert constants to index type for window dimensions and strides
  %c11_idx = index_cast %c11_i32 : i32 to index
  %c1_idx = index_cast %c1_i32 : i32 to index
  %c0_idx = index_cast %c0_i32 : i32 to index

  // Define window dimensions for reduce_window: [1,1,kernel_h,kernel_w]
  // Pooling only over height and width dimensions (dims 2 and 3)
  %window_dims = tensor.from_elements %c1_idx, %c1_idx, %c11_idx, %c11_idx : tensor<4xindex>

  // Define window strides: [1,1,1,1]
  %window_strides = tensor.from_elements %c1_idx, %c1_idx, %c1_idx, %c1_idx : tensor<4xindex>

  // Define padding: no padding, so all zeros
  // Padding is a tensor<4x2xindex> for low and high padding per dimension
  %pad_low = tensor.from_elements %c0_idx, %c0_idx, %c0_idx, %c0_idx : tensor<4xindex>
  %pad_high = tensor.from_elements %c0_idx, %c0_idx, %c0_idx, %c0_idx : tensor<4xindex>
  %padding = tensor.from_elements %pad_low, %pad_high : tensor<2x4xindex>
  // But StableHLO expects padding as tensor<4x2xindex>, so transpose:
  %padding_4_2 = tensor.empty() : tensor<4x2xindex>
  %padding_4_2 = tensor.insert_slice %pad_low into %padding_4_2[%c0_idx, %c0_idx] : tensor<4xindex> into tensor<4x2xindex>
  %padding_4_2 = tensor.insert_slice %pad_high into %padding_4_2[%c0_idx, %c1_idx] : tensor<4xindex> into tensor<4x2xindex>

  // But StableHLO reduce_window expects padding as tensor<4x2xi64>, so we must create a constant tensor<4x2xi64>
  // We'll create the padding constant directly as a dense elements attribute:
  %padding_const = constant dense<[[0,0],[0,0],[0,0],[0,0]]> : tensor<4x2xi64>

  // Compute the sum over the window using reduce_window with add
  %zero = constant 0.0 : f32
  %sum = stablehlo.reduce_window %arg0, %zero {
    strides = [1, 1, 1, 1],
    padding = [[0, 0], [0, 0], [0, 0], [0, 0]],
    window_dimensions = [1, 1, 11, 11],
    base_dilation = [],
    window_dilation = [],
    // The reduction function is addition
  } : tensor<16x16x16x16xf32> -> tensor<16x16x6x6xf32>

  // Compute divisor = kernel_size * kernel_size = 11*11 = 121.0
  %c121 = constant 121.0 : f32

  // Broadcast divisor to output shape [16,16,6,6]
  %divisor_broadcast = stablehlo.broadcast_in_dim %c121 : f32 to tensor<16x16x6x6xf32> dimensions = [0,1,2,3]

  // Divide sum by divisor to get average pooling output
  %avg = stablehlo.div %sum, %divisor_broadcast : tensor<16x16x6x6xf32>

  // Now we need to reshape or slice to get output shape tensor<16x16x1x1xf32>
  // The PyTorch AvgPool2d with kernel=11, stride=1, padding=0 on 16x16 input produces output size:
  // output_size = floor((input + 2*padding - kernel)/stride) + 1 = floor((16 + 0 - 11)/1) + 1 = 6
  // So output shape is [16,16,6,6]
  // We must reduce this to [16,16,1,1] by further pooling or slicing.

  // The PyTorch code returns output shape [16,16,6,6], but the task requires output shape [16,16,1,1]
  // So we must do a second average pooling over the 6x6 output to get 1x1 output.

  // Second average pooling over height and width with kernel=6, stride=1, padding=0

  // Define second window dims: [1,1,6,6]
  %window_dims2 = tensor.from_elements %c1_idx, %c1_idx, %c6_idx, %c6_idx : tensor<4xindex>
  // But we don't have %c6_idx yet, define it:
  %c6_i32 = constant 6 : i32
  %c6_idx = index_cast %c6_i32 : i32 to index

  // Define second window strides: [1,1,1,1]
  %window_strides2 = tensor.from_elements %c1_idx, %c1_idx, %c1_idx, %c1_idx : tensor<4xindex>

  // Padding zero again
  %padding_const2 = constant dense<[[0,0],[0,0],[0,0],[0,0]]> : tensor<4x2xi64>

  // Zero init for reduce_window
  %zero2 = constant 0.0 : f32

  // Second reduce_window sum
  %sum2 = stablehlo.reduce_window %avg, %zero2 {
    strides = [1, 1, 1, 1],
    padding = [[0, 0], [0, 0], [0, 0], [0, 0]],
    window_dimensions = [1, 1, 6, 6],
    base_dilation = [],
    window_dilation = [],
  } : tensor<16x16x6x6xf32> -> tensor<16x16x1x1xf32>

  // Divisor for second pooling = 6*6=36.0
  %c36 = constant 36.0 : f32

