  %divisor_broadcast2 = stablehlo.broadcast_in_dim %c36 : f32 to tensor<16x16x1x1xf32> dimensions = [0,1,2,3]

  // Divide sum2 by divisor2 to get final average pooling output
  %avg2 = stablehlo.div %sum2, %divisor_broadcast2 : tensor<16x16x1x1xf32>

  return %avg2 : tensor<16x16x1x1xf32>
}

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = scale (7)
  // %arg1 = gemm.weight (7x7)
  // %arg2 = gemm.bias (7)
  // %arg3 = bn.weight (7)
  // %arg4 = bn.bias (7)
  // %arg5 = input (6x7)

  // Step 1: GEMM: x = input @ weight^T + bias
  // gemm.weight shape: [7,7], input shape: [6,7]
  // We want: output shape [6,7] = input [6,7] * weight^T [7,7]
  // So dot_general with contracting dims: input dim 1 and weight dim 1
  // But weight needs to be transposed to get weight^T

  %weight_t = stablehlo.transpose %arg1 : tensor<7x7xf32> to tensor<7x7xf32> {permutation = [1, 0]}

  %dot = stablehlo.dot_general %arg5, %weight_t {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias (broadcast bias from [7] to [6,7])
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %x1 = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

