  // scale shape: [7], broadcast to [6,7]
  %scale_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %x2 = stablehlo.multiply %x1, %scale_broadcast : tensor<6x7xf32>

  // Step 3: BatchNorm1d in training mode
  // BatchNorm1d normalizes over batch dimension (dim 0)
  // Compute mean and variance over batch dimension (dim 0) for each feature (dim 1)

  // Compute mean over dim 0: result shape [7]
  %dim0 = stablehlo.constant dense<0> : tensor<i64>
  %mean = stablehlo.reduce %x2, %cst0 = stablehlo.constant dense<0.0> : tensor<6x7xf32>, tensor<f32> {
    dimensions = [0]
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute variance: mean of squared differences
  // First compute (x - mean)^2

  // Broadcast mean [7] to [6,7]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %diff = stablehlo.subtract %x2, %mean_broadcast : tensor<6x7xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  // Compute variance = mean of sq_diff over dim 0
  %variance = stablehlo.reduce %sq_diff, %cst0 : tensor<6x7xf32>, tensor<f32> {
    dimensions = [0]
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

