  %eps = stablehlo.constant dense<1.00000001e-5> : tensor<f32>

  // variance + eps
  %var_eps = stablehlo.add %variance, %eps : tensor<7xf32>

  // rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) * inv_std
  %norm = stablehlo.multiply %diff, %inv_std_broadcast = stablehlo.broadcast_in_dim %inv_std : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1] : tensor<6x7xf32>

