  // %arg1: gemm.weight, shape [7,7]
  // %arg2: gemm.bias, shape [7]
  // %arg0: scale, shape [7]
  // %arg3: bn.weight, shape [7]
  // %arg4: bn.bias, shape [7]

  // Step 1: GEMM: x @ weight^T + bias
  // gemm.weight shape is [7,7], we want to do x [6,7] * weight^T [7,7]
  // So transpose gemm.weight to get [7,7] (actually same shape, but we must transpose)
