  // BatchNorm1d normalizes over batch dimension (dim=0) for each feature (dim=1)
  // Compute mean over batch dim=0: result shape [7]
  %mean = stablehlo.reduce %scaled, %c0_f32 : tensor<6x7xf32>, tensor<f32> {
