  %var = stablehlo.reduce %diff_sq, %c0_f32 : tensor<6x7xf32>, tensor<f32> {
    ^bb0(%arg_lhs: f32, %arg_rhs: f32):
      %add = stablehlo.add %arg_lhs, %arg_rhs : f32
      stablehlo.return %add : f32
  } reduce_dimensions = [0]

  // Divide sum by batch_size=6 to get mean
  %c6 = stablehlo.constant dense<6.0> : tensor<f32>
  %var_mean = stablehlo.divide %var, %c6 : tensor<7xf32>

  // Add eps=1e-5 to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<7xf32> broadcast_dimensions = []
  %var_eps = stablehlo.add %var_mean, %eps_broadcast : tensor<7xf32>

