  %inv_std_broadcast = stablehlo.broadcast_in_dim %inv_std : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %normalized = stablehlo.multiply %diff, %inv_std_broadcast : tensor<6x7xf32>

