  // dot_general with contracting dims: x: [16,16], gemm.weight: [16,16]
  // Contract dimension 1 of x with dimension 1 of gemm.weight (gemm.weight is [out,in], so transpose needed)
  // We want x @ W^T, so dot_general contracting x dim 1 and gemm.weight dim 1, batch dims none
  // But gemm.weight is [16,16], we want to contract x dim 1 with gemm.weight dim 1, so gemm.weight dim 1 is input dim
  // So dot_general contracting dims = [(1,1)], batch dims = []
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast gemm.bias [16] to [16,16] on dim 1
  %1 = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

  // GroupNorm:
  // Parameters:
  // num_groups = 16, so each group has 1 channel (16 channels total)
  // Input shape: [batch=16, channels=16]
  // GroupNorm computes mean and variance per group per batch element.
  // Reshape input to [batch=16, groups=16, channels_per_group=1]
  %3 = stablehlo.reshape %2 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over channels_per_group dim (dim=2)
  %4 = stablehlo.reduce %3, %cst0 = stablehlo.constant 0.0 : tensor<f32> {
    dimensions = [2]
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16xf32>

  // mean = sum / channels_per_group (1)
  // channels_per_group = 1, so mean = sum
  %mean = %4

  // Compute variance: mean of squared difference
  // diff = x - mean (broadcast mean to shape [16,16,1])
  %5 = stablehlo.broadcast_in_dim %mean : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]
  %6 = stablehlo.subtract %3, %5 : tensor<16x16x1xf32>

  // square diff
  %7 = stablehlo.multiply %6, %6 : tensor<16x16x1xf32>

  // reduce mean over channels_per_group dim (dim=2)
  %8 = stablehlo.reduce %7, %cst0 : tensor<f32> {
    dimensions = [2]
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16xf32>

  // variance = mean of squared diff (channels_per_group=1)
  %variance = %8

  // epsilon for numerical stability
  %c_eps = stablehlo.constant 1.000000e-05 : f32

  // variance + epsilon
  %9 = stablehlo.add %variance, %c_eps : tensor<16x16xf32>

  // rsqrt(variance + epsilon)
  %10 = stablehlo.rsqrt %9 : tensor<16x16xf32>

  // normalize: (x - mean) * rsqrt(var + eps)
  %11 = stablehlo.multiply %6, stablehlo.broadcast_in_dim %10 : tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  // reshape normalized back to [16,16]
  %12 = stablehlo.reshape %11 : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias (both shape [16])
  // Broadcast weight and bias to [16,16] on dim 1
  %13 = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %14 = stablehlo.multiply %12, %13 : tensor<16x16xf32>
  %15 = stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %16 = stablehlo.add %14, %15 : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %16 : tensor<16x16xf32>
  %exp = stablehlo.exp %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %denom = stablehlo.add %one_broadcast, %exp : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<16x16xf32>
  %17 = stablehlo.multiply %16, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (shape [16]) broadcast on dim 1
  %18 = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %19 = stablehlo.multiply %17, %18 : tensor<16x16xf32>

  // Swish again: x * sigmoid(x)
  %neg2 = stablehlo.negate %19 : tensor<16x16xf32>
  %exp2 = stablehlo.exp %neg2 : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_broadcast, %exp2 : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_broadcast, %denom2 : tensor<16x16xf32>
  %20 = stablehlo.multiply %19, %sigmoid2 : tensor<16x16xf32>

  // Return final output
  stablehlo.return %20 : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape [16,16]
  // %arg1: gemm.weight, shape [16,16]
  // %arg2: gemm.bias, shape [16]
  // %arg3: group_norm.weight, shape [16]
  // %arg4: group_norm.bias, shape [16]
  // %arg0: multiply_weight, shape [16]

  // GEMM: x @ weight^T + bias
  // dot_general with contracting dims: x: [16,16], weight: [16,16]
  // Contract dimension 1 of x with dimension 1 of weight (weight is transposed)
  // So we transpose weight to [16,16] -> [16,16] (actually weight is [16,16], but we want weight^T)
  // We'll transpose weight to get weight^T: [16,16] -> [16,16] (swap dims)
  %weight_t = stablehlo.transpose %arg1 : tensor<16x16xf32> to tensor<16x16xf32> [1, 0]

  %dot = stablehlo.dot_general %arg5, %weight_t {
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias [16] to [16,16] on dim 1
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %x1 = stablehlo.add %dot, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm:
  // num_groups = 16, so each group has 1 channel (since out_features=16)
  // Reshape x1 [16,16] -> [16,16,1] to add group dim
  %x1_reshape = stablehlo.reshape %x1 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over group channels (dim=2)
  %mean = stablehlo.reduce %x1_reshape, %c0 : tensor<16x16x1xf32>, tensor<f32> {
    ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>):
      %add = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  } reduce_dims = [2]

  // mean shape: [16,16]
  // Compute variance: mean of (x - mean)^2 over dim=2
  // Broadcast mean to [16,16,1]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  %diff = stablehlo.subtract %x1_reshape, %mean_broadcast : tensor<16x16x1xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  %var = stablehlo.reduce %sq, %c0 : tensor<16x16x1xf32>, tensor<f32> {
    ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>):
      %add = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  } reduce_dims = [2]

  // variance shape: [16,16]

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant 1.000000e-05 : f32
  %eps_tensor = stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %var_eps = stablehlo.add %var, %eps_tensor : tensor<16x16xf32>
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Broadcast rsqrt_var to [16,16,1]
  %rsqrt_var_broadcast = stablehlo.broadcast_in_dim %rsqrt_var : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  %norm = stablehlo.multiply %diff, %rsqrt_var_broadcast : tensor<16x16x1xf32>

  // Reshape norm back to [16,16]
  %norm_reshape = stablehlo.reshape %norm : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias (both shape [16])
  // Broadcast weight and bias to [16,16] on dim 1
  %weight_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %bias_gn_broadcast = stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %norm_reshape, %weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_gn_broadcast : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %shifted : tensor<16x16xf32>
  %exp = stablehlo.exp %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %denom = stablehlo.add %one_broadcast, %exp : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<16x16xf32>
  %swish1 = stablehlo.multiply %shifted, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (shape [16]), broadcast on dim 1
  %multiply_weight_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %multiplied = stablehlo.multiply %swish1, %multiply_weight_broadcast : tensor<16x16xf32>

  // Swish again
  %neg2 = stablehlo.negate %multiplied : tensor<16x16xf32>
  %exp2 = stablehlo.exp %neg2 : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_broadcast, %exp2 : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_broadcast, %denom2 : tensor<16x16xf32>
  %swish2 = stablehlo.multiply %multiplied, %sigmoid2 : tensor<16x16xf32>

  stablehlo.return %swish2 : tensor<16x16xf32>
}

// Constants used in reductions
// zero constant for reduce initial value
// We define it outside the function for clarity, but StableHLO allows inside function constants.
func.func @c0() -> tensor<f32> {
  %c = stablehlo.constant dense<0.0> : tensor<f32>
  stablehlo.return %c : tensor<f32>
}

func.func @main(%multiply_weight: tensor<16xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %group_norm_weight: tensor<16xf32>, %group_norm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // GEMM: x = input @ gemm_weight^T + gemm_bias
  // gemm_weight shape: [16,16], we need to transpose to [16,16] (actually same shape, but transpose dims)
  %gemm_weight_t = "stablehlo.transpose"(%gemm_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %x = "stablehlo.dot_general"(%input, %gemm_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_bias = stablehlo.broadcast_in_dim %gemm_bias {broadcast_dimensions = array<i64: 1} : tensor<16xf32> -> tensor<16x16xf32>
  %x1 = stablehlo.add %x, %x_bias : tensor<16x16xf32>

  // GroupNorm: normalize x1 over groups
  // GroupNorm with num_groups=16, out_features=16 means each group has 1 channel (16/16=1)
  // So group norm is per channel normalization (per feature dim)
  // Compute mean over group elements (here group size=1, so mean = x1 itself)
  // But batch norm is over batch dimension, group norm normalizes over groups and spatial dims
  // Here input shape is [batch=16, channels=16]
  // GroupNorm reshapes to [batch, groups, channels_per_group] = [16,16,1]
  // Then compute mean and variance over axis=2 (channels_per_group)
  // Then normalize, then scale and shift by group_norm_weight and group_norm_bias (broadcasted)

  // Reshape x1 to [16,16,1]
  %x1_reshaped = stablehlo.reshape %x1 : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over last dim (axis=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x1_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2}} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // mean shape: [16,16]

  // Compute variance: mean of (x - mean)^2 over axis=2
  // Broadcast mean to [16,16,1]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean {broadcast_dimensions = array<i64: 0, 1} : tensor<16x16xf32> -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %x1_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %zero_f32_2 = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32_2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %sum2 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2}} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<16x16xf32>
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev {broadcast_dimensions = array<i64: 0, 1} : tensor<16x16xf32> -> tensor<16x16x1xf32>
  %normalized = stablehlo.divide %diff, %stddev_broadcast : tensor<16x16x1xf32>

  // Reshape normalized back to [16,16]
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Scale and shift: normalized * group_norm_weight + group_norm_bias
  %weight_broadcast = stablehlo.broadcast_in_dim %group_norm_weight {broadcast_dimensions = array<i64: 1} : tensor<16xf32> -> tensor<16x16xf32>
  %bias_broadcast = stablehlo.broadcast_in_dim %group_norm_bias {broadcast_dimensions = array<i64: 1} : tensor<16xf32> -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %normalized_reshaped, %weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_broadcast : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_shifted = stablehlo.negate %shifted : tensor<16x16xf32>
  %exp_neg = stablehlo.exponential %neg_shifted : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64: } : tensor<f32> -> tensor<16x16xf32>
  %denom = stablehlo.add %one_broadcast, %exp_neg : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<16x16xf32>
  %swish1 = stablehlo.multiply %shifted, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (broadcast multiply_weight from [16] to [16x16])
  %multiply_weight_broadcast = stablehlo.broadcast_in_dim %multiply_weight {broadcast_dimensions = array<i64: 1} : tensor<16xf32> -> tensor<16x16xf32>
  %multiplied = stablehlo.multiply %swish1, %multiply_weight_broadcast : tensor<16x16xf32>

  // Swish again: multiplied * sigmoid(multiplied)
  %neg_multiplied = stablehlo.negate %multiplied : tensor<16x16xf32>
  %exp_neg_multiplied = stablehlo.exponential %neg_multiplied : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_broadcast, %exp_neg_multiplied : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_broadcast, %denom2 : tensor<16x16xf32>
  %swish2 = stablehlo.multiply %multiplied, %sigmoid2 : tensor<16x16xf32>

  "stablehlo.return"(%swish2) : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape [16,16]
  // %arg1: gemm.weight, shape [16,16]
  // %arg2: gemm.bias, shape [16]
  // %arg3: group_norm.weight, shape [16]
  // %arg4: group_norm.bias, shape [16]
  // %arg0: multiply_weight, shape [16]

  // GEMM: x @ gemm.weight^T + gemm.bias
  // gemm.weight shape is [16,16], we want to do x @ gemm.weight^T
  // So transpose gemm.weight to [16,16] (transpose dims [1,0])
  %gemm_weight_t = stablehlo.transpose %arg1 {permutation = dense<[1,0]> : tensor<2xi64>} : tensor<16x16xf32> -> tensor<16x16xf32>
  %gemm_out = stablehlo.dot_general %arg5, %gemm_weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias (broadcast bias from [16] to [16x16])
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2
    {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : tensor<16xf32> -> tensor<16x16xf32>
  %gemm_out_bias = stablehlo.add %gemm_out, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm:
  // GroupNorm with num_groups=16, out_features=16, so each group has 1 channel.
  // Input shape: [batch=16, channels=16]
  // Reshape to [batch=16, groups=16, channels_per_group=1]
  %reshape1 = stablehlo.reshape %gemm_out_bias : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Compute mean over channels_per_group dimension (dim=2)
  %zero_f32 = stablehlo.constant 0.0 : tensor<f32>
  %mean = stablehlo.reduce %reshape1, %zero_f32 (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  ) {dimensions = dense<[2]> : tensor<1xi64>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean = sum / channels_per_group (1)
  %channels_per_group_f32 = stablehlo.constant 1.0 : tensor<f32>
  %mean_scaled = stablehlo.divide %mean, %channels_per_group_f32 : tensor<16x16xf32>

  // Subtract mean: x - mean
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_scaled
    {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>} : tensor<16x16xf32> -> tensor<16x16x1xf32>
  %x_centered = stablehlo.subtract %reshape1, %mean_broadcast : tensor<16x16x1xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<16x16x1xf32>
  %var = stablehlo.reduce %x_centered_sq, %zero_f32 (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  ) {dimensions = dense<[2]> : tensor<1xi64>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // var = sum / channels_per_group (1)
  %var_scaled = stablehlo.divide %var, %channels_per_group_f32 : tensor<16x16xf32>

  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant 1.0e-5 : tensor<f32>
  %epsilon_broadcast = stablehlo.broadcast_in_dim %epsilon
    {broadcast_dimensions = dense<> : tensor<0xi64>} : tensor<f32> -> tensor<16x16xf32>
  %var_eps = stablehlo.add %var_scaled, %epsilon_broadcast : tensor<16x16xf32>

  // Compute rsqrt(variance + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Broadcast inv_std to [16x16x1]
  %inv_std_broadcast = stablehlo.broadcast_in_dim %inv_std
    {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>} : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std_broadcast : tensor<16x16x1xf32>

  // Reshape back to [16x16]
  %x_norm_reshaped = stablehlo.reshape %x_norm : tensor<16x16x1xf32> -> tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias (both shape [16])
  // Broadcast weight and bias to [16x16]
  %weight_broadcast = stablehlo.broadcast_in_dim %arg3
    {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : tensor<16xf32> -> tensor<16x16xf32>
  %bias_gn_broadcast = stablehlo.broadcast_in_dim %arg4
    {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : tensor<16xf32> -> tensor<16x16xf32>

  // x_norm * weight + bias
  %weighted = stablehlo.multiply %x_norm_reshaped, %weight_broadcast : tensor<16x16xf32>
  %group_norm_out = stablehlo.add %weighted, %bias_gn_broadcast : tensor<16x16xf32>

  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %group_norm_out : tensor<16x16xf32>
  %exp_neg = stablehlo.exponential %neg : tensor<16x16xf32>
