  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x16x13x4x4xf32>
  %relu6_part1 = "stablehlo.maximum"(%x_plus_3, %zero) : tensor<6x16x13x4x4xf32>
  %relu6 = "stablehlo.minimum"(%relu6_part1, %six_broadcast) : tensor<6x16x13x4x4xf32>
  %relu6_div_6 = stablehlo.divide %relu6, %six_broadcast : tensor<6x16x13x4x4xf32>
  %hardswish = stablehlo.multiply %conv_bias_added, %relu6_div_6 : tensor<6x16x13x4x4xf32>

  // 4. GroupNorm
  // GroupNorm with num_groups=4, channels=16
  // Reshape to (N, G, C//G, D, H, W) = (6,4,4,13,4,4)
  %reshape1 = stablehlo.reshape %hardswish : (tensor<6x16x13x4x4xf32>) -> tensor<6x4x4x13x4x4xf32>

  // Compute mean over axes [2,3,4,5] (C//G, D, H, W)
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4, 5>} : (tensor<6x4x4x13x4x4xf32>, tensor<f32>) -> tensor<6x4xf32>

  // Compute count = 4*13*4*4 = 832 as constant
  %count = stablehlo.constant dense<832.0> : tensor<f32>
  %count_broadcast = "stablehlo.broadcast_in_dim"(%count) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x4xf32>
  %mean_div = stablehlo.divide %mean, %count_broadcast : tensor<6x4xf32>

  // Compute variance: mean of squared differences
  %reshape1_broadcast_mean = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4, 5>} : (tensor<6x4xf32>) -> tensor<6x4x4x13x4x4xf32>
  %diff = stablehlo.subtract %reshape1, %reshape1_broadcast_mean : tensor<6x4x4x13x4x4xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x4x4x13x4x4xf32>
