  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4, 5>} : (tensor<6x4x4x13x4x4xf32>, tensor<f32>) -> tensor<6x4xf32>
  %var = stablehlo.divide %var_sum, %count_broadcast : tensor<6x4xf32>

