  %epsilon = stablehlo.constant dense<1e-5> : tensor<f32>
  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x4xf32>
  %var_eps = stablehlo.add %var, %epsilon_broadcast : tensor<6x4xf32>

  // rsqrt variance
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<6x4xf32>

  // Normalize: (x - mean) * rsqrt_var
  %rsqrt_var_broadcast = "stablehlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4, 5>} : (tensor<6x4xf32>) -> tensor<6x4x4x13x4x4xf32>
  %diff_norm = stablehlo.multiply %diff, %rsqrt_var_broadcast : tensor<6x4x4x13x4x4xf32>

  // Reshape gn_weight and gn_bias from (16) to (4,4)
  %gn_weight_reshaped = stablehlo.reshape %gn_weight : (tensor<16xf32>) -> tensor<4x4xf32>
  %gn_bias_reshaped = stablehlo.reshape %gn_bias : (tensor<16xf32>) -> tensor<4x4xf32>

  // Broadcast gn_weight and gn_bias to (6x4x4x13x4x4)
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight_reshaped) {broadcast_dimensions = array<i64: 1, 2>} : (tensor<4x4xf32>) -> tensor<1x4

func.func @main(%arg0: tensor<16x3x4x4x4xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<6x3x16x7x7xf32>) -> tensor<6x16xf32> {
  // %arg0: conv.weight: [out_channels=16, in_channels=3, kernel_d=4, kernel_h=4, kernel_w=4]
  // %arg1: conv.bias: [16]
  // %arg2: group_norm.weight: [16]
  // %arg3: group_norm.bias: [16]
  // %arg4: input: [batch=6, in_channels=3, depth=16, height=7, width=7]

  // Convolution parameters:
  // input: [6,3,16,7,7]
  // weight: [16,3,4,4,4]
  // bias: [16]
  // stride=1, padding=0, dilation=1, groups=1

  // Perform convolution: output shape = [6,16,13,4,4]
  // Calculation of output dims:
  // D_out = floor((16 - 4)/1 + 1) = 13
  // H_out = floor((7 - 4)/1 + 1) = 4
  // W_out = floor((7 - 4)/1 + 1) = 4

  // conv3d
  %conv = stablehlo.convolution %arg4, %arg0 {
    window_strides = [1, 1, 1],
    padding = [0, 0, 0, 0, 0, 0],
    lhs_dilate = [1, 1, 1],
    rhs_dilate = [1, 1, 1],
    dimension_numbers = #stablehlo.conv_3d_dim_numbers,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {},
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x4x4x4xf32>) -> tensor<6x16x13x4x4xf32>

  // Add bias: broadcast bias [16] to [6,16,13,4,4]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x16x13x4x4xf32>

  // HardSwish activation: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)

  // Compute x + 3
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %three_bcast = stablehlo.broadcast_in_dim %three : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %x_plus_3 = stablehlo.add %conv_bias, %three_bcast : tensor<6x16x13x4x4xf32>

  // max(x+3, 0)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %relu_part = stablehlo.maximum %x_plus_3, %zero_bcast : tensor<6x16x13x4x4xf32>

  // min(relu_part, 6)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = stablehlo.broadcast_in_dim %six : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %relu6 = stablehlo.minimum %relu_part, %six_bcast : tensor<6x16x13x4x4xf32>

  // multiply x * relu6
  %hardswish_num = stablehlo.multiply %conv_bias, %relu6 : tensor<6x16x13x4x4xf32>

  // divide by 6
  %hardswish = stablehlo.divide %hardswish_num, %six_bcast : tensor<6x16x13x4x4xf32>

  // GroupNorm:
  // num_groups=4, channels=16
  // reshape input to [6,4,4,13,4,4] to group channels
  // compute mean and variance over axes [3,4,5,2] (spatial + channels per group)
  // axes for mean/var: D=13, H=4, W=4, and channels per group=4
  // axes = [2,3,4,5] in [batch, groups, channels_per_group, D, H, W]

  // Reshape [6,16,13,4,4] -> [6,4,4,13,4,4]
  %reshape_gn = stablehlo.reshape %hardswish : tensor<6x16x13x4x4xf32> to tensor<6x4x4x13x4x4xf32>

  // Compute mean over axes [2,3,4,5]
  %mean = stablehlo.reduce %reshape_gn, %zero {
    dimensions = [2, 3, 4, 5],
    body = {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x4x4x13x4x4xf32>, tensor<f32>) -> tensor<6x4xf32>

  // Compute variance:
  // variance = mean((x - mean)^2)
  // Broadcast mean to shape [6,4,4,13,4,4]
  %mean_bcast = stablehlo.broadcast_in_dim %mean : tensor<6x4xf32> to tensor<6x4x4x13x4x4xf32> broadcast_dimensions = [0,1]

  // x - mean
  %diff = stablehlo.subtract %reshape_gn, %mean_bcast : tensor<6x4x4x13x4x4xf32>

  // square (diff)^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x4x4x13x4x4xf32>

  // reduce mean of diff_sq over axes [2,3,4,5]
  %var = stablehlo.reduce %diff_sq, %zero {
    dimensions = [2, 3, 4, 5],
    body = {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x4x4x13x4x4xf32>, tensor<f32>) -> tensor<6x4xf32>

  // Compute inv_std = rsqrt(var + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_bcast = stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<6x4xf32> broadcast_dimensions = []

  %var_eps = stablehlo.add %var, %eps_bcast : tensor<6x4xf32>
  %inv_std = stablehlo.rsqrt %var_eps : tensor<6x4xf32>

  // Normalize: (x - mean) * inv_std
  %inv_std_bcast = stablehlo.broadcast_in_dim %inv_std : tensor<6x4xf32> to tensor<6x4x4x13x4x4xf32> broadcast_dimensions = [0,1]
  %norm = stablehlo.multiply %diff, %inv_std_bcast : tensor<6x4x4x13x4x4xf32>

  // Reshape norm back to [6,16,13,4,4]
  %norm_reshaped = stablehlo.reshape %norm : tensor<6x4x4x13x4x4xf32> to tensor<6x16x13x4x4xf32>

  // Apply affine transform: output = norm * weight + bias
  // weight and bias shape: [16]
  // Broadcast weight and bias to [6,16,13,4,4]
  %weight_bcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = [1]
  %bias_gn_bcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %norm_reshaped, %weight_bcast : tensor<6x16x13x4x

func.func @main(%arg0: tensor<16x3x4x4x4xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<6x3x16x7x7xf32>) -> tensor<6x16xf32> {
  // %arg0: conv.weight: [out_channels=16, in_channels=3, kD=4, kH=4, kW=4]
  // %arg1: conv.bias: [16]
  // %arg2: group_norm.weight: [16]
  // %arg3: group_norm.bias: [16]
  // %arg4: input: [batch=6, in_channels=3, depth=16, height=7, width=7]

  // Convolution parameters:
  // stride = 1, padding = 0, dilation = 1, groups = 1 (default)
  // Output shape: [6,16,13,4,4]
  // Calculation:
  // D_out = (16 - 4)/1 + 1 = 13
  // H_out = (7 - 4)/1 + 1 = 4
  // W_out = (7 - 4)/1 + 1 = 4

  // Perform convolution
  %conv = stablehlo.convolution %arg4, %arg0 {
    window_strides = [1, 1, 1],
    padding = [0, 0, 0, 0, 0, 0],
    lhs_dilate = [],
    rhs_dilate = [],
    feature_group_count = 1,
    batch_group_count = 1,
    dimension_numbers = #stablehlo.conv_dnums_5d,
    precision_config = #stablehlo.default_precision_config
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x4x4x4xf32>) -> tensor<6x16x13x4x4xf32>

  // Add bias: broadcast bias [16] to [6,16,13,4,4]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x16x13x4x4xf32>

  // HardSwish activation: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)

  // Compute x + 3
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %three_bcast = stablehlo.broadcast_in_dim %three : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %x_plus_3 = stablehlo.add %conv_bias, %three_bcast : tensor<6x16x13x4x4xf32>

  // max(x+3, 0)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %relu_part1 = stablehlo.maximum %x_plus_3, %zero_bcast : tensor<6x16x13x4x4xf32>

  // min(max(x+3,0), 6)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = stablehlo.broadcast_in_dim %six : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %relu6 = stablehlo.minimum %relu_part1, %six_bcast : tensor<6x16x13x4x4xf32>

  // Multiply x * relu6(x+3)
  %hardswish_num = stablehlo.multiply %conv_bias, %relu6 : tensor<6x16x13x4x4xf32>

  // Divide by 6
  %six_scalar = stablehlo.constant dense<6.0> : tensor<f32>
  %six_scalar_bcast = stablehlo.broadcast_in_dim %six_scalar : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %hardswish = stablehlo.divide %hardswish_num, %six_scalar_bcast : tensor<6x16x13x4x4xf32>

  // GroupNorm:
  // num_groups=4, channels=16
  // Reshape to [N, G, C_per_group, D, H, W] = [6,4,4,13,4,4]
  %shape = stablehlo.constant dense<[6,4,4,13,4,4]> : tensor<6xi64>
  %hardswish_reshaped = stablehlo.reshape %hardswish : tensor<6x16x13x4x4xf32> to tensor<6x4x4x13x4x4xf32>

  // Compute mean and variance over axes [2,3,4,5] (C_per_group, D, H, W)
  // axes = [2,3,4,5]
  %axes = stablehlo.constant dense<[2,3,4,5]> : tensor<4xi64>

  // Compute mean
  %mean = stablehlo.reduce %hardswish_reshaped init_tensor(%zero) dimensions = [2,3,4,5] : tensor<6x4x4x13x4x4xf32> -> tensor<6x4xf32> {
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  }

  // Compute count = 4*13*4*4 = 832 as f32
  %count = stablehlo.constant dense<832.0> : tensor<f32>
  %count_bcast = stablehlo.broadcast_in_dim %count : tensor<f32> to tensor<6x4xf32> broadcast_dimensions = []

  // mean = sum / count
  %mean_div = stablehlo.divide %mean, %count_bcast : tensor<6x4xf32>

  // Compute variance: mean of squared differences
  // First compute (x - mean)^2

  // Broadcast mean to shape [6,4,4,13,4,4]
  %mean_bcast = stablehlo.broadcast_in_dim %mean_div : tensor<6x4xf32> to tensor<6x4x4x13x4x4xf32> broadcast_dimensions = [0,1]

  // Compute diff = x - mean
  %diff = stablehlo.subtract %hardswish_reshaped, %mean_bcast : tensor<6x4x4x13x4x4xf32>

  // Square diff
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x4x4x13x4x4xf32>

  // Sum squared differences over axes [2,3,4,5]
  %var_sum = stablehlo.reduce %diff_sq init_tensor(%zero) dimensions = [2,3,4,5] : tensor<6x4x4x13x4x4xf32> -> tensor<6x4xf32> {
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  }

  // variance = var_sum / count
  %variance = stablehlo.divide %var_sum, %count_bcast : tensor<6x4xf32>

  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %epsilon_bcast = stablehlo.broadcast_in_dim %epsilon : tensor<f32> to tensor<6x4xf32> broadcast_dimensions = []

  %var_eps = stablehlo.add %variance, %epsilon_bcast : tensor<6x4xf32>

  // Compute rsqrt(variance + epsilon)
  %rsqrt = stablehlo.rsqrt %var_eps : tensor<6x4xf32>

  // Normalize: (x - mean) * rsqrt
  %diff_norm = stablehlo.multiply %diff, %rsqrt_bcast = stablehlo.broadcast_in_dim %rsqrt : tensor<6x4xf32> to tensor<6x4x4x13x4x4xf32> broadcast_dimensions = [0,1]

  // Reshape group_norm.weight and bias from [16] to [4,4]
  %gn_weight_reshaped = stablehlo.reshape %arg2 : tensor<16xf32> to tensor<4x4xf32>
  %gn_bias_reshaped = stablehlo.reshape %arg3 : tensor<16xf32> to tensor<4x4

func.func @main(%arg0: tensor<16x3x4x4x4xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<6x3x16x7x7xf32>) -> tensor<6x16xf32> {
  // %arg0: conv.weight (out_channels=16, in_channels=3, kernel_d=4, kernel_h=4, kernel_w=4)
  // %arg1: conv.bias (16)
  // %arg2: group_norm.weight (16)
  // %arg3: group_norm.bias (16)
  // %arg4: input (batch=6, in_channels=3, depth=16, height=7, width=7)

  // Convolution parameters:
  // input shape: [6,3,16,7,7]
  // kernel shape: [16,3,4,4,4]
  // output shape: [6,16,13,4,4] because:
  // output_depth = 16 - 4 + 1 = 13
  // output_height = 7 - 4 + 1 = 4
  // output_width = 7 - 4 + 1 = 4

  // convolution dimension numbers for 3D conv:
  // input: NCDHW = batch, channels, depth, height, width
  // kernel: OI D H W = out_channels, in_channels, kernel_d, kernel_h, kernel_w
  // output: NCDHW

  // Strides = 1, padding = 0, dilations = 1, feature_group_count = 1

  %cst_zero = stablehlo.constant dense<0> : tensor<i32>
  %cst_one = stablehlo.constant dense<1> : tensor<i32>

  %conv = stablehlo.convolution %arg4, %arg0 {
    window_strides = [1, 1, 1],
    padding = [0, 0, 0, 0, 0, 0],
    lhs_dilation = [],
    rhs_dilation = [],
    dimension_numbers = #stablehlo.conv_3d_dim_numbers,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {},
  } : tensor<6x3x16x7x7xf32>, tensor<16x3x4x4x4xf32> -> tensor<6x16x13x4x4xf32>

  // Add bias: broadcast bias from [16] to [6,16,13,4,4]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x16x13x4x4xf32>

  // HardSwish activation: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)
  // Implement step by step:

  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Broadcast constants to conv_bias shape
  %three_b = stablehlo.broadcast_in_dim %three : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %six_b = stablehlo.broadcast_in_dim %six : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []
  %zero_b = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x16x13x4x4xf32> broadcast_dimensions = []

  // x + 3
  %x_plus_3 = stablehlo.add %conv_bias, %three_b : tensor<6x16x13x4x4xf32>

  // max(x+3, 0)
  %max_x_plus_3_0 = stablehlo.maximum %x_plus_3, %zero_b : tensor<6x16x13x4x4xf32>

  // min(max(x+3,0), 6)
  %relu6 = stablehlo.minimum %max_x_plus_3_0, %six_b : tensor<6x16x13x4x4xf32>

  // x * relu6 / 6
  %relu6_div_6 = stablehlo.divide %relu6, %six_b : tensor<6x16x13x4x4xf32>
  %hardswish = stablehlo.multiply %conv_bias, %relu6_div_6 : tensor<6x16x13x4x4xf32>

  // GroupNorm:
  // num_groups=4, channels=16, so channels_per_group=4
  // Reshape to [batch, num_groups, channels_per_group, depth, height, width]
  %reshape1 = stablehlo.reshape %hardswish : tensor<6x16x13x4x4xf32> to tensor<6x4x4x13x4x4xf32>

  // Compute mean and variance over axes [2,3,4,5] (channels_per_group and spatial dims)
  // axes = [2,3,4,5]

  %axes = stablehlo.constant dense<[2,3,4,5]> : tensor<4xi64>

  %mean = stablehlo.reduce %reshape1, %zero {
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x4x4x13x4x4xf32>, tensor<f32>) -> tensor<6x4xf32> reduce_dims = [2,3,4,5]

  // Compute count of elements reduced: 4*13*4*4 = 832
  %count = stablehlo.constant dense<832.0> : tensor<f32>
  %count_b = stablehlo.broadcast_in_dim %count : tensor<f32> to tensor<6x4xf32> broadcast_dimensions = []

  %mean_div = stablehlo.divide %mean, %count_b : tensor<6x4xf32>

