  // %arg1: matmul.weight, shape [16,16]
  // %arg2: matmul.bias, shape [16]
  // %arg0: bias, shape [16]
  // %arg3: group_norm.weight, shape [16]
  // %arg4: group_norm.bias, shape [16]

  // 1) Linear layer: x @ weight^T + bias
  // Note: PyTorch Linear weight shape is [out_features, in_features], so we need to transpose weight for dot_general
