  %batch_size_broadcast = stablehlo.broadcast_in_dim %batch_size_const : tensor<f32> to tensor<16xf32> broadcast_dimensions = []
  %mean_scaled = stablehlo.divide %mean, %batch_size_broadcast : tensor<16xf32>

  // Broadcast mean to [16,16] for subtraction
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_scaled : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  // Compute variance: mean of (x - mean)^2 over batch dimension
  %diff = stablehlo.subtract %swish_bias, %mean_broadcast : tensor<16x16xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16xf32>
  %var_sum = stablehlo.reduce %diff_sq, %zero : tensor<16x16xf32>, tensor<f32> {
    ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>):
      %sum = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } : tensor<16x16xf32> to tensor<16xf32> reduce_dims = [0]

  %var = stablehlo.divide %var_sum, %batch_size_broadcast : tensor<16xf32>

  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1e-5> : tensor<f32>
  %epsilon_broadcast = stablehlo.broadcast_in_dim %epsilon : tensor<f32> to tensor<16xf32> broadcast_dimensions = []
  %var_eps = stablehlo.add %var, %epsilon_broadcast : tensor<16xf32>

  // Compute rsqrt(variance + epsilon)
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16xf32>

  // Normalize: (x - mean) * rsqrt_var
  %rsqrt_var_broadcast = stablehlo.broadcast_in_dim %rsqrt_var : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %normalized = stablehlo.multiply %diff, %rsqrt_var_broadcast : tensor<16x16xf32>

  // Apply group_norm.weight (scale) and group_norm.bias (shift)
  %weight_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %bias_gn_broadcast = stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %normalized, %weight_broadcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %bias_gn_broadcast : tensor<16x16xf32>

  func.return %out : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape [16,16]
  // %arg1: matmul.weight, shape [16,16]
  // %arg2: matmul.bias, shape [16]
  // %arg0: bias, shape [16]
  // %arg3: group_norm.weight, shape [16]
  // %arg4: group_norm.bias, shape [16]

  // Step 1: matmul: x @ weight^T
  // PyTorch Linear: y = x @ weight^T + bias
  // Here weight shape is [16,16], so weight^T shape is [16,16]
  // We do dot_general with contracting dims [1] of x and [1] of weight (transpose weight)
  // So we transpose weight first
  %weight_t = stablehlo.transpose %arg1 : tensor<16x16xf32> to tensor<16x16xf32>

  %matmul = stablehlo.dot_general %arg5, %weight_t {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: add matmul.bias (arg2) to matmul result
  // matmul.bias shape [16], broadcast to [16,16] on dim 1
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %matmul_bias = stablehlo.add %matmul, %bias_broadcast : tensor<16x16xf32>

  // Step 3: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %matmul_bias : tensor<16x16xf32>
  %exp = stablehlo.exp %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %one_plus_exp = stablehlo.add %one_tensor, %exp : tensor<16x16xf32>
  %sigmoid = stablehlo.div %one_tensor, %one_plus_exp : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_bias, %sigmoid : tensor<16x16xf32>

  // Step 4: add bias (arg0) to swish output
  // bias shape [16], broadcast on dim 1
  %bias_broadcast2 = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %swish_bias = stablehlo.add %swish, %bias_broadcast2 : tensor<16x16xf32>

  // Step 5: GroupNorm with num_groups=16, num_channels=16, input shape [N=16,C=16]
  // GroupNorm formula:
  // Reshape input [16,16] -> [16,16,1] (N,G,C//G)
  // Compute mean and variance over axes [2] (channels per group)
  // Normalize: (x - mean) / sqrt(var + eps)
  // Scale and shift with group_norm.weight and group_norm.bias (both shape [16])
  // Since num_groups=16 and channels=16, each group has 1 channel, so variance=0 always.
  // So normalization is (x - mean) / sqrt(eps)
  // mean over axis 2 (size=1) is just the value itself, so x - mean = 0
  // So output = group_norm.weight * 0 + group_norm.bias = group_norm.bias broadcasted
  // But to follow the formula exactly, we implement the steps.

  // Reshape input to [16,16,1]
  %input_reshaped = stablehlo.reshape %swish_bias : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over axis 2 (channels per group)
  %axes_mean = stablehlo.constant dense<2> : tensor<i64>
  %mean = stablehlo.reduce %input_reshaped, %zero = stablehlo.constant dense<0.0> : tensor<1xf32> {
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<16x16x1xf32>, tensor<1xf32>) -> tensor<16x16xf32>

  // Actually, stablehlo.reduce requires a region with two args: accumulator and element
  // Let's write the reduce region properly:

  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce %input_reshaped, %zero : tensor<16x16x1xf32>, tensor<f32> {
    ^bb0(%acc: tensor<f32>, %elem: tensor<f32>):
      %sum = stablehlo.add %acc, %elem : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide sum by 1 (size of axis 2)
  %one_f32 = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one_f32 : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %mean_div = stablehlo.div %mean, %one_broadcast : tensor<16x16xf32>

  // Compute variance: reduce sum of (x - mean)^2 over axis 2
  // Broadcast mean to shape [16,16,1]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_div : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  %diff = stablehlo.subtract %input_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = stablehlo.reduce %sq, %zero_f32 : tensor<16x16x1xf32>, tensor<f32> {
    ^bb0(%acc: tensor<f32>, %elem: tensor<f32>):
      %sum = stablehlo.add %acc, %elem : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide variance sum by 1 (axis size)
  %var = stablehlo.div %var_sum, %one_broadcast : tensor<16x16xf32>

  // Add epsilon = 1e-5 for numerical stability
  %eps = stablehlo.constant dense<1.00000001e-5> : tensor<f32>
  %eps_broadcast = stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<16x16xf32>

  // Compute rsqrt(var + eps)
  %rsqrt = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) * rsqrt
  %diff2 = stablehlo.subtract %swish_bias, %mean_div : tensor<16x16xf32>
  %norm = stablehlo.multiply %diff2, %rsqrt : tensor<16x16xf32>

  // Scale and shift: norm * group_norm.weight + group_norm.bias
  // group_norm.weight and bias shape [16], broadcast on dim 1
  %weight_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %bias_broadcast_gn = stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %norm, %weight_broadcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %bias_broadcast_gn : tensor<16x16xf32>

  func.return %out

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape [16,16]
  // %arg1: matmul.weight, shape [16,16]
  // %arg2: matmul.bias, shape [16]
  // %arg0: bias, shape [16]
  // %arg3: group_norm.weight, shape [16]
  // %arg4: group_norm.bias, shape [16]

  // Step 1: matmul: x @ weight^T
  // matmul.weight is [16,16], but nn.Linear weight shape is [out_features, in_features]
  // PyTorch Linear does x @ weight.T + bias, so we do dot_general with lhs=%arg5 [16,16], rhs=%arg1 [16,16]
  // We want to do dot_general with contracting dims: lhs dim 1, rhs dim 1 (rhs transposed)
  // So we transpose rhs to get [16,16] -> [16,16], but since it's square, transpose is same shape.
  // We'll do dot_general with rhs transposed.

  %rhs_t = stablehlo.transpose %arg1 : tensor<16x16xf32> to tensor<16x16xf32>

  %matmul = stablehlo.dot_general %arg5, %rhs_t {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: add matmul.bias (arg2) to matmul output
  // matmul.bias shape [16], broadcast to [16,16] on dim 1
  %matmul_bias_bcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %matmul_plus_bias = stablehlo.add %matmul, %matmul_bias_bcast : tensor<16x16xf32>

  // Step 3: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %matmul_plus_bias : tensor<16x16xf32>
  %exp = stablehlo.exp %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %one_plus_exp = stablehlo.add %one_tensor, %exp : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_tensor, %one_plus_exp : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_plus_bias, %sigmoid : tensor<16x16xf32>

  // Step 4: add bias (arg0) to swish output
  // bias shape [16], broadcast on dim 1
  %bias_bcast = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %swish_plus_bias = stablehlo.add %swish, %bias_bcast : tensor<16x16xf32>

  // Step 5: group norm
  // GroupNorm with num_groups=16, out_features=16
  // Input shape: [N=16, C=16]
  // GroupNorm divides channels into groups of size C//num_groups=1
  // So each group has 1 channel, so mean and var are over group channels (1 channel) and spatial dims (none)
  // So mean and var are per element (per batch and channel)
  // But PyTorch GroupNorm computes mean and var over (N, spatial dims) per group channel.
  // Actually, PyTorch GroupNorm computes mean and var over (N, spatial dims) per group channel.
  // But since num_groups=channels=16, group size=1, so mean and var are computed over spatial dims only.
  // Here input is 2D [N,C], no spatial dims, so mean and var are computed over batch dimension per channel group.
  // So for each group (channel), mean and var over batch dimension (dim 0).
  // So we compute mean and variance over dim 0 for each channel.

  // Reshape input to [N=16, C=16]
  %gn_input = %swish_plus_bias : tensor<16x16xf32>

  // Compute mean over batch dim (dim 0), result shape [16]
  %mean = stablehlo.reduce %gn_input, %zero = stablehlo.constant dense<0.0> : tensor<f32> {
    dimensions = [0],
    body = {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // mean = sum / 16
  %divisor = stablehlo.constant dense<16.0> : tensor<f32>
  %divisor_tensor = stablehlo.broadcast_in_dim %divisor : tensor<f32> to tensor<16xf32> broadcast_dimensions = []
  %mean_scaled = stablehlo.divide %mean, %divisor_tensor : tensor<16xf32>

  // Broadcast mean to [16,16] for subtraction
  %mean_bcast = stablehlo.broadcast_in_dim %mean_scaled : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  // Compute (x - mean)^2
  %diff = stablehlo.subtract %gn_input, %mean_bcast : tensor<16x16xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16xf32>

  // Compute variance: reduce sum over batch dim (dim 0)
  %var_sum = stablehlo.reduce %diff_sq, %zero : tensor<f32> {
    dimensions = [0],
    body = {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // variance = var_sum / 16
  %var = stablehlo.divide %var_sum, %divisor_tensor : tensor<16xf32>

  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %epsilon_tensor = stablehlo.broadcast_in_dim %epsilon : tensor<f32> to tensor<16xf32> broadcast_dimensions = []
  %var_eps = stablehlo.add %var, %epsilon_tensor : tensor<16xf32>

  // Compute rsqrt(variance + epsilon)
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16xf32>

  // Normalize: (x - mean) * rsqrt_var
  %rsqrt_var_bcast = stablehlo.broadcast_in_dim %rsqrt_var : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %normalized = stablehlo.multiply %diff, %rsqrt_var_bcast : tensor<16x16xf32>

  // Apply affine transform: normalized * weight + bias
  // group_norm.weight (arg3) and group_norm.bias (arg4) shape [16]
  %weight_bcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %bias_gn_bcast = stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %normalized, %weight_bcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %bias_gn_bcast : tensor<16x16xf32>

  func.return %out : tensor<16x16xf32>
}

func.func @main(%bias: tensor<16xf32>, %matmul_weight: tensor<16x16xf32>, %matmul_bias: tensor<16xf32>, %group_norm_weight: tensor<16xf32>, %group_norm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // matmul: x @ weight^T + bias
  // matmul_weight shape: [16,16], we want to do input [16,16] x weight^T [16,16]
  // So transpose matmul_weight to [16,16] (actually same shape, but transpose swaps dims)
  %matmul_weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %matmul_out = "stablehlo.dot_general"(%input, %matmul_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %matmul_out_bias = stablehlo.add %matmul_out, %matmul_bias : tensor<16x16xf32>

  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %matmul_out_bias : tensor<16x16xf32>
  %exp = stablehlo.exponential %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: []}} : (tensor<f32>) -> tensor<16x16xf32>
  %one_plus_exp = stablehlo.add %one_tensor, %exp : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_tensor, %one_plus_exp : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_out_bias, %sigmoid : tensor<16x16xf32>

  // Add bias parameter %bias (shape [16]) broadcasted to [16x16]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64:  [1]} } : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm with num_groups=16, out_features=16
  // Input shape: [16,16] (batch_size=16, channels=16)
  // GroupNorm with 16 groups means each channel is its own group (group size = 1)
  // So normalization is per channel per batch element (mean and variance over group_size=1 elements)
  // But group size=1 means variance=0, so normalized output = (x - mean) / sqrt(var + eps) = 0/eps = 0
  // But we must implement the formula:
  // For each batch and group, compute mean and variance over group_size elements.
  // Here group_size=1, so mean = x itself, variance=0.
  // So normalized = 0 always.
  // Then output = normalized * weight + bias (weight and bias are per channel)
  // So output = bias (broadcasted over batch)
  // But to follow the task, we implement the general formula.

  // Reshape input [16,16] to [16,16,1] to separate groups (groups=16, group_size=1)
  %input_reshaped = stablehlo.reshape %swish_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over last dimension (group_size=1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: []}} : (tensor<f32>) -> tensor<16x16xf32>
  %mean = "stablehlo.reduce"(%input_reshaped, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean /= group_size=1 (no change)
  // Compute variance: mean of squared difference
  %mean_broadcast = stablehlo.reshape %mean : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %input_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%diff_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance /= group_size=1 (no change)
  // epsilon for numerical stability
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: []}} : (tensor<f32>) -> tensor<16x16xf32>
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<16x16xf32>
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %diff_2d = stablehlo.reshape %diff : (tensor<16x16x1xf32>) -> tensor<16x16xf32>
  %normalized = stablehlo.multiply %diff_2d, %rsqrt_var : tensor<16x16xf32>

  // Apply group_norm weight and bias (per channel)
  // weight and bias shape: [16], broadcast to [16x16]
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%group_norm_weight) {broadcast_dimensions = array<i64: [1]} } : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_broadcast = "stablehlo.broadcast_in_dim"(%group_norm_bias) {broadcast_dimensions = array<i64: [1]} } : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %normalized, %weight_broadcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %bias_gn_broadcast : tensor<16x16xf32>

  func.return %out : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape (16,16)
  // %arg1: matmul.weight, shape (16,16)
  // %arg2: matmul.bias, shape (16)
  // %arg0: bias, shape (16)
  // %arg3: group_norm.weight, shape (16)
  // %arg4: group_norm.bias, shape (16)

  // 1) Linear layer: x @ weight^T + bias
  // dot_general with batch dims [0], contracting dims [1] of lhs and [1] of rhs
  %0 = stablehlo.dot_general %arg5, %arg1 {
    lhs_batch_dims = [0],
    rhs_batch_dims = [0],
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %1 = stablehlo.add %0, %arg2 : tensor<16x16xf32>, tensor<16xf32> -> tensor<16x16xf32>
  // Broadcast %arg2 (bias) from shape (16) to (16,16) on dim 1
  // Actually stablehlo.add broadcasts automatically if shapes are compatible

  // 2) Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %2 = stablehlo.negate %1 : tensor<16x16xf32>
  %3 = stablehlo.exp %2 : tensor<16x16xf32>
  %4 = stablehlo.add %3, %cst_one : tensor<16x16xf32>, tensor<f32> -> tensor<16x16xf32>
  %5 = stablehlo.divide %cst_one, %4 : tensor<f32>, tensor<16x16xf32> -> tensor<16x16xf32>
  %6 = stablehlo.multiply %1, %5 : tensor<16x16xf32>, tensor<16x16xf32> -> tensor<16x16xf32>

  // 3) Add bias (parameter bias, %arg0) to each output vector element-wise
  // %arg0 shape (16), broadcast to (16,16) on dim 1
  %7 = stablehlo.add %6, %arg0 : tensor<16x16xf32>, tensor<16xf32> -> tensor<16x16xf32>

  // 4) GroupNorm with num_groups=16, so each channel is its own group
  // Input shape: (N=16, C=16)
  // Reshape to (N=16, G=16, C_per_group=1)
  %8 = stablehlo.reshape %7 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over axis 2 (C_per_group=1), so mean is the same as the value itself
  // But we do it generally:
  %axes = stablehlo.constant dense<[2]> : tensor<1xi64>
  %9 = stablehlo.reduce %8, %cst_zero : tensor<16x16x1xf32>, tensor<f32> {
    body() {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32> -> tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean = sum / 1 = sum (since size=1)
  %mean = %9

  // Compute variance: mean((x - mean)^2)
  %10 = stablehlo.subtract %8, %mean : tensor<16x16x1xf32>, tensor<16x16xf32> -> tensor<16x16x1xf32>
  %11 = stablehlo.multiply %10, %10 : tensor<16x16x1xf32>, tensor<16x16x1xf32> -> tensor<16x16x1xf32>
  %12 = stablehlo.reduce %11, %cst_zero : tensor<16x16x1xf32>, tensor<f32> {
    body() {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32> -> tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = sum / 1 = sum
  %variance = %12

  // epsilon for numerical stability
  %cst_eps = stablehlo.constant 1.000000e-05 : f32

  // inv_std = rsqrt(variance + epsilon)
  %13 = stablehlo.add %variance, %cst_eps : tensor<16x16xf32>, tensor<f32> -> tensor<16x16xf32>
  %14 = stablehlo.rsqrt %13 : tensor<16x16xf32>

  // Normalize: (x - mean) * inv_std
  %15 = stablehlo.subtract %8, %mean : tensor<16x16x1xf32>, tensor<16x16xf32> -> tensor<16x16x1xf32>
  %16 = stablehlo.multiply %15, %14 : tensor<16x16x1xf32>, tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Reshape group_norm.weight and bias from (16) to (1,16,1) for broadcast
  %17 = stablehlo.reshape %arg3 : tensor<16xf32> to tensor<1x16x1xf32>
  %18 = stablehlo.reshape %arg4 : tensor<16xf32> to tensor<1x16x1xf32>

  // Apply scale and shift: normalized * weight + bias
  %19 = stablehlo.multiply %16, %17 : tensor<16x16x1xf32>, tensor<1x16x1xf32> -> tensor<16x16x1xf32>
  %20 = stablehlo.add %19, %18 : tensor<16x16x1xf32>, tensor<1x16x1xf32> -> tensor<16x16x1xf32>

  // Reshape back to (16,16)
  %21 = stablehlo.reshape %20 : tensor<16x16x1xf32> to tensor<16x16xf32>

  return %21 : tensor<16x16xf32>
}

