func.func @main(%bias: tensor<16xf32>, %matmul_weight: tensor<16x16xf32>, %matmul_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // matmul: x @ weight^T + bias
  // matmul_weight shape: [16,16], we want to do input [16,16] x weight^T [16,16]^T = [16,16]
  // So contract dimension is input's last dim (1) and weight's last dim (1)
  // But weight needs to be transposed or we use dot_general with contracting dims [1] and [1] and no transpose
  // Actually, weight is [16,16], input [16,16], so dot_general with contracting dims input dim 1 and weight dim 1
  // But weight is [out_features, in_features], so to do input @ weight^T, we do dot_general with lhs_contracting=1, rhs_contracting=1, but rhs is weight transposed
  // Instead, we transpose weight to get [16,16] -> [16,16] (swap dims 0 and 1)
  %weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
