  %matmul_out_bias = stablehlo.add %matmul_out, %bias_broadcast : tensor<16x16xf32>

  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %matmul_out_bias : tensor<16x16xf32>
  %exp = stablehlo.exponential %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: []}} : (tensor<f32>) -> tensor<16x16xf32>
  %exp_plus_one = stablehlo.add %one_tensor, %exp : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_tensor, %exp_plus_one : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_out_bias, %sigmoid : tensor<16x16xf32>

  // Add bias parameter (bias argument %bias shape [16]) broadcast to [16x16]
  %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias_broadcast2 : tensor<16x16xf32>

  // GroupNorm with num_groups=16, out_features=16, so each group has 1 channel
  // Input shape: [batch=16, channels=16]
  // GroupNorm reshapes to [batch, num_groups, channels_per_group] = [16,16,1]
  // Compute mean and variance over channels_per_group dimension (dim=2)
  // Then normalize: (x - mean) / sqrt(var + eps)
  // Then scale and shift with gn_weight and gn_bias (shape [16]) broadcasted over batch dimension

  // Reshape to [16,16,1]
  %swish_bias_reshaped = stablehlo.reshape %swish_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over dim=2 (channels_per_group)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_tensor = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: []}} : (tensor<f32>) -> tensor<16x16xf32>
  %mean = "stablehlo.reduce"(%swish_bias_reshaped, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: [16,16], divide by channels_per_group=1
  %one_scalar = stablehlo.constant dense<1.0> : tensor<f32>
  %one_scalar_broadcast = "stablehlo.broadcast_in_dim"(%one_scalar) {broadcast_dimensions = array<i64: []}} : (tensor<f32>) -> tensor<16x16xf32>
  %mean_scaled = stablehlo.divide %mean, %one_scalar_broadcast : tensor<16x16xf32>

  // Broadcast mean back to [16,16,1]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute variance: mean of squared differences
  %diff = stablehlo.subtract %swish_bias_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  %var_scaled = stablehlo.divide %var, %one_scalar_broadcast : tensor<16x16xf32>
  %var_broadcast = "stablehlo.broadcast_in_dim"(%var_scaled) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // epsilon for numerical stability
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: []}} : (tensor<f32>) -> tensor<16x16xf32>
  %eps_broadcast_3d = "stablehlo.broadcast_in_dim"(%eps_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // variance + eps
  %var_eps = stablehlo.add %var_broadcast, %eps_broadcast_3d : tensor<16x16x1xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<16x16x1xf32>

  // normalize: (x - mean) / stddev
  %normalized = stablehlo.divide %diff, %stddev : tensor<16x16x1xf32>

  // Reshape normalized to [16,16]
  %normalized_2d = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Scale and shift with gn_weight and gn_bias (shape [16])
  // Broadcast gn_weight and gn_bias to [16,16]
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  %scaled = stablehlo.multiply %normalized_2d, %gn_weight_broadcast : tensor<16x16xf32

