  %cst_sub1 = stablehlo.constant 0.5 : f32
  %sub1_broadcast = stablehlo.broadcast %cst_sub1 : tensor<f32> to tensor<6x6x4x4xf32>
  %sub1 = stablehlo.subtract %conv_bias, %sub1_broadcast : tensor<6x6x4x4xf32>

  // tanh
  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // subtract2_value = 0.2
  %cst_sub2 = stablehlo.constant 0.2 : f32
  %sub2_broadcast = stablehlo.broadcast %cst_sub2 : tensor<f32> to tensor<6x6x4x4xf32>
  %sub2 = stablehlo.subtract %tanh, %sub2_broadcast : tensor<6x6x4x4xf32>

