    window_dilation = [],
    // reduce add
    reduce_computation = @add_f32
  } : tensor<6x6x4x4xf32> -> tensor<6x6x2x2xf32>

  // divide by 4 (kernel_size_pool^2)
  %cst_4 = stablehlo.constant 4.0 : f32
  %divisor = stablehlo.broadcast %cst_4 : tensor<f32> to tensor<6x6x2x2xf32>
  %avgpool = stablehlo.divide %pool_sum, %divisor : tensor<6x6x2x2xf32>

  func.return %avgpool : tensor<6x6x2x2xf32>
