  %c_sub1 = stablehlo.constant dense<0.5> : tensor<f32>
  %c_sub1_broadcast = "stablehlo.broadcast_in_dim"(%c_sub1) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub1 = stablehlo.subtract %conv_bias, %c_sub1_broadcast : tensor<6x6x4x4xf32>

