  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // Subtract 0.2 (subtract2_value)
  %c_sub2 = stablehlo.constant dense<0.2> : tensor<f32>
  %c_sub2_broadcast = "stablehlo.broadcast_in_dim"(%c_sub2) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub2 = stablehlo.subtract %tanh, %c_sub2_broadcast : tensor<6x6x4x4xf32>

  // Average Pooling with kernel_size_pool=2, stride=2, no padding
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %avgpool_sum = "stablehlo.reduce_window"(%sub2, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Divide by 4 (kernel_size_pool^2) to get average
  %c_4 = stablehlo.constant dense<4.0> : tensor<f32>
  %c_4_broadcast = "stablehlo.broadcast_in_dim"(%c_4) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x6x2x2xf32>
  %avgpool = stablehlo.divide %avgpool_sum, %c_4_broadcast : tensor<6x6x2x2xf32>

  return %avgpool : tensor<6x6x2x2xf32>
}

func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
  // %arg0: conv.weight (out_channels=6, in_channels=7, kernel_h=3, kernel_w=3)
  // %arg1: conv.bias (6)
  // %arg2: input (batch=6, in_channels=7, height=6, width=6)

  // Convolution parameters:
  // window_strides = [1,1]
  // padding = 0 (valid convolution)
  // lhs_dilation = [1,1]
  // rhs_dilation = [1,1]
  // dimension_numbers = [b, i, h, w] x [o, i, kh, kw] -> [b, o, h, w]
  // feature_group_count = 1
  // batch_group_count = 1

  // Perform convolution
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: broadcast bias from [6] to [6x6x4x4]
  // Bias shape: [6] (out_channels)
  // Conv output shape: [6(batch), 6(out_channels), 4, 4]
  // Broadcast bias on dimension 1 (out_channels)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

  // Subtract 0.5 (subtract1_value)
  %c_sub1 = stablehlo.constant dense<0.5> : tensor<f32>
