  %sub1_broadcast = "stablehlo.broadcast_in_dim"(%c_sub1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub1 = stablehlo.subtract %conv_bias, %sub1_broadcast : tensor<6x6x4x4xf32>

  // Apply tanh
  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // Subtract 0.2 (subtract2_value)
  %c_sub2 = stablehlo.constant dense<0.2> : tensor<f32>
  // Broadcast scalar 0.2 to tanh shape
  %sub2_broadcast = "stablehlo.broadcast_in_dim"(%c_sub2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub2 = stablehlo.subtract %tanh, %sub2_broadcast : tensor<6x6x4x4xf32>

  // Average Pooling with kernel_size_pool=2, stride=2, no padding
  // avgpool kernel size = 2x2
  // stride = 2x2
  // input shape: [6,6,4,4]
  // output shape: [6,6,2,2]

  // Compute sum pooling by reduce_window with add, then divide by 4.0

  // Initial value for reduce_window (zero)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  %sum_pool = "stablehlo.reduce_window"(%sub2, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Divide by 4.0 to get average
  %c_4 = stablehlo.constant dense<4.0> : tensor<f32>
  // Broadcast scalar 4.0 to sum_pool shape
  %divisor = "stablehlo.broadcast_in_dim"(%c_4) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>
  %avg_pool = stablehlo.divide %sum_pool, %divisor : tensor<6x6x2x2xf32>

  return %avg_pool : tensor<6x6x2x2xf32>
}

func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
