func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // %arg0: conv.weight with shape [out_channels=7, in_channels=8, kernel_h=3, kernel_w=3]
  // %arg1: conv.bias with shape [7]
  // %arg2: input with shape [batch=6, in_channels=8, height=6, width=6]

  // Perform convolution:
  // convolution expects input NHWC or NCHW? StableHLO convolution expects input in NCHW format by default.
  // The conv.weight shape is [out_channels, in_channels, kernel_h, kernel_w]
  // The input shape is [batch, in_channels, height, width]
  // We want output shape [batch=6, out_channels=7, out_height=4, out_width=4]
  // Because kernel=3, stride=1, padding=0, output spatial dims = input_dim - kernel_dim + 1 = 6 - 3 + 1 = 4

  // Convolution dimension numbers for NCHW input and OIHW kernel producing NCHW output:
  // input: batch=0, feature=1, spatial=2,3
  // kernel: output_feature=0, input_feature=1, spatial=2,3
  // output: batch=0, feature=1, spatial=2,3

  // Create convolution dimension numbers attribute
  %dim_numbers = stablehlo.convolution_dimension_numbers {
    input_batch_dimension = 0,
    input_feature_dimension = 1,
    input_spatial_dimensions = [2, 3],
    kernel_output_feature_dimension = 0,
    kernel_input_feature_dimension = 1,
    kernel_spatial_dimensions = [2, 3],
    output_batch_dimension = 0,
    output_feature_dimension = 1,
    output_spatial_dimensions = [2, 3]
  }

  // No padding, no dilation, stride=1
  %conv = stablehlo.convolution %arg2, %arg0 {
    window_strides = [1, 1],
    padding = [0, 0, 0, 0],
    lhs_dilation = [],
    rhs_dilation = [],
