  // LeakyReLU(x) = max(x, 0) + negative_slope * min(x, 0)
  %zero = stablehlo.constant 0.0 : f32
  %zero_broadcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x7x4x4xf32> broadcast_dimensions = []

