func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  %c0 = constant 0 : index
  %c1 = constant 1 : index
  %c6 = constant 6 : index

  // Initialize output tensor with the same shape as input
  %init = tensor.empty() : tensor<6x6xf32>

  // We will compute cumulative product along dim=1 (second dimension)
  // Loop over batch dimension (i) and sequence dimension (j)
  // output[i,0] = input[i,0]
  // output[i,j] = output[i,j-1] * input[i,j]

  %result = scf.for %i = %c0 to %c6 step %c1 iter_args(%out = %init) -> tensor<6x6xf32> {
    %row = tensor.extract_slice %arg0[%i, 0] [1] [1] : tensor<6x6xf32> to tensor<1xf32>
    %row_init = tensor.insert_slice %row into %out[%i, 0] [1] [1] : tensor<1xf32> into tensor<6x6xf32>

    %row_result = scf.for %j = %c1 to %c6 step %c1 iter_args(%acc = %row_init) -> tensor<6x6xf32> {
      %prev = tensor.extract_slice %acc[%i, %j - 1] [1] [1] : tensor<6x6xf32> to tensor<1xf32>
      %curr = tensor.extract_slice %arg0[%i, %j] [1] [1] : tensor<6x6xf32> to tensor<1xf32>
      %mul = mul %prev, %curr : tensor<1xf32>
      %acc_updated = tensor.insert_slice %mul into %acc[%i, %j] [1] [1] : tensor<1xf32> into tensor<6x6xf32>
      scf.yield %acc_updated : tensor<6x6xf32>
    }
    scf.yield %row_result : tensor<6x6xf32>
  }
  return %result : tensor<6x6xf32>
}

func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  %cst_0 = constant 0 : index
  %cst_1 = constant 1 : index
  %cst_6 = constant 6 : index

  // Initialize output tensor with the same shape as input
  %init = tensor.empty() : tensor<6x6xf32>

  // We will compute cumulative product along dim=1 (second dimension)
  // Loop over batch dimension (i) and sequence dimension (j)
  // Use scf.for to implement the cumulative product

  %result = scf.for %i = %cst_0 to %cst_6 step %cst_1 iter_args(%acc = %init) -> tensor<6x6xf32> {
    %row = tensor.extract_slice %arg0[%i, 0] [%cst_1, 6] [1, 1] : tensor<6x6xf32> to tensor<1x6xf32>
    %row_1d = tensor.reshape %row : tensor<1x6xf32> to tensor<6xf32>

    // Compute cumulative product along dim=0 of row_1d
    %cumprod = scf.for %j = %cst_0 to %cst_6 step %cst_1 iter_args(%prod = %row_1d[%cst_0]) -> tensor<6xf32> {
      %prev_prod = scf.if %j {
        scf.yield %prod : f32
      } else {
        %prev = tensor.extract %prod[%cst_0] : tensor<6xf32>
        scf.yield %prev : f32
      }
    }

    // The above is not valid MLIR, so we need to implement cumulative product manually with scf.for

    // Instead, implement cumulative product with a loop over j:
    %cumprod_init = tensor.empty() : tensor<6xf32>
    %cumprod_result = scf.for %j = %cst_0 to %cst_6 step %cst_1 iter_args(%acc_prod = %cumprod_init, %prev = %row_1d[%cst_0]) -> (tensor<6xf32>, f32) {
      %val = tensor.extract %row_1d[%j] : tensor<6xf32>
      %new_prod = mulf %prev, %val : f32
      %acc_prod_updated = tensor.insert %new_prod into %acc_prod[%j] : tensor<6xf32>
      scf.yield %acc_prod_updated, %new_prod : tensor<6xf32>, f32
    }

    // Reshape cumprod_result to 1x6
    %cumprod_2d = tensor.reshape %cumprod_result#0 : tensor<6xf32> to tensor<1x6xf32>

    // Insert cumprod_2d back into output tensor at row i
    %acc_updated = tensor.insert_slice %cumprod_2d into %acc[%i, 0] [1, 6] [1, 1] : tensor<6x6xf32>

    scf.yield %acc_updated : tensor<6x6xf32>
  }

  return %result : tensor<6x6xf32>
}

func.func @main(%arg0: tensor<3x16x3x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<6x3x7x7x7xf32>) -> tensor<6x16x3x3x3xf32> {
