  // %arg0: conv_transpose.weight with shape [in_channels=3, out_channels=16, kD=3, kH=3, kW=3]
  // %arg1: conv_transpose.bias with shape [16]
  // %arg2: batch_norm.weight (gamma) with shape [16]
  // %arg3: batch_norm.bias (beta) with shape [16]

