  // ConvTranspose3d in PyTorch:
  // output_size = (input_size - 1) * stride - 2*padding + kernel_size + output_padding
  // For each spatial dim: (7-1)*2 - 2*1 + 3 + 1 = 12 - 2 + 3 + 1 = 14

  // StableHLO convolution expects weight shape: [N, C, D, H, W]
  // For conv_transpose, we use convolution with dimension_numbers and transpose flag.

  // Prepare dimension numbers for ConvTranspose3d:
  // Input: NCDHW = [6,3,7,7,7]
  // Weight: OI D H W = [3,16,3,3,3] but PyTorch conv_transpose weight shape is [in_channels, out_channels, kD,kH,kW]
  // StableHLO expects weight shape [output_channels, input_channels, kD,kH,kW] for conv (forward)
  // For conv_transpose, weight shape is [input_channels, output_channels, kD,kH,kW], so we must transpose weight dims 0 and 1.

  // So first transpose weight from [3,16,3,3,3] -> [16,3,3,3,3]
  %weight_transposed = stablehlo.transpose %arg0 : tensor<3x16x3x3x3xf32> to tensor<16x3x3x3x3xf32> {permutation = [1,0,2,3,4]}

  // ConvTranspose3d is implemented as convolution with:
  // - window_strides = [1,1,1]
  // - lhs_dilation = [stride=2,2,2]
  // - padding = [padding=1,1,1] on both sides
  // - rhs_dilation = [1,1,1]
  // - dimension_numbers: input NCDHW, kernel OI D H W, output NCDHW
  // - feature_group_count = 1
  // - batch_group_count = 1
  // - precision_config = none

  // StableHLO convolution expects:
  // lhs = input tensor: [N, C_in, D_in, H_in, W_in] = %arg4
  // rhs = kernel tensor: [C_out, C_in, kD, kH, kW] = %weight_transposed
  // lhs_dilation = stride for conv_transpose = [2,2,2]
  // padding = [1,1,1] on both sides

  // Define padding attribute: 3D padding low and high for each spatial dim
  // padding = [[1,1],[1,1],[1,1]]

  %conv_transpose = stablehlo.convolution %arg4, %weight_transposed {
    window_strides = [1,1,1],
    padding = [[1,1],[1,1],[1,1]],
    lhs_dilation = [2,2,2],
    rhs_dilation = [1,1,1],
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2,3,4],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2,3,4],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2,3,4]
    },
    feature_group_count = 1,
    batch_group_count = 1
  } : (tensor<6x3x7x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x14x14x14xf32>

  // Add conv_transpose bias: %arg1 shape [16]
  // Broadcast bias to [6,16,14,14,14]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<6x16x14x14x14xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv_transpose, %bias_broadcast : tensor<6x16x14x14x14xf32>

  // Step 2: BatchNorm3d in training mode:
