  // mean and var computed per channel over batch and spatial dims

  // Compute mean over dims [0,2,3,4] (batch, D, H, W), keep dim 1 (channels)
  %mean = stablehlo.reduce %conv_bias, %c0_f32 : tensor<6x16x14x14x14xf32>, tensor<f32> {
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  } : (tensor<6x16x14x14x14xf32>, tensor<f32>) -> tensor<16xf32> reduce_dims = [0,2,3,4]

  // Compute count for mean: 6*14*14*14 = 16464
  %c16464 = stablehlo.constant 16464 : index
  %c16464_f32 = stablehlo.convert %c16464 : index to f32

  // mean = sum / count
  %mean_f32 = stablehlo.div %mean, %c16464_f32 : tensor<16xf32>

  // Broadcast mean to input shape for subtraction
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_f32 : tensor<16xf32> to tensor<6x16x14x14x14xf32> broadcast_dimensions = [1]

  // Compute variance: var = mean((x - mean)^2)
  %diff = stablehlo.subtract %conv_bias, %mean_broadcast : tensor<6x16x14x14x14xf32>
