  %var_sum = stablehlo.reduce %sq_diff, %c0_f32 : tensor<6x16x14x14x14xf32>, tensor<f32> {
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  } : (tensor<6x16x14x14x14xf32>, tensor<f32>) -> tensor<16xf32> reduce_dims = [0,2,3,4]

  %var = stablehlo.div %var_sum, %c16464_f32 : tensor<16xf32>

  // epsilon for numerical stability
  %eps = stablehlo.constant 1.000000e-05 : f32

  // var + eps
  %var_eps = stablehlo.add %var, %eps : tensor<16xf32>

  // sqrt(var + eps)
  %rsqrt_var_eps = stablehlo.sqrt %var_eps : tensor<16xf32>

  // Broadcast rsqrt_var_eps to input shape
  %rsqrt_broadcast = stablehlo.broadcast_in_dim %rsqrt_var_eps : tensor<16xf32> to tensor<6x16x14x14x14xf32> broadcast_dimensions = [1]

  // Normalize: (x - mean) / sqrt(var + eps)
  %norm = stablehlo.divide %diff, %rsqrt_broadcast : tensor<6x16x14x14x14xf32>

