  // Broadcast gamma and beta to input shape
  %gamma_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<6x16x14x14x14xf32> broadcast_dimensions = [1]
  %beta_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<6x16x14x14x14xf32> broadcast

func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  %cst_0 = stablehlo.constant dense<0> : tensor<i64>
  %cst_1 = stablehlo.constant dense<1> : tensor<i64>
  %cst_6 = stablehlo.constant dense<6> : tensor<i64>

  // Initialize output tensor with the first element of each row (dim=1)
  %first_col = stablehlo.slice %arg0[%cst_0, %cst_0] [%cst_6, %cst_1] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
  %first_col_reshaped = stablehlo.reshape %first_col : tensor<6x1xf32> to tensor<6xf32>

  // We'll build the cumulative product along dim=1 (columns)
  // Initialize an accumulator tensor of shape 6x6 with zeros
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %acc_init = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x6xf32> broadcast_dimensions = []

  // Insert first column values into accumulator at column 0
  %acc_0 = stablehlo.dynamic_update_slice %acc_init, %first_col, %cst_0, %cst_0 : tensor<6x6xf32>, tensor<6xf32>, tensor<i64>, tensor<i64> -> tensor<6x6xf32>

  // Loop over columns 1 to 5 to compute cumulative product
  %cumulative = stablehlo.while (%acc = %acc_0, %i = %cst_1) : (tensor<6x6xf32>, tensor<i64>) -> tensor<6x6xf32> {
    // Condition: i < 6
    %cond = stablehlo.compare "lt" %i, %cst_6 : tensor<i64>
    stablehlo.cond_br %cond, ^body, ^exit(%acc : tensor<6x6xf32>)

  ^body(%acc: tensor<6x6xf32>, %i: tensor<i64>):
    // Slice previous cumulative product column: acc[:, i-1]
    %i_minus_1 = stablehlo.subtract %i, %cst_1 : tensor<i64>
    %prev_col = stablehlo.slice %acc[%cst_0, %i_minus_1] [%cst_6, %i] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
    %prev_col_reshaped = stablehlo.reshape %prev_col : tensor<6x1xf32> to tensor<6xf32>

    // Slice input column: arg0[:, i]
    %curr_col = stablehlo.slice %arg0[%cst_0, %i] [%cst_6, %i_plus_1] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
    %curr_col_reshaped = stablehlo.reshape %curr_col : tensor<6x1xf32> to tensor<6xf32>

    // Multiply prev_col * curr_col elementwise
    %prod = stablehlo.multiply %prev_col_reshaped, %curr_col_reshaped : tensor<6xf32>

    // Reshape prod to 6x1 to update slice
    %prod_reshaped = stablehlo.reshape %prod : tensor<6xf32> to tensor<6x1xf32>

    // Update accumulator at column i with prod
    %acc_updated = stablehlo.dynamic_update_slice %acc, %prod_reshaped, %cst_0, %i : tensor<6x6xf32>, tensor<6x1xf32>, tensor<i64>, tensor<i64> -> tensor<6x6xf32>

    // Increment i
    %i_next = stablehlo.add %i, %cst_1 : tensor<i64>

    stablehlo.br ^cond(%acc_updated, %i_next : tensor<6x6xf32>, tensor<i64>)

  ^exit(%result: tensor<6x6xf32>):
    stablehlo.return %result : tensor<6x6xf32>
  }

  stablehlo.return %cumulative : tensor<6x6xf32>
}

