func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  %cst_0 = stablehlo.constant dense<0> : tensor<i64>
  %cst_1 = stablehlo.constant dense<1> : tensor<i64>
  %cst_6 = stablehlo.constant dense<6> : tensor<i64>

  // Initialize output tensor with the first column of input along dim=1
  %slice0 = stablehlo.slice %arg0[%cst_0, %cst_0] [%cst_6, %cst_1] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
  %init = stablehlo.reshape %slice0 : tensor<6x1xf32> to tensor<6x1xf32>

  // Loop index i from 1 to 5 (dim size along dim=1 is 6)
  %i = stablehlo.constant dense<1> : tensor<i64>

  // We will unroll the loop manually since StableHLO does not have loops.
  // For i in 1..5:
  //   slice_i = input[:, i:i+1]
  //   prev = output[:, i-1:i]
  //   prod = prev * slice_i
  //   concat prod to output along dim=1

  // i=1
  %slice1 = stablehlo.slice %arg0[%cst_0, %i] [%cst_6, %cst_1 + %i] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
