  %prod1 = stablehlo.mul %prev1, %slice1 : tensor<6x1xf32>
  %out1 = stablehlo.concatenate [%init, %prod1] {dimension = 1} : tensor<6x1xf32>, tensor<6x1xf32> -> tensor<6x2xf32>

  // i=2
  %cst_2 = stablehlo.constant dense<2> : tensor<i64>
  %slice2 = stablehlo.slice %arg0[%cst_0, %cst_2] [%cst_6, %cst_2 + %cst_1] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
  %prev2 = stablehlo.slice %out1[%cst_0, %cst_1] [%cst_6, %cst_2] [%cst_1, %cst_1] : tensor<6x2xf32> to tensor<6x1xf32>
  %prod2 = stablehlo.mul %prev2, %slice2 : tensor<6x1xf32>
  %out2 = stablehlo.concatenate [%out1, %prod2] {dimension = 1} : tensor<6x2xf32>, tensor<6x1xf32> -> tensor<6x3xf32>

  // i=3
  %cst_3 = stablehlo.constant dense<3> : tensor<i64>
  %slice3 = stablehlo.slice %arg0[%cst_0, %cst_3] [%cst_6, %cst_3 + %cst_1] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
  %prev3 = stablehlo.slice %out2[%cst_0, %cst_2] [%cst_6, %cst_3] [%cst_1, %cst_1] : tensor<6x3xf32> to tensor<6x1xf32>
  %prod3 = stablehlo.mul %prev3, %slice3 : tensor<6x1xf32>
  %out3 = stablehlo.concatenate [%out2, %prod3] {dimension = 1} : tensor<6x3xf32>, tensor<6x1xf32> -> tensor<6x4xf32>

  // i=4
  %cst_4 = stablehlo.constant dense<4> : tensor<i64>
  %slice4 = stablehlo.slice %arg0[%cst_0, %cst_4] [%cst_6, %cst_4 + %cst_1] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
  %prev4 = stablehlo.slice %out3[%cst_0, %cst_3] [%cst_6, %cst_4] [%cst_1, %cst_1] : tensor<6x4xf32> to tensor<6x1xf32>
  %prod4 = stablehlo.mul %prev4, %slice4 : tensor<6x1xf32>
  %out4 = stablehlo.concatenate [%out3, %prod4] {dimension = 1} : tensor<6x4xf32>, tensor<6x1xf32> -> tensor<6x5xf32>

  // i=5
  %cst_5 = stablehlo.constant dense<5> : tensor<i64>
  %slice5 = stablehlo.slice %arg0[%cst_0, %cst_5] [%cst_6, %cst_5 + %cst_1] [%cst_1, %cst_1] : tensor<6x6xf32> to tensor<6x1xf32>
  %prev5 = stablehlo.slice %out4[%cst_0, %cst_4] [%cst_6, %cst_5] [%cst_1, %cst_1] : tensor<6x5xf32> to tensor<6x1xf32>
  %prod5 = stablehlo.mul %prev5, %slice5 : tensor<6x1xf32>
  %out5 = stablehlo.concatenate [%out4, %prod5] {dimension = 1} : tensor<6x5xf32>, tensor<6x1xf32> -> tensor<6x6xf32>

