  // input: NCHW = batch=0, channel=1, height=2, width=3
  // kernel: OIHW = out_channel=0, in_channel=1, height=2, width=3
  // output: NCHW = batch=0, channel=1, height=2, width=3
  %dim_numbers = stablehlo.convolution_dimension_numbers {
