    dimension_numbers = %dim_numbers,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {operand_precision = [DEFAULT, DEFAULT]}
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

