    stablehlo.return %a : f32
  }) {dimensions = [1]} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7xf32>

  // Broadcast sum_exp_x back to shape 7x8 for division
  %sum_exp_x_broadcast = stablehlo.broadcast_in_dim %sum_exp_x 
    : tensor<7xf32> to tensor<7x8xf32> 
    broadcast_dimensions = [0]

  // Divide exp(x) by sum_exp_x along dimension 1
  %softmax = stablehlo.divide %exp_x, %sum_exp_x_broadcast : tensor<7x8xf32>

  stablehlo.return %softmax : tensor<7x8xf32>
}

func.func @main(%x: tensor<7x8xf32>) -> tensor<7x8xf32> {
  // Compute max over dim 1 for numerical stability: max_x[i] = max_j x[i,j]
  %init_max = stablehlo.constant dense<-inf> : tensor<f32>
  %max_x = "stablehlo.reduce"(%x, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7xf32>

  // Broadcast max_x back to shape 7x8 for subtraction
  %max_x_broadcast = "stablehlo.broadcast_in_dim"(%max_x) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x8xf32>

  // Subtract max_x from x for numerical stability
  %x_stable = stablehlo.subtract %x, %max_x_broadcast : tensor<7x8xf32>

  // Compute exp(x - max_x)
  %exp_x = stablehlo.exponential %x_stable : tensor<7x8xf32>

  // Compute sum over dim 1 of exp_x: sum_exp_x[i] = sum_j exp_x[i,j]
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp_x = "stablehlo.reduce"(%exp_x, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7xf32>

  // Broadcast sum_exp_x back to shape 7x8 for division
  %sum_exp_x_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp_x) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x8xf32>

  // Divide exp_x by sum_exp_x to get softmax output
  %softmax = stablehlo.divide %exp_x, %sum_exp_x_broadcast : tensor<7x8xf32>

  "stablehlo.return"(%softmax) : tensor<7x8xf32>
}

