func.func @main(%arg0: tensor<6x16x3x3xf32>, %arg1: tensor<16x16x7x7xf32>) -> tensor<16x6x5x5xf32> {
  %c0 = arith.constant 0 : index
  %c1 = arith.constant 1 : index
  %c2 = arith.constant 2 : index
  %c3 = arith.constant 3 : index

  // Dimensions:
  // %arg1 shape: [batch=16, in_channels=16, height=7, width=7]
  // %arg0 shape: [out_channels=6, in_channels=16, kernel_h=3, kernel_w=3]
  // Output shape: [batch=16, out_channels=6, out_h=5, out_w=5]

  // Convolution parameters:
  // stride = 1, padding = 0, dilation = 1, groups = 1, bias = false

  // StableHLO convolution expects lhs and rhs tensors with batch and feature dims:
  // lhs: [N, H, W, C_in] or [N, C_in, H, W] depending on dimension_numbers
  // rhs: [K_H, K_W, C_in, C_out] or similar depending on dimension_numbers
  // We must specify dimension_numbers accordingly.

  // Our input is NCHW: [16,16,7,7]
  // Our kernel is OIHW: [6,16,3,3]
  // We want output: [16,6,5,5]

  // StableHLO conv dimension_numbers:
  // lhs_spec: batch, spatial..., feature
  // rhs_spec: spatial..., input_feature, output_feature
  // output_spec: batch, spatial..., feature

  // So we can use:
  // lhs: NCHW -> batch=0, feature=1, spatial=[2,3]
  // rhs: OIHW -> spatial=[2,3], input_feature=1, output_feature=0
  // output: NCHW -> batch=0, feature=1, spatial=[2,3]

  // So dimension_numbers = {
  //   lhs_batch_dim = 0,
  //   lhs_feature_dim = 1,
  //   lhs_spatial_dims = [2,3],
  //   rhs_spatial_dims = [2,3],
  //   rhs_input_feature_dim = 1,
  //   rhs_output_feature_dim = 0,
  //   output_batch_dim = 0,
  //   output_feature_dim = 1,
  //   output_spatial_dims = [2,3]
  // }

  // Create convolution window strides = [1,1]
  %stride = dense<1> : tensor<2xi64>
  %padding = dense<0> : tensor<4xi64>  // no padding: [pad_top, pad_bottom, pad_left, pad_right]
  %lhs_dilation = dense<1> : tensor<2xi64>  // dilation of input (usually 1)
  %rhs_dilation = dense<1> : tensor<2xi64>  // dilation of kernel (usually 1)

  %dim_numbers = stablehlo.convolution_dimension_numbers {
    lhs_batch_dimension = 0,
    lhs_feature_dimension = 1,
    lhs_spatial_dimensions = [2, 3],
    rhs_spatial_dimensions = [2, 3],
    rhs_input_feature_dimension = 1,
    rhs_output_feature_dimension = 0,
    output_batch_dimension = 0,
    output_feature_dimension = 1,
    output_spatial_dimensions = [2, 3]
  }

  %result = stablehlo.convolution %arg1, %arg0 {
    window_strides = %stride,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = %dim_numbers,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {operand_precision = [DEFAULT, DEFAULT]}
  } : (tensor<16x16x7x7xf32>, tensor<6x16x3x3xf32>) -> tensor<16x6x5x5xf32>

  func.return %result : tensor<16x6x5x5xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (gamma) (7)
  // %arg3 = batch_norm.bias (beta) (7)
  // %arg4 = input (6x7)

  // GEMM: x @ W^T + b
  // %arg4 shape: [6,7], %arg0 shape: [7,7]
  // We want to do dot_general with contracting dims: input features (dim 1) and weight input dim (dim 1)
  // But gemm.weight is (out_features x in_features), so we transpose it to (in_features x out_features)
  // Actually, PyTorch Linear does x @ W^T + b, so we do dot_general with lhs=%arg4, rhs=%arg0, contracting lhs dim 1 and rhs dim 1, but rhs needs to be transposed first.

  // Transpose gemm.weight from [7,7] to [7,7] swapping dims 0 and 1 (actually same shape, but transpose needed)
  %0 = stablehlo.transpose %arg0 [1, 0] : tensor<7x7xf32> to tensor<7x7xf32>

  // Dot general: lhs %arg4 [6x7], rhs %0 [7x7], contracting dim 1 lhs and dim 0 rhs
  %1 = stablehlo.dot_general %arg4, %0 {
    lhs_batching_dims = [],
    rhs_batching_dims = [],
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [0]
  } : tensor<6x7xf32>, tensor<7x7xf32> -> tensor<6x7xf32>

  // Add bias %arg1 (7) to each row of %1 (6x7)
  // Broadcast bias to [6x7]
  %2 = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %3 = stablehlo.add %1, %2 : tensor<6x7xf32>

  // BatchNorm1d in training mode:
  // batch_norm(x) = gamma * ((x - mean) / sqrt(var + eps)) + beta
  // mean and var computed over batch dimension (dim 0) for each feature (dim 1)
  // eps = 1e-5 (PyTorch default)

  // Compute mean over batch dim 0: reduce mean over dim 0
  %4 = stablehlo.reduce %3 init(%c0_f32 : f32) dimensions = [0] : tensor<6x7xf32> -> tensor<7xf32> {
    ^bb0(%arg5: f32, %arg6: f32):
      %7 = stablehlo.add %arg5, %arg6 : f32
      stablehlo.return %7 : f32
  }
  // divide sum by 6 (batch size)
  %c6_f32 = stablehlo.constant 6.000000e+00 : f32
  %5 = stablehlo.div %4, %c6_f32 : tensor<7xf32>

  // Compute variance: mean of squared differences
  // (x - mean)^2
  // Broadcast mean %5 [7] to [6x7]
  %6 = stablehlo.broadcast_in_dim %5 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %7 = stablehlo.subtract %3, %6 : tensor<6x7xf32>
  %8 = stablehlo.multiply %7, %7 : tensor<6x7xf32>

  // reduce mean over batch dim 0
  %9 = stablehlo.reduce %8 init(%c0_f32 : f32) dimensions = [0] : tensor<6x7xf32> -> tensor<7xf32> {
    ^bb0(%arg7: f32, %arg8: f32):
      %10 = stablehlo.add %arg7, %arg8 : f32
      stablehlo.return %10 : f32
  }
  %10 = stablehlo.div %9, %c6_f32 : tensor<7xf32>

  // Add eps = 1e-5
  %c_eps = stablehlo.constant 1.000000e-05 : f32
  %11 = stablehlo.add %10, %c_eps : tensor<7xf32>

  // sqrt(var + eps)
  %12 = stablehlo.sqrt %11 : tensor<7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %13 = stablehlo.divide %7, %12 : tensor<6x7xf32>

  // Scale and shift: gamma * normalized + beta
  // Broadcast gamma (%arg2) and beta (%arg3) from [7] to [6x7]
  %14 = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %15 = stablehlo.broadcast_in_dim %arg3 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %16 = stablehlo.multiply %14, %13 : tensor<6x7xf32>
  %17 = stablehlo.add %16, %15 : tensor<6x7xf32>

  // GELU activation (approximate exact GELU):
  // gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // constants:
  %c_half = stablehlo.constant 0.5 : f32
  %c_one = stablehlo.constant 1.0 : f32
  %c_sqrt2 = stablehlo.constant 1.4142135 : f32

  // x / sqrt(2)
  %18 = stablehlo.divide %17, %c_sqrt2 : tensor<6x7xf32>

  // erf(x / sqrt(2))
  %19 = chlo.erf %18 : tensor<6x7xf32>

  // 1 + erf(...)
  %20 = stablehlo.add %c_one, %19 : tensor<6x7xf32>

  // 0.5 * x
  %21 = stablehlo.multiply %c_half, %17 : tensor<6x7xf32>

  // gelu = 0.5 * x * (1 + erf(...))
  %22 = stablehlo.multiply %21, %20 : tensor<6x7xf32>

  // ReLU: max(0, gelu)
  %c_zero = stablehlo.constant 0.0 : f32
  %23 = stablehlo.maximum %22, %c_zero : tensor<6x7xf32>

  stablehlo.return %23 : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (7)
  // %arg3 = batch_norm.bias (7)
  // %arg4 = input (6x7)

  // GEMM: x @ W^T + b
  // %arg4 shape: [6,7], %arg0 shape: [7,7]
  // We want to do dot_general with contracting dims: input feature dim 1 and weight dim 1 (since weight is [7,7], we want to contract input dim 1 with weight dim 1)
  // But PyTorch Linear does x @ W^T + b, so we transpose weight first.

  // Transpose weight: from [7,7] to [7,7] (actually same shape, but transpose dims 0 and 1)
  %weight_t = stablehlo.transpose %arg0 : tensor<7x7xf32> to tensor<7x7xf32> {permutation = [1, 0]}

  // Dot general: batch dim 0 of input and batch dim 0 of weight_t are parallel dims
  // Contract input dim 1 with weight_t dim 1
  %dot = stablehlo.dot_general %arg4, %weight_t {
    lhs_batching_dimensions = [0],
    rhs_batching_dimensions = [0],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [1]
  } : tensor<6x7xf32>, tensor<7x7xf32> -> tensor<6x7xf32>

  // Add bias: broadcast bias [7] to [6,7]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %gemm_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // BatchNorm1d in training mode:
  // batch_norm(x) = weight * ((x - mean) / sqrt(var + eps)) + bias
  // mean and var computed over batch dimension (dim 0)
  // eps = 1e-5 (PyTorch default)

  // Compute mean over batch dim 0: reduce mean over dim 0
  %zero = stablehlo.constant 0 : index
  %one = stablehlo.constant 1 : index
  %eps = stablehlo.constant 0.00001 : f32

  %init_mean = stablehlo.constant 0.0 : f32
  %mean = stablehlo.reduce %gemm_out, %init_mean {
    dimensions = [0],
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // mean = sum / batch_size (6)
  %six = stablehlo.constant 6.0 : f32
  %mean_scaled = stablehlo.divide %mean, %six : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2)
  // Broadcast mean to [6,7]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_scaled : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  // x - mean
  %diff = stablehlo.subtract %gemm_out, %mean_broadcast : tensor<6x7xf32>

  // (x - mean)^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  // sum of squared diffs over batch dim 0
  %init_var = stablehlo.constant 0.0 : f32
  %var_sum = stablehlo.reduce %diff_sq, %init_var {
    dimensions = [0],
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // var = sum / batch_size (6)
  %var = stablehlo.divide %var_sum, %six : tensor<7xf32>

  // var + eps
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  // Broadcast stddev to [6,7]
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7xf32>

  // Apply batch_norm.weight (scale) and batch_norm.bias (shift)
  // Broadcast batch_norm.weight and batch_norm.bias to [6,7]
  %bn_weight_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %bn_bias_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %norm, %bn_weight_broadcast : tensor<6x7xf32>
  %batch_norm_out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // GELU activation (approximate exact GELU):
  // gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // constants:
  %half = stablehlo.constant 0.5 : f32
  %one_f32 = stablehlo.constant 1.0 : f32
  %sqrt2 = stablehlo.constant 1.41421356237 : f32

  // x / sqrt(2)
  %div_sqrt2 = stablehlo.divide %batch_norm_out, %sqrt2 : tensor<6x7xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %div_sqrt2 : tensor<6x7xf32>

  // 1 + erf(...)
  %one_plus_erf = stablehlo.add %one_f32, %erf : tensor<6x7xf32>

  // x * (1 + erf(...))
  %mul_x = stablehlo.multiply %batch_norm_out, %one_plus_erf : tensor<6x7xf32>

  // 0.5 * x * (1 + erf(...))
  %gelu = stablehlo.multiply %half, %mul_x : tensor<6x7xf32>

  // ReLU activation: max(0, gelu)
  %zero_f32 = stablehlo.constant 0.0 : f32
  %relu = stablehlo.maximum %gelu, %zero_f32 : tensor<6x7xf32>

  stablehlo.return %relu : tensor<6x7xf32>
}

