func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (gamma) (7)
  // %arg3 = batch_norm.bias (beta) (7)
  // %arg4 = input (6x7)

  // Step 1: GEMM: x = input * weight^T + bias
  // Note: PyTorch Linear does x @ weight^T + bias
  // So we need to transpose weight to 7x7 (weight is 7x7), but since weight is (out_features x in_features),
  // and input is (batch_size x in_features), we do dot_general with contracting dims [1] and [1] after transpose.
  // Actually, weight is (7x7), input is (6x7), so to do input * weight^T:
  // weight^T shape: 7x7 (same shape), so we transpose weight to get weight^T.
  %weight_t = stablehlo.transpose %arg0 {permutation = [1, 0]} : tensor<7x7xf32> -> tensor<7x7xf32>

  // dot_general with batching dims [] and contracting dims [1] for lhs and [0] for rhs
  %dot = stablehlo.dot_general %arg4, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>
  %x1 = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Step 2: BatchNorm1d in training mode:
  // y = (x - mean) / sqrt(var + eps) * gamma + beta
  // mean and var are computed per feature over batch dimension (dim 0)
  // eps = 1e-5 (PyTorch default)
  // Compute mean over dim 0 (batch dimension)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = []} : tensor<f32> -> tensor<7xf32>
  %mean = stablehlo.reduce %x1, %init_mean (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  ) {dimensions = [0]} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %six : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2)
  // Broadcast mean to (6x7)
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>
  %diff = stablehlo.subtract %x1, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  %init_var = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = []} : tensor<f32> -> tensor<7xf32>
  %var_sum = stablehlo.reduce %diff_sq, %init_var (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  ) {dimensions = [0]} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  %var = stablehlo.divide %var_sum, %six : tensor<7xf32>

  // Add eps and sqrt
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>
  %x_norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7xf32>

  // Scale and shift: gamma * x_norm + beta
  %gamma_broadcast = stablehlo.broadcast_in_dim %arg2 {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>
  %beta_broadcast = stablehlo.broadcast_in_dim %arg3 {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %x_norm, %gamma_broadcast : tensor<6x7xf32>
  %bn_out = stablehlo.add %scaled, %beta_broadcast : tensor<6x7xf32>

  // Step 3: GELU activation (approximate)
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // constants
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>

  %sqrt2_broadcast = stablehlo.broadcast_in_dim %sqrt2 {broadcast_dimensions = []} : tensor<f32> -> tensor<6x7xf32>
  %x_div_sqrt2 = stablehlo.divide %bn_out, %sqrt2_broadcast : tensor<6x7xf32>
  %erf_val = chlo.erf %x_div_sqrt2 : tensor<6x7xf32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = []} : tensor<f32> -> tensor<6x7xf32>
  %erf_plus_one = stablehlo.add %erf_val, %one_broadcast : tensor<6x7xf32>
  %half_broadcast = stablehlo.broadcast_in_dim %half {broadcast_dimensions = []} : tensor<f32> -> tensor<6x7xf32>
  %mul1 = stablehlo.multiply %bn_out, %erf_plus_one : tensor<6x7xf32>
  %gelu = stablehlo.multiply %mul1, %half_broadcast : tensor<6x7xf32>

  // Step 4: ReLU activation: max(0, gelu)
  %zero_broadcast = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = []} : tensor<f32> -> tensor<6x7xf32>
  %relu = stablehlo.maximum %gelu, %zero_broadcast : tensor<6x7xf32>

  func.return %relu : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight: tensor<7x7xf32>
  // %arg1 = gemm.bias: tensor<7xf32>
  // %arg2 = batch_norm.weight (gamma): tensor<7xf32>
  // %arg3 = batch_norm.bias (beta): tensor<7xf32>
  // %arg4 = input: tensor<6x7xf32>

  // Step 1: GEMM: x = input @ weight^T + bias
  // Note: PyTorch Linear uses weight shape (out_features, in_features)
  // Here %arg0 is 7x7, so we assume weight shape is (out_features=7, in_features=7)
  // input shape: (6,7)
  // We want: (6,7) @ (7,7)^T = (6,7) @ (7,7) = (6,7)
  // So we do dot_general with contracting dims: input dim 1 and weight dim 1 (weight second dim)
  // But weight is (7x7), so to do input @ weight^T, we transpose weight first.

  %weight_t = stablehlo.transpose %arg0 {permutation = [1, 0]} : tensor<7x7xf32> -> tensor<7x7xf32>
  %gemm = stablehlo.dot_general %arg4, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6,7)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1
    {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_broadcast : tensor<6x7xf32>

  // Step 2: BatchNorm1d in training mode:
  // batch_norm(x) = gamma * ((x - mean) / sqrt(var + eps)) + beta
  // mean and var computed over batch dimension (dim 0) for each feature (dim 1)
  // eps = 1e-5 (PyTorch default)

  // Compute mean over batch dim 0: shape (7)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = []} : tensor<f32> -> tensor<7xf32>
  %mean = stablehlo.reduce %gemm_bias, %init_mean {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = [0]} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // Divide mean by batch size (6)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %six : tensor<7xf32>

  // Broadcast mean to (6,7)
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>

  // Compute variance: var = mean((x - mean)^2)
  %diff = stablehlo.subtract %gemm_bias, %mean_broadcast : tensor<6x7xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  %init_var = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = []} : tensor<f32> -> tensor<7xf32>
  %var_sum = stablehlo.reduce %sq_diff, %init_var {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = [0]} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // Divide var_sum by batch size (6)
  %var = stablehlo.divide %var_sum, %six : tensor<7xf32>

  // Add eps = 1e-5 to var
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = stablehlo.broadcast_in_dim %eps {broadcast_dimensions = []} : tensor<f32> -> tensor<7xf32>
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Broadcast stddev to (6,7)
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7xf32>

  // Scale and shift: gamma * norm + beta
  // Broadcast gamma and beta to (6,7)
  %gamma_broadcast = stablehlo.broadcast_in_dim %arg2 {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>
  %beta_broadcast = stablehlo.broadcast_in_dim %arg3 {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<6x7xf32>

  %scaled = stablehlo.multiply %norm, %gamma_broadcast : tensor<6x7xf32>
  %batchnorm_out = stablehlo.add %scaled, %beta_broadcast : tensor<6x7xf32>

  // Step 3: GELU activation (approximate)
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // sqrt(2) ~ 1.4142135

  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>
  %sqrt2_broadcast = stablehlo.broadcast_in_dim %sqrt2 {broadcast_dimensions = []} : tensor<f32> -> tensor<6x7xf32>
  %x_div_sqrt2 = stablehlo.divide %batchnorm_out, %sqrt2_broadcast : tensor<6x7xf32>

  %erf_x = chlo.erf %x_div_sqrt2 : tensor<6x7xf32>

  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = []} : tensor<f32> -> tensor<6x7xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf_x : tensor<6x7xf32>

  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = stablehlo.broadcast_in_dim %half {broadcast_dimensions = []} : tensor<f32> -> tensor<6x7xf32>

  %mul1 = stablehlo.multiply %batchnorm_out, %half_broadcast : tensor<6x7xf32>
  %gelu = stablehlo.multiply %mul1, %one_plus_erf : tensor<6x7xf32>

  // Step 4: ReLU activation: max(0, x)
  %zero_broadcast = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = []} : tensor<f32> -> tensor<6x7xf32>
  %relu = stablehlo.maximum %gelu, %zero_broadcast : tensor<6x7xf32>

  func.return %relu : tensor<6x7xf32>
}

