func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<3x16x3x3x3xf32>, %arg2: tensor<16xf32>, %arg3: tensor<6x3x16x7x7xf32>) -> tensor<6x16x7x7xf32> {
