  // Input spatial dims: D=16, H=7, W=7
  // kernel_size=3, stride=2, padding=1, output_padding=1, dilation=1
  // Output size formula for conv_transpose:
  // output = (input - 1)*stride - 2*padding + dilation*(kernel_size-1) + output_padding + 1
  // For D: (16-1)*2 - 2*1 + 1*(3-1) + 1 + 1 = 15*2 - 2 + 2 + 1 + 1 = 30 - 2 + 2 + 1 + 1 = 32
  // For H: (7-1)*2 - 2*1 + 2 + 1 + 1 = 6*2 - 2 + 2 + 1 + 1 = 12 - 2 + 2 + 1 + 1 = 14
  // For W: same as H = 14

