  // bias shape: [16]
  // broadcast bias to [6,16,33,15,15]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<6x16x33x15x15xf32> broadcast_dimensions = [1]

