    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Add conv.bias (shape [7]) to conv_out (shape [6x7x4x4])
  // Broadcast conv_bias to [6x7x4x4]
  %conv_bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %conv_out_bias = stablehlo.add %conv_out, %conv_bias_broadcast : tensor<6x7x4x4xf32>

  // BatchNorm2d forward (training mode):
  // batch mean: reduce mean over batch, height, width dims: dims = [0, 2, 3]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %sum = "stablehlo.reduce"(%conv_out_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<7xf32>) -> tensor<7xf32>
  // mean = sum / (batch*height*width) = sum / (6*4*4) = sum / 96
  %denominator = stablehlo.constant dense<96.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %denominator : tensor<7xf32>

  // batch variance: reduce mean of squared difference over batch, height, width dims
  // compute (x - mean)^2
  // broadcast mean to [6x7x4x4]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %diff = stablehlo.subtract %conv_out_bias, %mean_broadcast : tensor<6x7x4x4xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x4x4xf32>
  %zero_f32_4d = stablehlo.constant dense<0.0> : tensor<f32>
  %init_var = stablehlo.broadcast_in_dim %zero_f32_4d {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>
  %sum_var = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<7xf32>) -> tensor<7xf32>
  %var = stablehlo.divide %sum_var, %denominator : tensor<7xf32>

  // epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1e-5> : tensor<f32>

  // var + epsilon
  %var_eps = stablehlo.add %var, %epsilon : tensor<7xf32>

  // sqrt(var + epsilon)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  // broadcast stddev to [6x7x4x4]
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7x4x4xf32>

  // Apply affine transform: y = norm * bn_weight + bn_bias
  // broadcast bn_weight and bn_bias to [6x7x4x4]
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %scaled = stablehlo.multiply %norm, %bn_weight_broadcast : tensor<6x7x4x4xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7x4x4xf32>

  // Multiply by scaling_factor = 2.0
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scaling_factor_broadcast = stablehlo.broadcast_in_dim %scaling_factor {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %output = stablehlo.multiply %bn_out, %scaling_factor_broadcast : tensor<6x7x4x4xf32>

  return %output : tensor<6x7x4x4xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
