    batch_group_count = 1,
    precision_config = {}
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Step 2: Add conv.bias (broadcast over batch and spatial dims)
  // conv.bias shape: [7]
  // broadcast conv.bias to [6,7,4,4]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7x4x4xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x4x4xf32>

