  // BatchNorm formula (training):
  // mean = reduce_mean over batch and spatial dims (0,2,3)
  // var = reduce_mean((x - mean)^2) over batch and spatial dims (0,2,3)
  // normalized = (x - mean) / sqrt(var + eps)
  // output = gamma * normalized + beta
  // gamma = bn.weight (%arg2), beta = bn.bias (%arg3)
  // eps = 1e-5

