  %x_centered = stablehlo.subtract %conv_bias, %mean_broadcast : tensor<6x7x4x4xf32>

  // Compute squared difference (x - mean)^2
  %sq_diff = stablehlo.multiply %x_centered, %x_centered : tensor<6x7x4x4xf32>

