    dimensions = [0, 2, 3],
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

  %var_scaled = stablehlo.divide %var, %divisor : tensor<7xf32>

  // eps = 1e-5
  %eps = stablehlo.constant dense<1.000000e-5> : tensor<f32>

