  %scaling_broadcast = stablehlo.broadcast_in_dim %scaling_factor : tensor<f32> to tensor<6x7x4x4xf32> broadcast_dimensions = []

  // Multiply bn_out * scaling_factor
  %output = stablehlo.multiply %bn_out, %scaling_broadcast : tensor<6x7x4x4xf32>

  func.return %output : tensor<6x7x4x4xf32>
}

func.func @main(%conv_weight: tensor<7x8x3x3xf32>, %conv_bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // Convolution:
  // conv.weight shape: [out_channels=7, in_channels=8, kernel_h=3, kernel_w=3]
  // input shape: [batch=6, in_channels=8, height=6, width=6]
  // output shape: [batch=6, out_channels=7, out_h=4, out_w=4]
  %conv_out = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Add conv.bias (shape [7]) to conv_out (shape [6x7x4x4])
  // Broadcast conv_bias to [6x7x4x4]
  %conv_bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %conv_out_biased = stablehlo.add %conv_out, %conv_bias_broadcast : tensor<6x7x4x4xf32>

