  // For each channel (7), compute mean and variance over batch and spatial dims (axes 0,2,3)
  // conv_out_biased shape: [6,7,4,4]
  // Compute mean over dims [0,2,3] -> result shape [7]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean = "stablehlo.reduce"(%conv_out_biased, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3}} : (tensor<6x7x4x4xf32>, tensor<7xf32>) -> tensor<7xf32>

  // Compute divisor = batch_size * height * width = 6*4*4=96 as f32 constant
  %const_96 = stablehlo.constant dense<96.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %const_96 : tensor<7xf32>

  // Compute squared difference (x - mean)^2
  // Broadcast mean_div to [6x7x4x4]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %diff = stablehlo.subtract %conv_out_biased, %mean_broadcast : tensor<6x7x4x4xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x4x4xf32>

  // Compute variance = sum(diff_sq) / 96 over dims [0,2,3]
  %init_var = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3}} : (tensor<6x7x4x4xf32>, tensor<7xf32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %const_96 : tensor<7xf32>

  // Compute invstd = 1 / sqrt(variance + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
  %sqrt_var_eps = stablehlo.sqrt %var_eps : tensor<7xf32>
