  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %invstd = stablehlo.divide %one, %sqrt_var_eps : tensor<7xf32>

  // Normalize: (x - mean) * invstd
  // Broadcast mean_div and invstd to [6x7x4x4]
  %invstd_broadcast = "stablehlo.broadcast_in_dim"(%invstd) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
