  %x_norm = stablehlo.multiply %x_centered, %invstd_broadcast : tensor<6x7x4x4xf32>

  // Scale and shift: y = gamma * x_norm + beta
  // bn_weight = gamma, bn_bias = beta, shape [7]
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %scaled = stablehlo.multiply %x_norm, %bn_weight_broadcast : tensor<6x7x4x4xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7x4x4xf32>

  // Multiply by scaling_factor = 2.0 (constant)
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scaling_factor_broadcast = "stablehlo.broadcast_in_dim"(%scaling_factor) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %result = stablehlo.multiply %bn_out, %scaling_factor_broadcast : tensor<6x7x4x4xf32>

  return %result : tensor<6x7x4x4xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
