  %rsqrt_broadcast = stablehlo.broadcast_in_dim %rsqrt : tensor<7xf32> to tensor<6x7x4x4xf32> broadcast_dimensions = [1]
  %norm = stablehlo.multiply %diff, %rsqrt_broadcast : tensor<6x7x4x4xf32>

