  %gamma_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7x4x4xf32> broadcast_dimensions = [1]
  %scaled = stablehlo.multiply %norm, %gamma_broadcast : tensor<6x7x4x4xf32>

