  %beta_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<7xf32> to tensor<6x7x4x4xf32> broadcast_dimensions = [1]
  %bn_out = stablehlo.add %scaled, %beta_broadcast : tensor<6x7x4x4xf32>

  // 4) Multiply by scaling_factor = 2.0
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scaling_factor_broadcast = stablehlo.broadcast_in_dim %scaling_factor : tensor<f32> to tensor<6x7x4x4xf32> broadcast_dimensions = []
  %final = stablehlo.multiply %bn_out, %scaling_factor_broadcast : tensor<6x7x4x4xf32>

  func.return %final : tensor<6x7x4x4xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
