    padding = [0, 0, 0, 0],
    lhs_dilate = [],
    rhs_dilate = [],
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {},
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2, 3],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2, 3],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3]
    }
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Step 2: Add conv.bias (broadcast over batch and spatial dims)
  // conv.bias shape: [7]
  // conv output shape: [6,7,4,4]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7x4x4xf32> broadcast_dimensions = [1]
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x4x4xf32>

  // Step 3: BatchNorm2d (training mode)
  // BatchNorm formula (training):
  // y = gamma * (x - mean) / sqrt(var + eps) + beta
  // mean and var computed over batch and spatial dims per channel
