  %cst_one = stablehlo.constant 1 : index
  %cst_two = stablehlo.constant 2 : index

  // reduce dims for mean: dims = [0,2,3]
  %mean = stablehlo.reduce %conv_bias dimensions = [0, 2, 3] {
    ^bb0(%a: f32, %b: f32):
      %sum = stablehlo.add %a, %b : f32
      stablehlo.return %sum : f32
  } : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

  // compute count = 6*4*4 = 96 as f32 constant
  %cst_96 = stablehlo.constant 96.0 : f32
  %mean_div = stablehlo.divide %mean, %cst_96 : tensor<7xf32>

