  %diff = stablehlo.subtract %conv_bias, %mean_broadcast : tensor<6x7x4x4xf32>

  %sq_diff = stablehlo.multiply %diff, %diff : tensor<6x7x4x4xf32>

  %var_sum = stablehlo.reduce %sq_diff dimensions = [0, 2, 3] {
    ^bb0(%a: f32, %b: f32):
      %sum = stablehlo.add %a, %b : f32
      stablehlo.return %sum : f32
  } : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

  %var = stablehlo.divide %var_sum, %cst_96 : tensor<7xf32>

  // epsilon for numerical stability
  %eps = stablehlo.constant 1.000000e-05 : f32

  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // normalize: (x - mean) / stddev
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev : tensor<7xf32> to tensor<6x7x4x4xf32> broadcast_dimensions = [1]

  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7x4x4xf32>

  // scale and shift: gamma * norm + beta
  %gamma_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7x4x4xf32> broadcast_dimensions = [1]
  %beta_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<7xf32> to tensor<6x7x4x4xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %gamma_broadcast, %norm : tensor<6x7x4x4xf32>
  %bn_out = stablehlo.add %scaled, %beta_broadcast : tensor<6x7x4x4xf32>

  // Step 4: Multiply by scaling_factor = 2.0 (constant scalar)
  %scaling_factor = stablehlo.constant 2.0 : f32
  %scaling_broadcast = stablehlo.broadcast_in_dim %scaling_factor : tensor<f32> to tensor<6x7x4x4xf32> broadcast_dimensions = []

  %final = stablehlo.multiply %bn_out, %scaling_broadcast : tensor<6x7x4x4xf32>

  stablehlo.return %final : tensor<6x7x4x4xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
