  %divisor = stablehlo.constant dense<96.0> : tensor<f32>
  %mean_scaled = stablehlo.divide %mean, %divisor : tensor<7xf32>

  // Broadcast mean to [6,7,4,4]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %mean_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%mean_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>

