func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x8x8xf32>) -> tensor<6xf32> {
  // %arg0: conv.weight with shape [out_channels=7, in_channels=8, kernel_h=3, kernel_w=3]
  // %arg1: conv.bias with shape [7]
  // %arg2: input with shape [batch=6, in_channels=8, height=8, width=8]

  // Convolution parameters:
  // input NHWC is not given, input is NCHW, so we use convolution with dimension numbers:
  // input: NCHW = [6,8,8,8]
  // kernel: OIHW = [7,8,3,3]
  // output: NCHW = [6,7,6,6] because (8-3+1)=6 with default stride=1, padding=0, dilation=1

  // Convolution dimension numbers:
  // input: batch=0, feature=1, spatial=[2,3]
  // kernel: output_feature=0, input_feature=1, spatial=[2,3]
  // output: batch=0, feature=1, spatial=[2,3]

  // Perform convolution
  %conv = stablehlo.convolution %arg2, %arg0 {
    window_strides = [1, 1],
    padding = [0, 0, 0, 0],
    lhs_dilate = [],
    rhs_dilate = [],
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {operand_precision = []},
    dimension_numbers = {
      lhs_batch_dimension = 0,
      lhs_feature_dimension = 1,
      lhs_spatial_dimensions = [2, 3],
      rhs_output_feature_dimension = 0,
      rhs_input_feature_dimension = 1,
      rhs_spatial_dimensions = [2, 3],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3]
    }
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6,7,6,6]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7x6x6xf32> broadcast_dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Average Pooling with kernel size 4x4, stride=4 (default stride = kernel size)
  // Input shape: [6,7,6,6]
  // Pool kernel: 4x4
  // Output shape: floor((6-4)/4)+1 = 1 for each spatial dimension, so output shape [6,7,1,1]

  %avg_pool = stablehlo.reduce_window %conv_bias {
    window_dimensions = [1, 1, 4, 4],
    window_strides = [1, 1, 4, 4],
    padding = [0, 0, 0, 0, 0, 0, 0, 0],
    base_dilation = [],
    window_dilation = [],
    // Use add as reduction, initial value 0
  } : tensor<6x7x6x6xf32> to tensor<6x7x1x1xf32> {
    body = (arg0: f32, arg1: f32) -> (f32) {
      %add = stablehlo.add arg0, arg1 : f32
      stablehlo.return %add : f32
    },
    init_value = stablehlo.constant 0.0 : f32
  }

  // Divide by window size (4*4=16) to get average
  %window_size = stablehlo.constant 16.0 : f32
  %window_size_broadcast = stablehlo.broadcast_in_dim %window_size : tensor<f32> to tensor<6x7x1x1xf32> broadcast_dimensions = []
  %avg_pool_result = stablehlo.divide %avg_pool, %window_size_broadcast : tensor<6x7x1x1xf32>

  // Remove spatial dims 1x1 by reshape to [6,7]
  %avg_pool_reshaped = stablehlo.reshape %avg_pool_result : tensor<6x7x1x1xf32> to tensor<6x7xf32>

  // Apply sigmoid elementwise: sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %avg_pool_reshaped : tensor<6x7xf32>
  %exp = stablehlo.exponential %neg : tensor<6x7xf32>
  %one = stablehlo.constant 1.0 : f32
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x7xf32> broadcast_dimensions = []
  %denom = stablehlo.add %one_broadcast, %exp : tensor<6x7xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<6x7xf32>

