  %sum = stablehlo.reduce %sigmoid {
    dimensions = [1],
    body = (arg0: f32, arg1: f32) -> (f32) {
      %add = stablehlo.add arg0, arg1 : f32
      stablehlo.return %add : f32
    }
  } : tensor<6x7xf32> to tensor<6xf32>

  stablehlo.return %sum : tensor<6xf32>
}

