  %slice_limit = dense<[6,5]> : tensor<2xi32>
  %slice_strides = dense<[1,1]> : tensor<2xi32>
  %sliced = stablehlo.slice %arg0 {
    start_indices = %slice_start,
    limit_indices = %slice_limit,
    strides = %slice_strides
  } : (tensor<6x6xf32>) -> tensor<6x5xf32>

