func.func @main(%arg0: tensor<1xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg5: input x, shape [6,7]
  // matmul: x @ weight^T + bias
  // weight shape: [7,7], but PyTorch Linear weight is [out_features, in_features]
  // So matmul.weight is [7,7], input [6,7], output [6,7]
  // matmul: dot_general with contracting dims ([1],[1]) and batch dims ([0],[0])
  // Actually, input is [6,7], weight is [7,7], so we do dot_general with contracting dims ([1],[1])?
  // Wait, PyTorch Linear does x @ weight.T + bias, weight shape [out_features, in_features]
  // So weight is [7,7], input [6,7], output [6,7]
  // So dot_general contracting dims ([1],[1]) with batch dims ([0],[0]) is not correct.
  // Actually, dot_general contracting dims ([1],[1]) means summing over input dim 1 and weight dim 1.
  // But weight dim 1 is in_features, so weight should be transposed.
  // So we do dot_general with contracting dims ([1],[0]) to do x @ weight^T
  // x: [6,7], weight: [7,7], contracting dims ([1],[0]) -> output [6,7]

  // Step 1: matmul x @ weight^T
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    lhs_batching_dimensions = [0],
    rhs_batching_dimensions = [1],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Step 2: add matmul.bias (shape [7]) broadcasted over batch dim 0
  %1 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // Step 3: batch norm 1d forward in training mode
  // BatchNorm1d formula:
  // mean = reduce_mean over batch dim 0
  // var = reduce_mean((x - mean)^2) over batch dim 0
  // normalized = (x - mean) / sqrt(var + eps)
  // output = normalized * weight + bias (bn.weight and bn.bias)
  // shapes: x: [6,7], mean: [7], var: [7], weight: [7], bias: [7]

  // Compute mean over batch dim 0
  %3 = "stablehlo.reduce"(%2) ( {
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  }) {dimensions = [0]} : (tensor<6x7xf32>) -> tensor<7xf32>

  // mean = sum / batch_size (6)
  %c6 = stablehlo.constant 6.0 : f32
  %4 = stablehlo.div %3, %c6 : tensor<7xf32>

  // Broadcast mean to [6,7]
  %5 = "stablehlo.broadcast_in_dim"(%4) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Compute (x - mean)
  %6 = stablehlo.sub %2, %5 : tensor<6x7xf32>

  // Compute squared difference (x - mean)^2
  %7 = stablehlo.mul %6, %6 : tensor<6x7xf32>

  // Compute variance = mean of squared differences over batch dim 0
  %8 = "stablehlo.reduce"(%7) ( {
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  }) {dimensions = [0]} : (tensor<6x7xf32>) -> tensor<7xf32>

  // var = sum / batch_size (6)
  %9 = stablehlo.div %8, %c6 : tensor<7xf32>

  // Add eps (1e-5) to variance
  %c_eps = stablehlo.constant 0.00001 : f32
  %10 = stablehlo.add %9, %c_eps : tensor<7xf32>

  // Compute rsqrt(var + eps)
  %11 = stablehlo.rsqrt %10 : tensor<7xf32>

  // Broadcast rsqrt to [6,7]
  %12 = "stablehlo.broadcast_in_dim"(%11) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %13 = stablehlo.mul %6, %12 : tensor<6x7xf32>

  // Apply scale (bn.weight) and shift (bn.bias)
  // Broadcast bn.weight and bn.bias to [6,7]
  %14 = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %15 = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>

  %16 = stablehlo.mul %13, %14 : tensor<6x7xf32>
  %17 = stablehlo.add %16, %15 : tensor<6x7xf32>

  // Step 4: add bias (parameter %arg0 shape [1]) broadcasted to [6,7]
  %18 = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = [], output_shape = [6,7]} : (tensor<1xf32>) -> tensor<6x7xf32>
  %19 = stablehlo.add %17, %18 : tensor<6x7xf32>

  // Step 5: divide by divide_value = 1.0 (no-op)
  // So skip division

  // Step 6: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %20 = stablehlo.neg %19 : tensor<6x7xf32>
  %21 = stablehlo.exp %20 : tensor<6x7xf32>
  %c1 = stablehlo.constant 1.0 : f32
  %22 = stablehlo.add %21, %c1 : tensor<6x7xf32>
  %23 = stablehlo.div %c1, %22 : tensor<6x7xf32>
  %24 = stablehlo.mul %19, %23 : tensor<6x7xf32>

  // Return result
  stablehlo.return %24 : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<1xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg5: input x, shape [6,7]
  // %arg1: matmul.weight, shape [7,7]
  // %arg2: matmul.bias, shape [7]
  // %arg3: bn.weight (gamma), shape [7]
  // %arg4: bn.bias (beta), shape [7]
  // %arg0: bias, shape [1]

  // Step 1: matmul: x @ weight + bias
  // dot_general with contracting dims [1] of lhs and [0] of rhs
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    lhs_batching_dimensions = [0],
    rhs_batching_dimensions = [1],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  %1 = stablehlo.add %0, stablehlo.broadcast_in_dim %arg2 : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>
  // %1 is matmul output with bias added

  // Step 2: BatchNorm1d forward (training mode)
  // Compute mean over batch dimension (dim=0)
  %2 = stablehlo.reduce %1, %cst0 = stablehlo.constant 0.0 : tensor<6x7xf32>, tensor<f32> {
    dimensions = [0],
    body = {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // Actually stablehlo.reduce needs a region with proper ops, rewrite:

  %cst0 = stablehlo.constant 0.0 : tensor<f32>
  %mean = stablehlo.reduce %1, %cst0 {
    dimensions = [0],
    body = {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // mean = sum over batch dim, shape [7]
  // divide by batch size 6.0
  %cst6 = stablehlo.constant 6.0 : tensor<f32>
  %mean_f = stablehlo.div %mean, %cst6 : tensor<7xf32>

  // Compute variance: mean of squared differences
  // First compute (x - mean)
  // Broadcast mean [7] to [6,7]
  %mean_bcast = stablehlo.broadcast_in_dim %mean_f : tensor<7xf32> to tensor<6x7xf32> dimensions = [1]

  %diff = stablehlo.subtract %1, %mean_bcast : tensor<6x7xf32>

  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  %var_sum = stablehlo.reduce %diff_sq, %cst0 {
    dimensions = [0],
    body = {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  %var = stablehlo.div %var_sum, %cst6 : tensor<7xf32>

  // Compute invstd = 1 / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.00000001e-5> : tensor<f32>
  %eps_bcast = stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<7xf32> dimensions = []

  %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>

  %sqrt_var_eps = stablehlo.sqrt %var_eps : tensor<7xf32>

  %invstd = stablehlo.div %cst1 = stablehlo.constant 1.0 : tensor<f32>, %sqrt_var_eps : tensor<7xf32>

  // Normalize: (x - mean) * invstd
  %invstd_bcast = stablehlo.broadcast_in_dim %invstd : tensor<7xf32> to tensor<6x7xf32> dimensions = [1]

  %norm = stablehlo.multiply %diff, %invstd_bcast : tensor<6x7xf32>

  // Scale and shift: norm * gamma + beta
  %gamma_bcast = stablehlo.broadcast_in_dim %arg3 : tensor<7xf32> to tensor<6x7xf32> dimensions = [1]
  %beta_bcast = stablehlo.broadcast_in_dim %arg4 : tensor<7xf32> to tensor<6x7xf32> dimensions = [1]

  %scaled = stablehlo.multiply %norm, %gamma_bcast : tensor<6x7xf32>
  %shifted = stablehlo.add %scaled, %beta_bcast : tensor<6x7xf32>

  // Step 3: Add bias (arg0) shape [1], broadcast to [6,7]
  %bias_bcast = stablehlo.broadcast_in_dim %arg0 : tensor<1xf32> to tensor<6x7xf32> dimensions = []

  %add_bias = stablehlo.add %shifted, %bias_bcast : tensor<6x7xf32>

  // Step 4: Divide by divide_value=1.0 (no-op)
  // Just keep %add_bias as is

  // Step 5: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %add_bias : tensor<6x7xf32>
  %exp_neg = stablehlo.exp %neg : tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x7xf32> dimensions = []
  %denom = stablehlo.add %one_bcast, %exp_neg : tensor<6x7xf32>
  %sigmoid = stablehlo.div %one_bcast, %denom : tensor<6x7xf32>

  %swish = stablehlo.multiply %add_bias, %sigmoid : tensor<6x7xf32>

  // Return result
  stablehlo.return %swish : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<1xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg5: input x, shape [6,7]
  // Linear layer: y = x @ weight^T + bias
  // %arg1: weight [7,7], %arg2: bias [7]
  // We do dot_general with lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[1]
  // and no batching dims, output shape [6,7]
  %linear = "stablehlo.dot_general"(%arg5, %arg1) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %linear_bias = stablehlo.add %linear, %arg2 : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // input shape: [6,7]
  // compute mean over batch dim (dim=0), shape [7]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.constant dense<0.0> : tensor<7xf32>
  %mean = "stablehlo.reduce"(%linear_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>
  %mean_div = stablehlo.divide %mean, %six_bcast : tensor<7xf32>

  // compute variance over batch dim (dim=0), shape [7]
  // variance = mean((x - mean)^2)
  // first broadcast mean to [6,7]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %linear_bias, %mean_bcast : tensor<6x7xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = stablehlo.constant dense<0.0> : tensor<7xf32>
  %var_sum = "stablehlo.reduce"(%sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six_bcast : tensor<7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>
  %rsqrt_var_eps = stablehlo.rsqrt %var_eps : tensor<7xf32>
  // Broadcast rsqrt_var_eps and bn.weight and bn.bias to [6,7]
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 0} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 0} : (tensor<7xf32>) -> tensor<6x7xf32>
  %rsqrt_bcast = "stablehlo.broadcast_in_dim"(%rsqrt_var_eps) {broadcast_dimensions = array<i64: 0} : (tensor<7xf32>) -> tensor<6x7xf32>

  // normalized = (x - mean) * rsqrt(var + eps)
  %normalized = stablehlo.multiply %diff, %rsqrt_bcast : tensor<6x7xf32>
  // scale and shift: normalized * weight + bias
  %scaled = stablehlo.multiply %normalized, %bn_weight_bcast : tensor<6x7xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_bcast : tensor<6x7xf32>

  // Add bias parameter %arg0 (shape [1]) broadcast to [6,7]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1} : (tensor<1xf32>) -> tensor<6x7xf32>
  %biased = stablehlo.add %bn_out, %bias_bcast : tensor<6x7xf32>

  // Divide by divide_value=1.0 (no-op but included)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %divided = stablehlo.divide %biased, %one_bcast : tensor<6x7xf32>

  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %divided : tensor<6x7xf32>
  %exp = stablehlo.exponential %neg : tensor<6x7xf32>
  %one_scalar = stablehlo.constant dense<1.0> : tensor<f32>
  %one_scalar_bcast = "stablehlo.broadcast_in_dim"(%one_scalar) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %exp_plus_one = stablehlo.add %exp, %one_scalar_bcast : tensor<6x7xf32>
  %sigmoid = stablehlo.divide %one_scalar_bcast, %exp_plus_one : tensor<6x7xf32>
  %swish = stablehlo.multiply %divided, %sigmoid : tensor<6x7xf32>

  "stablehlo.return"(%swish) : tensor<6x7xf32>
}

func.func @main(%bias: tensor<1xf32>, %matmul_weight: tensor<7x7xf32>, %matmul_bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
