  %matmul_out = stablehlo.dot_general %input, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %matmul_out_bias = stablehlo.add %matmul_out, %matmul_bias : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // mean = reduce mean over batch dim 0 -> shape [7]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = stablehlo.reduce %matmul_out_bias, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } {dimensions = dense<[0]> : tensor<1xi64>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %six : tensor<7xf32>

  // variance = reduce mean of (x - mean)^2 over batch dim 0
  // broadcast mean to [6x7]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean
    {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : tensor<7xf32> -> tensor<6x7xf32>
  %diff = stablehlo.subtract %matmul_out_bias, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %var_sum = stablehlo.reduce %diff_sq, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } {dimensions = dense<[0]> : tensor<1xi64>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %variance = stablehlo.divide %var_sum, %six : tensor<7xf32>

  // Normalize: (x - mean) / sqrt(variance + eps)
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %variance, %eps : tensor<7xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>
