  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %one_broadcast_2d = "stablehlo.broadcast_in_dim"(%one_broadcast) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %divided = stablehlo.divide %biased, %one_broadcast_2d : tensor<6x7xf32>

  // Step 5: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %divided : tensor<6x7xf32>
  %exp_neg = stablehlo.exponential %neg : tensor<6x7xf32>
  %one_2d = stablehlo.constant dense<1.0> : tensor<f32>
  %one_2d_broadcast = "stablehlo.broadcast_in_dim"(%one_2d) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %denom = stablehlo.add %one_2d_broadcast, %exp_neg : tensor<6x7xf32>
  %sigmoid = stablehlo.divide %one_2d_broadcast, %denom : tensor<6x7xf32>
  %swish = stablehlo.multiply %divided, %sigmoid : tensor<6x7xf32>

  return %swish : tensor<6x7xf32>
}

