  %subtract_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %x_sub = stablehlo.subtract %x_gemm, %subtract_broadcast : tensor<6x7xf32>

