  %15 = stablehlo.multiply %half_broadcast, %mul2 : tensor<6x1xf32>

  stablehlo.return %15 : tensor<6x1xf32>
}

// Constants used in reductions and computations
// Negative infinity for max reduction initial value
// Zero for sums and comparisons
// These constants are defined outside the function for clarity
// but can be inlined if preferred.
module {
  stablehlo.constant dense<-inf> : tensor<f32> {sym_name = "cst_neg_inf"}
  stablehlo.constant dense<0.0> : tensor<f32> {sym_name = "cst_0"}
}

func.func @main(%linear_weight: tensor<7x7xf32>, %linear_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: x @ W^T + b
  // %linear_weight shape: [7,7], %input shape: [6,7]
  // We want (6x7) @ (7x7)^T = (6x7) @ (7x7) = (6x7)
  // So transpose linear_weight to get W^T: (7x7) -> (7x7) (transpose dims 1,0)
  %weight_t = "stablehlo.transpose"(%linear_weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %matmul = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %output_linear = stablehlo.add %matmul, "stablehlo.broadcast_in_dim"(%linear_bias) {broadcast_dimensions = array<i64: 1} } : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // LogSumExp over dim=1, keepdim=True
  // stablehlo.reduce with max for numerical stability
  %init_max = stablehlo.constant dense<-inf> : tensor<f32>
  %max = "stablehlo.reduce"(%output_linear, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast max to shape (6x7)
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0} } : (tensor<6xf32>) -> tensor<6x7xf32>
  // Subtract max for numerical stability
  %shifted = stablehlo.subtract %output_linear, %max_broadcast : tensor<6x7xf32>
  // exp(shifted)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7xf32>
  // sum exp(shifted) over dim=1
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6xf32>
  // add max back
  %logsumexp = stablehlo.add %log_sum_exp, %max : tensor<6xf32>
  // reshape to (6x1)
  %logsumexp_reshaped = "stablehlo.broadcast_in_dim"(%logsumexp) {broadcast_dimensions = array<i64: 0} } : (tensor<6xf32>) -> tensor<6x1xf32>

  // LeakyReLU with negative_slope=0.01 applied twice
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_6x1 = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0} } : (tensor<f32>) -> tensor<6x1xf32>
  // First LeakyReLU
  %max_part1 = stablehlo.maximum %logsumexp_reshaped, %zero_6x1 : tensor<6x1xf32>
  %min_part1 = stablehlo.minimum %logsumexp_reshaped, %zero_6x1 : tensor<6x1xf32>
  %slope = stablehlo.constant dense<0.01> : tensor<f32>
  %slope_broadcast = "stablehlo.broadcast_in_dim"(%slope) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %scaled_min1 = stablehlo.multiply %min_part1, %slope_broadcast : tensor<6x1xf32>
  %leaky1 = stablehlo.add %max_part1, %scaled_min1 : tensor<6x1xf32>
