  %max_part2 = stablehlo.maximum %leaky1, %zero_6x1 : tensor<6x1xf32>
  %min_part2 = stablehlo.minimum %leaky1, %zero_6x1 : tensor<6x1xf32>
  %scaled_min2 = stablehlo.multiply %min_part2, %slope_broadcast : tensor<6x1xf32>
  %leaky2 = stablehlo.add %max_part2, %scaled_min2 : tensor<6x1xf32>

  // GELU applied twice
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %inv_sqrt2 = stablehlo.divide %one, %sqrt2_broadcast : tensor<6x1xf32>

  // First GELU
  %x_div_sqrt2 = stablehlo.multiply %leaky2, %inv_sqrt2 : tensor<6x1xf32>
  %erf_x = chlo.erf %x_div_sqrt2 : tensor<6x1xf32> -> tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one, %erf_x : tensor<6x1xf32>
  %mul1 = stablehlo.multiply %leaky2, %one_plus_erf : tensor<6x1xf32>
  %gelu1 = stablehlo.multiply %half, %mul1 : tensor<6x1xf32>

  // Second GELU
  %x_div_sqrt2_2 = stablehlo.multiply %gelu1, %inv_sqrt2 : tensor<6x1xf32>
  %erf_x_2 = chlo.erf %x_div_sqrt2_2 : tensor<6x1xf32> -> tensor<6x1xf32>
  %one_plus_erf_2 = stablehlo.add %one, %erf_x_2 : tensor<6x1xf32>
  %mul2 = stablehlo.multiply %gelu1, %one_plus_erf_2 : tensor<6x1xf32>
  %gelu2 = stablehlo.multiply %half, %mul2 : tensor<6x1xf32>

  "stablehlo.return"(%gelu2) : tensor<6x1xf32>
}

func.func @main(%linear_weight: tensor<7x7xf32>, %linear_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: y = x * W^T + b
  // %input: [6x7], %linear_weight: [7x7], want output [6x7]
  // dot_general with contracting dims: input dim 1 and weight dim 1 (weight transposed)
  %linear_out = "stablehlo.dot_general"(%input, %linear_weight) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias [7] to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%linear_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out_bias = stablehlo.add %linear_out, %bias_broadcast : tensor<6x7xf32>

