  // 2) subtract max_per_row from linear_out_bias for stability
  %linear_out_bias_reshaped = %linear_out_bias : tensor<6x7xf32>
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_per_row) {broadcast_dimensions = array<i64: 0} : (tensor<6xf32>) -> tensor<6x1xf32>
  %max_broadcast_7 = "stablehlo.broadcast_in_dim"(%max_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x1xf32>) -> tensor<6x7xf32>
  %shifted = stablehlo.subtract %linear_out_bias, %max_broadcast_7 : tensor<6x7xf32>

  // 3) exp(shifted)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7xf32>

  // 4) sum exp_shifted over dim=1 -> [6]
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // 5) log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6xf32>

  // 6) add back max_per_row [6] + [6] -> [6]
  %log_sum_exp_plus_max = stablehlo.add %log_sum_exp, %max_per_row : tensor<6xf32>

  // 7) reshape to [6x1]
  %log_sum_exp_reshaped = "stablehlo.broadcast_in_dim"(%log_sum_exp_plus_max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // LeakyReLU with negative_slope=0.01 applied twice
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>

  // First LeakyReLU
  %gt_zero = "stablehlo.compare"(%log_sum_exp_reshaped, %zero_bcast) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xi1>
  %max_part = "stablehlo.select"(%gt_zero, %log_sum_exp_reshaped, %zero_bcast) : (tensor<6x1xi1>, tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
  %min_part = "stablehlo.select"(%gt_zero, %zero_bcast, %log_sum_exp_reshaped) : (tensor<6x1xi1>, tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
  %slope_const = stablehlo.constant dense<0.01> : tensor<f32>
  %slope_bcast = "stablehlo.broadcast_in_dim"(%slope_const) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %min_scaled = stablehlo.multiply %min_part, %slope_bcast : tensor<6x1xf32>
  %leaky_relu1 = stablehlo.add %max_part, %min_scaled : tensor<6x1xf32>

  // Second LeakyReLU (same as first, applied to leaky_relu1)
  %gt_zero2 = "stablehlo.compare"(%leaky_relu1, %zero_bcast) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xi1>
  %max_part2 = "stablehlo.select"(%gt_zero2, %leaky_relu1, %zero_bcast) : (tensor<6x1xi1>, tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
  %min_part2 = "stablehlo.select"(%gt_zero2, %zero_bcast, %leaky_relu1) : (tensor<6x1xi1>, tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
  %min_scaled2 = stablehlo.multiply %min_part2, %slope_bcast : tensor<6x1xf32>
  %leaky_relu2 = stablehlo.add %max_part2, %min_scaled2 : tensor<6x1xf32>

  // GELU applied twice
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>

  // First GELU
  %x_div_sqrt2 = stablehlo.divide %leaky_relu2, %sqrt2_bcast : tensor<6x1xf32>
  %erf_x = chlo.erf %x_div_sqrt2 : tensor<6x1xf32> -> tensor<6x1xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one_bcast, %erf_x : tensor<6x1xf32>
  %mul1 = stablehlo.multiply

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // %arg0: linear.weight (7x7)
  // %arg1: linear.bias (7)
  // %arg2: input (6x7)

  // Compute linear output: x @ W^T + b
  // %arg0 is weight (7x7), but PyTorch Linear does x @ W^T + b
  // So we transpose weight to (7x7) (same shape, but transpose needed)
  %0 = stablehlo.transpose %arg0 {permutation = [1, 0]} : tensor<7x7xf32> to tensor<7x7xf32>
  // Dot: (6x7) @ (7x7) -> (6x7)
  %1 = stablehlo.dot_general %arg2, %0 {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : tensor<6x7xf32>, tensor<7x7xf32> -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %2 = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %3 = stablehlo.add %1, %2 : tensor<6x7xf32>

  // LogSumExp over dim=1, keepdim=True
  // Reduce over dim=1 with logsumexp:
  // logsumexp(x) = log(sum(exp(x)))
  // Steps:
  // 1) max over dim=1 (keepdim)
  %4 = stablehlo.reduce %3, %cst_neg_inf : tensor<6x7xf32>, tensor<f32> {
    dimensions = [1],
    body = {
      %a = stablehlo.compare %arg0, %arg1 direction = "gt" : tensor<f32>, tensor<f32>
      %res = stablehlo.select %a, %arg0, %arg1 : tensor<f32>
      stablehlo.return %res : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>
  // We need constant -inf for initial value
  // Define constant -inf
  %cst_neg_inf = stablehlo.constant dense<-inf> : tensor<f32>

  // Actually, constants must be defined before use, so move constant up
  // We'll reorder later

  // For clarity, define constants first:
  // -inf constant
  // 0.01 (negative_slope)
  // We'll define them now at top

  // Let's restart with constants first:

  // Constants
  %cst_neg_inf = stablehlo.constant dense<-inf> : tensor<f32>
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_one = stablehlo.constant dense<1.0> : tensor<f32>
  %cst_0_01 = stablehlo.constant dense<0.01> : tensor<f32>

  // Max over dim=1 keepdim
  %max = stablehlo.reduce %3, %cst_neg_inf : tensor<6x7xf32>, tensor<f32> {
    dimensions = [1],
    body = {
      %a = stablehlo.compare %arg0, %arg1 direction = "gt" : tensor<f32>, tensor<f32>
      %res = stablehlo.select %a, %arg0, %arg1 : tensor<f32>
      stablehlo.return %res : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // Broadcast max to (6x7)
  %max_bcast = stablehlo.broadcast_in_dim %max : tensor<6x1xf32> to tensor<6x7xf32> broadcast_dimensions = [0,1]

  // Subtract max for numerical stability
  %shifted = stablehlo.subtract %3, %max_bcast : tensor<6x7xf32>

  // exp(shifted)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7xf32>

  // sum exp over dim=1 keepdim
  %sum_exp = stablehlo.reduce %exp_shifted, %cst_zero : tensor<6x7xf32>, tensor<f32> {
    dimensions = [1],
    body = {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6x1xf32>

  // Add max back: logsumexp = max + log(sum(exp(x - max)))
  %logsumexp = stablehlo.add %max, %log_sum_exp : tensor<6x1xf32>

  // LeakyReLU with negative_slope=0.01 applied twice
  // LeakyReLU(x) = max(x, 0) + negative_slope * min(x, 0)
  // First LeakyReLU
  %zero_bcast = stablehlo.broadcast_in_dim %cst_zero : tensor<f32> to tensor<6x1xf32> broadcast_dimensions = []
  %max_part = stablehlo.maximum %logsumexp, %zero_bcast : tensor<6x1xf32>
  %min_part = stablehlo.minimum %logsumexp, %zero_bcast : tensor<6x1xf32>
  %scaled_min = stablehlo.multiply %min_part, %cst_0_01 : tensor<6x1xf32>
  %leaky1 = stablehlo.add %max_part, %scaled_min : tensor<6x1xf32>

  // Second LeakyReLU (same as first)
  %max_part2 = stablehlo.maximum %leaky1, %zero_bcast : tensor<6x1xf32>
  %min_part2 = stablehlo.minimum %leaky1, %zero_bcast : tensor<6x1xf32>
  %scaled_min2 = stablehlo.multiply %min_part2, %cst_0_01 : tensor<6x1xf32>
  %leaky2 = stablehlo.add %max_part2, %scaled_min2 : tensor<6x1xf32>

  // GELU applied twice
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Define constant sqrt(2)
  %cst_sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %cst_half = stablehlo.constant dense<0.5> : tensor<f32>
  %cst_one = stablehlo.constant dense<1.0> : tensor<f32>

  // First GELU
  %div1 = stablehlo.divide %leaky2, %cst_sqrt2 : tensor<6x1xf32>
  %erf1 = chlo.erf %div1 : tensor<6x1xf32>
  %add1 = stablehlo.add %erf1, %cst_one : tensor<6x1xf32>
  %mul1 = stablehlo.multiply %leaky2, %add1 : tensor<6x1xf32>
  %gelu1 = stablehlo.multiply %mul1, %cst_half : tensor<6x1xf32>

  // Second GELU
  %div2 = stablehlo.divide %gelu1, %cst_sqrt2 : tensor<6x1xf32>
  %erf2 = chlo.erf %div2 : tensor<6x1xf32>
  %add2 = stablehlo.add %erf2, %cst_one : tensor<6x1xf32>
  %mul2 = stablehlo.multiply %gelu1, %add2 : tensor<6x1xf32>
  %gelu2 = stablehlo.multiply %mul2, %cst_half : tensor<6x1xf32>

  // Return final result
  stablehlo.return %gelu2 : tensor<6x1xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // %arg0 = linear.weight (7x7)
  // %arg1 = linear.bias (7)
  // %arg2 = input (6x7)

  // Perform linear: x = %arg2 * %arg0^T + %arg1
  // We need to do dot_general with batch dimension 0 (batch=6), contracting dimension 1 of input and 1 of weight
  // But weight is 7x7, input is 6x7, so we want to do (6x7) dot (7x7) -> (6x7)
  // So lhs_batching_dimensions = [0], lhs_contracting_dimensions = [1]
  // rhs_contracting_dimensions = [0], rhs_batching_dimensions = [1]
  // But weight shape is 7x7, no batch dimension, so batching dims empty for rhs
  // Actually, weight is 7x7, input is 6x7, so contracting dims are input dim 1 and weight dim 0
  // So dot dims: lhs_batching = [0], rhs_batching = [], lhs_contracting = [1], rhs_contracting = [0]
  %dot = stablehlo.dot_general %arg2, %arg0 {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // LogSumExp over dim=1 with keepdim=1
  // Steps:
  // 1) max over dim=1 for numerical stability
  %init_max = stablehlo.constant dense<-inf> : tensor<f32>
  %max = stablehlo.reduce %linear_out, %init_max {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } dimensions = [1] : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast max to shape (6x7)
  %max_broadcast = stablehlo.broadcast_in_dim %max : tensor<6xf32> to tensor<6x7xf32> broadcast_dimensions = [0]

  // Subtract max for numerical stability
  %shifted = stablehlo.subtract %linear_out, %max_broadcast : tensor<6x7xf32>

  // exp(shifted)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7xf32>

  // sum exp over dim=1
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = stablehlo.reduce %exp_shifted, %init_zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
