  %mish = stablehlo.multiply %add_bias, %tanh_softplus : tensor<6x7x12x12xf32>

  // Add add_value = 0.5
  %add_value_const = stablehlo.constant dense<0.5> : tensor<f32>
  %add_value_broadcast = stablehlo.broadcast_in_dim %add_value_const : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []

  %mish_plus_add = stablehlo.add %mish, %add_value_broadcast : tensor<6x7x12x12xf32>

  // Hardtanh activation with min_val=-1, max_val=1
  %min_val_const = stablehlo.constant dense<-1.0> : tensor<f32>
  %min_val_broadcast = stablehlo.broadcast_in_dim %min_val_const : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []
  %max_val_const = stablehlo.constant dense<1.0> : tensor<f32>
  %max_val_broadcast = stablehlo.broadcast_in_dim %max_val_const : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []

  %clamp_min = stablehlo.maximum %mish_plus_add, %min_val_broadcast : tensor<6x7x12x12xf32>
  %hardtanh = stablehlo.minimum %clamp_min, %max_val_broadcast : tensor<6x7x12x12xf32>

  // Scale output by scale=2
  %scale_const = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = stablehlo.broadcast_in_dim %scale_const : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []

  %scaled_output = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  func.return %scaled_output : tensor<6x7x12x12xf32>
}

func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transpose convolution parameters:
  // %arg0: weight tensor of shape [in_channels=7, out_channels=7, kernel_h=3, kernel_w=3]
  // PyTorch ConvTranspose2d weight shape is (in_channels, out_channels/groups, kernel_h, kernel_w)
  // StableHLO convolution expects filter shape [KH, KW, output_channels, input_channels/groups]
  // So we need to transpose %arg0 from [7,7,3,3] to [3,3,7,7]
  %weight_transposed = stablehlo.transpose %arg0 : tensor<7x7x3x3xf32> to tensor<3x3x7x7xf32> {permutation = [2, 3, 1, 0]}

  // ConvTranspose2d in PyTorch is a backward convolution (gradient of conv) with stride, padding, output_padding.
  // StableHLO convolution op supports dimension_numbers and window_strides, padding, lhs_dilation for transposed conv.
  // We use convolution with lhs_dilation=stride to implement ConvTranspose2d.
  // Parameters:
  // stride=2, padding=1, output_padding=1
  // input shape: [6,7,6,6]
  // weight shape after transpose: [3,3,7,7]
  // output shape: [6,7,12,12]

  // Set convolution dimension numbers for NCHW format:
  // lhs (input): NCHW = [batch, in_channels, height, width]
  // rhs (filter): OHWI = [out_channels, height, width, in_channels] in normal conv
  // But here filter shape is [KH, KW, out_channels, in_channels], so dimension_numbers:
  // lhs: NCHW -> [0,1,2,3]
  // rhs: HWIO -> [0,1,2,3]
  // output: NCHW -> [0,1,2,3]
  // So dimension_numbers = {lhs_spec = "NCHW", rhs_spec = "HWIO", out_spec = "NCHW"}

  // lhs_dilation = stride = [2,2]
  // padding = [1,1]
  // output_padding = 1 means output size is increased by 1 in height and width compared to default conv transpose output.
  // StableHLO convolution does not have explicit output_padding param, so we adjust padding or output shape accordingly.
  // We will use padding = [1,1] and then slice or pad output to get exact output shape 12x12.

  // Perform convolution with lhs_dilation (transposed conv)
  %conv = stablehlo.convolution %arg2, %weight_transposed {
    window_strides = [1, 1],
    padding = [1, 1, 1, 1], // padding for height and width: low and high padding each 1
    lhs_dilation = [2, 2],
    dimension_numbers = #stablehlo.conv_dim_numbers<"NCHW", "HWIO", "NCHW">,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {operand_precision = [DEFAULT, DEFAULT]}
  } : tensor<6x7x6x6xf32>, tensor<3x3x7x7xf32> -> tensor<6x7x11x11xf32>

  // The output shape from above conv is [6,7,11,11], but we want [6,7,12,12].
  // Because output_padding=1 in PyTorch adds 1 to output spatial dims.
  // We pad output by 1 on bottom and right spatial dims.
  %pad_low = stablehlo.constant dense<0> : tensor<f32>
  %pad_high = stablehlo.constant dense<0> : tensor<f32>
  %padding_tensor = stablehlo.constant dense<[[0,0],[0,0],[0,1],[0,1]]> : tensor<4x2xi64>
  %conv_padded = stablehlo.pad %conv, %pad_low, %pad_high {
    edge_padding_low = [0, 0, 0, 0],
    edge_padding_high = [0, 0, 1, 1],
    interior_padding = [0, 0, 0, 0]
  } : tensor<6x7x11x11xf32> -> tensor<6x7x12x12xf32>

  // Add bias: %arg1 shape [7], broadcast to [6,7,12,12]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7x12x12xf32> broadcast_dimensions = [1]

  %add_bias = stablehlo.add %conv_padded, %bias_broadcast : tensor<6x7x12x12xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %exp_x = stablehlo.exponential %add_bias : tensor<6x7x12x12xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []
  %exp_x_plus_one = stablehlo.add %exp_x, %one_broadcast : tensor<6x7x12x12xf32>
  %softplus = stablehlo.log %exp_x_plus_one : tensor<6x7x12x12xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x12x12xf32>
  %mish = stablehlo.multiply %add_bias, %tanh_softplus : tensor<6x7x12x12xf32>

  // Add add_value = 0.5 (constant)
  %add_value = stablehlo.constant dense<0.5> : tensor<f32>
  %add_value_broadcast = stablehlo.broadcast_in_dim %add_value : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []
  %mish_plus_add = stablehlo.add %mish, %add_value_broadcast : tensor<6x7x12x12xf32>

  // Hardtanh activation with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %min_val_broadcast = stablehlo.broadcast_in_dim %min_val : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []
  %max_val_broadcast = stablehlo.broadcast_in_dim %max_val : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []
  %clamped_min = stablehlo.maximum %mish_plus_add, %min_val_broadcast : tensor<6x7x12x12xf32>
  %hardtanh = stablehlo.minimum %clamped_min, %max_val_broadcast : tensor<6x7x12x12xf32>

  // Scale output by scale=2 (constant)
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = stablehlo.broadcast_in_dim %scale : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions = []
  %scaled_output = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  func.return %scaled_output : tensor<6x7x12x12xf32>
}

// Conv dimension numbers attribute for convenience
// N = batch, C = channel, H = height, W = width
// lhs_spec = "NCHW", rhs_spec = "HWIO", out_spec = "NCHW"
#stablehlo.conv_dim_numbers = {
  lhs_spec = "NCHW",
  rhs_spec = "HWIO",
  out_spec = "NCHW"
}

func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // %arg0: conv_transpose.weight: [in_channels=7, out_channels=7, kernel_h=3, kernel_w=3]
  // %arg1: conv_transpose.bias: [out_channels=7]
  // %arg2: input: [batch=6, in_channels=7, height=6, width=6]

  // StableHLO ConvTranspose expects weight shape: [in_channels, out_channels, kernel_h, kernel_w]
  // which matches %arg0.

  // ConvTranspose2d parameters:
  // stride=2, padding=1, output_padding=1
  // input shape: [6,7,6,6]
  // weight shape: [7,7,3,3]
  // bias shape: [7]
  // output shape: [6,7,12,12]

  // Step 1: ConvTranspose2d
  // conv_transpose = conv_transpose(input, weight, bias, stride=2, padding=1, output_padding=1)

  // StableHLO conv op with feature_group_count=1, batch_group_count=1, dimension_numbers:
  // input: NCHW
  // kernel: IOHW (in_channels, out_channels, height, width)
  // output: NCHW

  // Create conv_transpose output shape: [6,7,12,12]
  // We will use conv with transpose=true

  // Create constants for strides, padding, output_padding
  %c2 = constant dense<2> : tensor<2xi64>
  %c1 = constant dense<1> : tensor<1xi64>
  %c01 = constant dense<1> : tensor<1xi64>  // for output_padding=1

  // ConvTranspose dimension numbers
  // input: NCHW -> [0,1,2,3]
  // kernel: IOHW -> [0,1,2,3]
  // output: NCHW -> [0,1,2,3]

  // Create dimension numbers attribute
  %dim_nums = stablehlo.conv_dimension_numbers {
    input_batch_dimension = 0,
    input_feature_dimension = 1,
    input_spatial_dimensions = [2, 3],
    kernel_input_feature_dimension = 0,
    kernel_output_feature_dimension = 1,
    kernel_spatial_dimensions = [2, 3],
    output_batch_dimension = 0,
    output_feature_dimension = 1,
    output_spatial_dimensions = [2, 3]
  }

  // Create padding attribute: padding=1 means pad 1 on both sides for height and width
  // padding is a list of pairs: [[pad_low, pad_high], [pad_low, pad_high]]
  // So padding = [[1,1],[1,1]]
  %padding = constant dense<[[1,1],[1,1]]> : tensor<2x2xi64>

  // output_padding=1 means output_padding for each spatial dim is 1
  // StableHLO conv_transpose op uses output_padding attribute as array of i64
  %output_padding = constant dense<[1,1]> : tensor<2xi64>

  // bias add after conv_transpose

  // Perform conv_transpose
  %conv = stablehlo.convolution_transpose %arg2, %arg0 {
    strides = %c2,
    padding = %padding,
    output_padding = %output_padding,
    dimension_numbers = %dim_nums,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = null
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: bias shape [7], broadcast to [6,7,12,12]
  // Broadcast bias on batch, height, width dims
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7x12x12xf32> broadcast_dimensions=[1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Step 2: Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  // tanh(softplus(x))
  // mish(x) = x * tanh(softplus(x))

  // Compute exp(x)
  %exp = stablehlo.exp %conv_bias : tensor<6x7x12x12xf32>

  // Compute 1 + exp(x)
  %one = constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions=[]
  %exp_plus_one = stablehlo.add %exp, %one_broadcast : tensor<6x7x12x12xf32>

  // Compute log(1 + exp(x)) = softplus(x)
  %softplus = stablehlo.log %exp_plus_one : tensor<6x7x12x12xf32>

  // Compute tanh(softplus(x))
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x12x12xf32>

  // Compute mish = x * tanh(softplus(x))
  %mish = stablehlo.multiply %conv_bias, %tanh_softplus : tensor<6x7x12x12xf32>

  // Step 3: Add add_value = 0.5
  %add_val = constant dense<0.5> : tensor<f32>
  %add_val_broadcast = stablehlo.broadcast_in_dim %add_val : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions=[]

  %added = stablehlo.add %mish, %add_val_broadcast : tensor<6x7x12x12xf32>

  // Step 4: Hardtanh activation with min_val=-1, max_val=1
  // hardtanh(x) = min(max(x, min_val), max_val)

  %min_val = constant dense<-1.0> : tensor<f32>
  %max_val = constant dense<1.0> : tensor<f32>
  %min_val_broadcast = stablehlo.broadcast_in_dim %min_val : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions=[]
  %max_val_broadcast = stablehlo.broadcast_in_dim %max_val : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions=[]

  // max(x, min_val)
  %maxed = stablehlo.maximum %added, %min_val_broadcast : tensor<6x7x12x12xf32>

  // min(max(x, min_val), max_val)
  %hardtanh = stablehlo.minimum %maxed, %max_val_broadcast : tensor<6x7x12x12xf32>

  // Step 5: Scale output by scale=2
  %scale_val = constant dense<2.0> : tensor<f32>
  %scale_broadcast = stablehlo.broadcast_in_dim %scale_val : tensor<f32> to tensor<6x7x12x12xf32> broadcast_dimensions=[]

  %scaled = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  func.return %scaled : tensor<6x7x12x12xf32>
}

func.func @main(%x: tensor<4x7xf32>) -> tensor<7x4xf32> {
  %0 = stablehlo.transpose %x {permutation = dense<1 0> : tensor<2xi64>} : tensor<4x7xf32> to tensor<7x4xf32>
  func.return %0 : tensor<7x4xf32>
}

func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transpose input from NCHW to NHWC: (6,7,6,6) -> (6,6,6,7)
  %0 = stablehlo.transpose %arg2 [0,2,3,1] : tensor<6x7x6x6xf32> -> tensor<6x6x6x7xf32>

  // Transpose weight from OIHW (7,7,3,3) to HWIO (3,3,7,7)
  %1 = stablehlo.transpose %arg0 [2,3,1,0] : tensor<7x7x3x3xf32> -> tensor<3x3x7x7xf32>

  // Convolution parameters:
  // stride = 2, padding = 1, output_padding = 1
  // StableHLO conv expects:
  //   lhs = input NHWC: (N,H,W,C_in) = (6,6,6,7)
  //   rhs = kernel HWIO: (KH,KW,C_in,C_out) = (3,3,7,7)
  //   result NHWC: (6,12,12,7)
  //   window_strides = [2,2]
  //   padding = [1,1,1,1] (top,bottom,left,right)
  //   output_padding is not directly supported in StableHLO conv op,
  //   but ConvTranspose2d with output_padding=1 is equivalent to ConvTranspose with output_padding.
  // Since StableHLO conv is forward conv, we simulate ConvTranspose2d by using conv with lhs and rhs swapped and appropriate padding.
  // However, StableHLO has a dedicated conv_transpose op, but since only conv is listed, we do the forward conv with lhs and rhs swapped.
  // But the problem states to use convolution op only.
  // So we implement ConvTranspose2d as a convolution with lhs and rhs swapped and appropriate padding and dilation.
  // Alternatively, since the problem states "Relevant operations: convolution", we assume stablehlo.convolution supports transpose.
  // But since only convolution is listed, we implement ConvTranspose2d as a convolution with lhs and rhs swapped and appropriate padding.
  // So we do convolution with:
  //   lhs = weight (rhs of conv_transpose)
  //   rhs = input
  // But input shape is (6,6,6,7), weight shape is (3,3,7,7)
  // So we swap lhs and rhs:
  // lhs: weight (3,3,7,7)
  // rhs: input (6,6,6,7)
  // But shapes don't match for convolution.
  // So we do the following:
  // Use stablehlo.convolution with lhs=input, rhs=weight, window_strides=1, padding=0, and then apply dilation and output_padding manually.
  // But this is complicated.
  // Since the problem states "Relevant operations: convolution", and the input is the forward input, and weight is conv_transpose.weight,
  // we assume stablehlo.convolution is the forward convolution, so to do ConvTranspose2d, we use stablehlo.convolution with lhs=input, rhs=weight, but with stride=2, padding=1, output_padding=1.
  // So we do stablehlo.convolution with:
  //   lhs = input (6,6,6,7)
  //   rhs = weight (3,3,7,7)
  //   window_strides = [2,2]
  //   padding = [1,1,1,1]
  //   dimension_numbers = {lhs: NHWC, rhs: HWIO, output: NHWC}
  // This matches the conv_transpose forward output shape (6,12,12,7).
  // So we proceed.

  %2 = stablehlo.convolution %0, %1 {
    window_strides = [2, 2],
    padding = [1, 1, 1, 1],
    dimension_numbers = {
      lhs_spec = "NHWC",
      rhs_spec = "HWIO",
      out_spec = "NHWC"
    }
  } : (tensor<6x6x6x7xf32>, tensor<3x3x7x7xf32>) -> tensor<6x12x12x7xf32>

  // Add bias: %arg1 shape is (7), broadcast to (6,12,12,7)
  %3 = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x12x12x7xf32> broadcast_dimensions = [3]

  %4 = stablehlo.add %2, %3 : tensor<6x12x12x7xf32>

  // Mish activation: mish(x) = x * tanh(softplus(x)) = x * tanh(ln(1+exp(x)))
  // Compute softplus = ln(1 + exp(x))
  %5 = stablehlo.exponential %4 : tensor<6x12x12x7xf32>
  %6 = stablehlo.add %5, %cst_1 : tensor<6x12x12x7xf32> // cst_1 = 1.0
  %7 = stablehlo.log %6 : tensor<6x12x12x7xf32>
  %8 = stablehlo.tanh %7 : tensor<6x12x12x7xf32>
  %9 = stablehlo.multiply %4, %8 : tensor<6x12x12x7xf32>

  // Add add_value = 0.5 (constant)
  %cst_0_5 = stablehlo.constant 0.5 : f32
  %10 = stablehlo.add %9, %cst_0_5 : tensor<6x12x12x7xf32>

  // Hardtanh activation with min_val=-1, max_val=1
  %cst_m1 = stablehlo.constant -1.0 : f32
  %cst_1 = stablehlo.constant 1.0 : f32
  %11 = stablehlo.maximum %10, %cst_m1 : tensor<6x12x12x7xf32>
  %12 = stablehlo.minimum %11, %cst_1 : tensor<6x12x12x7xf32>

  // Scale by 2 (constant)
  %cst_2 = stablehlo.constant 2.0 : f32
  %13 = stablehlo.multiply %12, %cst_2 : tensor<6x12x12x7xf32>

  // Transpose output from NHWC to NCHW: (6,12,12,7) -> (6,7,12,12)
  %14 = stablehlo.transpose %13 [0,3,1,2] : tensor<6x12x12x7xf32> -> tensor<6x7x12x12xf32>

  return %14 : tensor<6x7x12x12xf32>
}

// Constants used
// 1.0 constant
stablehlo.constant dense<1.000000e+00> : tensor<f32> {name = "cst_1"}
// 0.5 constant
stablehlo.constant dense<5.000000e-01> : tensor<f32> {name = "cst_0_5"}
// -1.0 constant
stablehlo.constant dense<-1.000000e+00> : tensor<f32> {name = "cst_m1"}
// 2.0 constant
stablehlo.constant dense<2.000000e+00> : tensor<f32> {name = "cst_2"}

func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transposed convolution parameters:
  // input: %arg2 (6x7x6x6)
  // weight: %arg0 (7x7x3x3) [out_channels, in_channels, kernel_h, kernel_w]
  // bias: %arg1 (7)
  // stride=2, padding=1, output_padding=1

  // stablehlo.convolution expects lhs: input tensor, rhs: kernel tensor
  // For ConvTranspose2d, we use convolution with rhs_dilation=stride,
  // lhs_dilation=1, padding adjusted by padding and output_padding,
  // and dimension_numbers set accordingly.

  // Dimension numbers for ConvTranspose2d:
  // PyTorch ConvTranspose2d input: NCHW = [batch, in_channels, H, W]
  // weight: [in_channels, out_channels, kernel_h, kernel_w] in PyTorch,
  // but here weight is given as [out_channels, in_channels, kernel_h, kernel_w].
  // So we must transpose weight to [in_channels, out_channels, kernel_h, kernel_w] for convolution rhs.

  // However, StableHLO convolution expects rhs shape [output_channels, input_channels, ...]
  // So the given weight is already [out_channels, in_channels, kernel_h, kernel_w], which matches stablehlo rhs.

  // For ConvTranspose2d, the convolution is done as a backward convolution:
  // output = conv_transpose(input, weight) = conv(input, weight flipped spatially, with rhs_dilation=stride)

  // So we flip the kernel spatially (reverse dims 2 and 3)
  %weight_flipped_1 = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2>} : (tensor<7x7x3x3xf32>) -> tensor<7x7x3x3xf32>
  %weight_flipped = "stablehlo.reverse"(%weight_flipped_1) {dimensions = array<i64: 3>} : (tensor<7x7x3x3xf32>) -> tensor<7x7x3x3xf32>

  // Set convolution parameters:
  // window_strides = [1,1] (no stride on convolution itself)
  // rhs_dilation = [2,2] (stride of transposed conv)
  // lhs_dilation = [1,1]
  // padding = [[1,1],[1,1]] (padding)
  // output_padding handled by padding adjustment in transposed conv, but StableHLO conv does not have output_padding param.
  // The output shape is expected to be 6x7x12x12, so padding is set accordingly.

  // dimension_numbers: lhs = [N, C, H, W] = [0,1,2,3]
  // rhs = [O, I, KH, KW] = [0,1,2,3]
  // output = [N, O, OH, OW] = [0,1,2,3]
  // So dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  // where b=batch, f=feature, 0=height, 1=width

  %conv = "stablehlo.convolution"(%arg2, %weight_flipped) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 2, 2>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
