  %clamp_0_1 = stablehlo.minimum %clamp_min, %one_tensor : tensor<6x7x12x12xf32>

  // Step 4: Multiply by scaling_factor = 2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_tensor = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: []}} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %clamp_0_1, %scale_tensor : tensor<6x7x12x12xf32>

