  // Correction: We want 1/sqrt(8), so:
  %one = stablehlo.constant 1.0 : f32
  %scale = stablehlo.div %one, %sqrt_8 : f32

  %scaled_dot = stablehlo.mul %dot, %scale : tensor<6x6x7x7xf32>, f32 -> tensor<6x6x7x7xf32>

  // Step 3: Compute softmax over last dimension (seq_len of K)
  // Softmax = exp(x - max(x)) / sum(exp(x - max(x)))
  // Compute max over last dim (dim=3)
  %max = stablehlo.reduce %scaled_dot, %(-inf : f32) {
    body {
      %a = stablehlo.max %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32> {dimensions = [3]}

  // Broadcast max back to shape [6,6,7,7]
  %max_broadcast = stablehlo.broadcast_in_dim %max : tensor<6x6x7xf32> to tensor<6x6x7x7xf32> broadcast_dimensions = [0,1,2]

  // Subtract max for numerical stability
  %shifted = stablehlo.sub %scaled_dot, %max_broadcast : tensor<6x6x7x7xf32>

  // Exponentiate
  %exp = stablehlo.exp %shifted : tensor<6x6x7x7xf32>

  // Sum exp over last dim
  %sum_exp = stablehlo.reduce %exp, %0 : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32> {
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } {dimensions = [3]}

  // Broadcast sum_exp back to [6,6,7,7]
  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp : tensor<6x6x7xf32> to tensor<6x6x7x7xf32> broadcast_dimensions = [0,1,2]

  // Divide exp by sum_exp to get softmax
  %softmax = stablehlo.div %exp, %sum_exp_broadcast : tensor<6x6x7x7xf32>

  // Step 4: Multiply softmax weights by V
  // V shape: [6,6,7,8]
  // We want to do batch matmul: softmax [6,6,7,7] * V [6,6,7,8] -> [6,6,7,8]
  // Dot general with batch dims [0,1], contracting dims [3] of softmax and [2] of V
  %out = stablehlo.dot_general %softmax, %arg2 {
    lhs_batching_dimensions = [0,1],
    rhs_batching_dimensions = [0,1],
    lhs_contracting_dimensions = [3],
    rhs_contracting_dimensions = [2]
  } : tensor<6x6x7x7xf32>, tensor<6x6x7x8xf32> -> tensor<6x6x7x8xf32>

  stablehlo.return %out : tensor<6x6x7x8xf32>
}

func.func @main(%arg0: tensor<6x6x7x8xf32>, %arg1: tensor<6x6x7x8xf32>, %arg2: tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32> {
  // %arg0 = Q, %arg1 = K, %arg2 = V
  // scaled_dot_product_attention(Q, K, V) = softmax(QK^T / sqrt(d_k)) V
  // d_k = embedding_dimension = 8

  // Step 1: transpose K to get K^T on the last two dims: from [6,6,7,8] to [6,6,8,7]
  %k_transposed = stablehlo.transpose %arg1 {
    permutation = [0, 1, 3, 2]
  } : tensor<6x6x7x8xf32> -> tensor<6x6x8x7xf32>

  // Step 2: dot_general Q and K^T
  // batch dims: [0,1], contracting dims: Q last dim 3, K^T contracting dim 2
  %qk = stablehlo.dot_general %arg0, %k_transposed {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]
    >
  } : (tensor<6x6x7x8xf32>, tensor<6x6x8x7xf32>) -> tensor<6x6x7x7xf32>

  // Step 3: scale by 1/sqrt(d_k) = 1/sqrt(8)
  %scale = stablehlo.constant 0x3f3504f3 : f32  // approx 1/sqrt(8) = 0.35355338
  %qk_scaled = stablehlo.multiply %qk, %scale : tensor<6x6x7x7xf32>, f32 -> tensor<6x6x7x7xf32>

  // Step 4: compute softmax over last dimension (dim=3)
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // 4a: reduce max over last dim
  %init_max = stablehlo.constant -inf : f32
  %max = stablehlo.reduce %qk_scaled, %init_max {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } dimensions = [3] : tensor<6x6x7x7xf32>, tensor<f32> -> tensor<6x6x7xf32>

  // 4b: broadcast max to shape of qk_scaled for subtraction
  %max_broadcast = stablehlo.broadcast_in_dim %max
    : tensor<6x6x7xf32> to tensor<6x6x7x7xf32>
    broadcast_dimensions = [0, 1, 2]

  // 4c: subtract max from qk_scaled
  %qk_shifted = stablehlo.subtract %qk_scaled, %max_broadcast : tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32> -> tensor<6x6x7x7xf32>

  // 4d: exp of shifted
  %exp = stablehlo.exponential %qk_shifted : tensor<6x6x7x7xf32> -> tensor<6x6x7x7xf32>

  // 4e: reduce sum over last dim
  %init_zero = stablehlo.constant 0.0 : f32
  %sum_exp = stablehlo.reduce %exp, %init_zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } dimensions = [3] : tensor<6x6x7x7xf32>, tensor<f32> -> tensor<6x6x7xf32>

  // 4f: broadcast sum_exp for division
  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp
    : tensor<6x6x7xf32> to tensor<6x6x7x7xf32>
    broadcast_dimensions = [0, 1, 2]

  // 4g: divide exp by sum_exp to get softmax
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32> -> tensor<6x6x7x7xf32>

  // Step 5: dot_general softmax result with V
  // softmax shape: [6,6,7,7], V shape: [6,6,7,8]
  // batch dims: [0,1], contracting dims: softmax last dim 3, V dim 2
  %out = stablehlo.dot_general %softmax, %arg2 {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]
    >
  } : (tensor<6x6x7x7xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  func.return %out : tensor<6x6x7x8xf32>
}

func.func @main(%arg0: tensor<6x6x7x8xf32>, %arg1: tensor<6x6x7x8xf32>, %arg2: tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32> {
  // %arg0 = Q, %arg1 = K, %arg2 = V
  // Shapes:
  // Q, K, V: [batch=6, heads=6, seq_len=7, embed=8]

  // Step 1: Compute scaled dot product attention scores:
  // scores = (Q @ K^T) / sqrt(embed_dim)
  // Q: [6,6,7,8], K: [6,6,7,8]
  // Need to do dot_general over last dim of Q and last dim of K after transpose on seq_len and embed dims of K.

  // Transpose K to shape [6,6,8,7] to prepare for dot_general
  %k_transposed = stablehlo.transpose %arg1 [0, 1, 3, 2] : tensor<6x6x7x8xf32> to tensor<6x6x8x7xf32>

  // Dot_general dimension numbers:
  // lhs_contracting_dims = [3] (embedding dim of Q)
  // rhs_contracting_dims = [2] (embedding dim of K after transpose)
  // batch dims = [0,1] (batch and heads)
  // non-contracting dims:
  // lhs: [2] (seq_len Q)
  // rhs: [3] (seq_len K after transpose)
  // Result shape: [6,6,7,7]

  %scores = stablehlo.dot_general %arg0, %k_transposed {
    lhs_batch_dims = [0, 1],
    rhs_batch_dims = [0, 1],
    lhs_contracting_dims = [3],
    rhs_contracting_dims = [2]
  } : tensor<6x6x7x8xf32>, tensor<6x6x8x7xf32> -> tensor<6x6x7x7xf32>

  // Step 2: Scale scores by 1/sqrt(embed_dim)
  // embed_dim = 8, sqrt(8) = 2.8284271247461903
  %scale = stablehlo.constant 0x4006db3d : f32  // 1/2.8284271247461903 ≈ 0.35355338

  %scores_scaled = stablehlo.multiply %scores, %scale : tensor<6x6x7x7xf32>

  // Step 3: Compute softmax over last dimension (seq_len K dimension = 7)
  // Softmax = exp(x - max(x)) / sum(exp(x - max(x)))

  // Compute max over last dim (dim=3)
  %scores_max = stablehlo.reduce %scores_scaled, %cst_neg_inf : tensor<6x6x7x7xf32>, tensor<f32> {
    dimensions = [3],
    body {
      %a = stablehlo.compare %arg0, %arg1, "gt" : f32
      %res = stablehlo.select %a, %arg0, %arg1 : f32
      stablehlo.return %res : f32
    }
  } : tensor<6x6x7x7xf32>, tensor<f32> -> tensor<6x6x7xf32>

  // Broadcast max back to shape [6,6,7,7]
  %scores_max_bcast = stablehlo.broadcast_in_dim %scores_max : tensor<6x6x7xf32> to tensor<6x6x7x7xf32> broadcast_dimensions = [0,1,2]

  // Subtract max for numerical stability
  %scores_shifted = stablehlo.subtract %scores_scaled, %scores_max_bcast : tensor<6x6x7x7xf32>

  // Exponentiate
  %scores_exp = stablehlo.exp %scores_shifted : tensor<6x6x7x7xf32>

  // Sum exp over last dim (dim=3)
  %scores_exp_sum = stablehlo.reduce %scores_exp, %cst_zero : tensor<6x6x7x7xf32>, tensor<f32> {
    dimensions = [3],
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : tensor<6x6x7x7xf32>, tensor<f32> -> tensor<6x6x7xf32>

  // Broadcast sum back to shape [6,6,7,7]
  %scores_exp_sum_bcast = stablehlo.broadcast_in_dim %scores_exp_sum : tensor<6x6x7xf32> to tensor<6x6x7x7xf32> broadcast_dimensions = [0,1,2]

  // Divide exp by sum to get softmax
  %softmax = stablehlo.divide %scores_exp, %scores_exp_sum_bcast : tensor<6x6x7x7xf32>

  // Step 4: Multiply softmax weights by V
  // softmax: [6,6,7,7], V: [6,6,7,8]
  // Need to do dot_general over seq_len dimension of softmax (dim=3) and seq_len dimension of V (dim=2)
  // batch dims: [0,1]
  // contracting dims: softmax dim 3, V dim 2
  // result dims: [6,6,7,8]

  %out = stablehlo.dot_general %softmax, %arg2 {
    lhs_batch_dims = [0, 1],
    rhs_batch_dims = [0, 1],
    lhs_contracting_dims = [3],
    rhs_contracting_dims = [2]
  } : tensor<6x6x7x7xf32>, tensor<6x6x7x8xf32> -> tensor<6x6x7x8xf32>

  return %out : tensor<6x6x7x8xf32>
}

