  // Subtract max_scores from scaled_scores for numerical stability
  %shifted_scores = stablehlo.subtract %scaled_scores, %max_scores_b : tensor<6x6x7x7xf32>

  // Exponentiate
  %exp_scores = stablehlo.exponential %shifted_scores : tensor<6x6x7x7xf32>

