  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %1 = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

  // GroupNorm with num_groups=16, num_channels=16, eps=1e-5
  // Input shape: (16,16)
  // GroupNorm reshapes input to (N, G, C//G), here (16,16,1)
  // Compute mean and variance over last two dims (G and C//G) per batch element

  // Reshape to (16,16,1)
  %3 = stablehlo.reshape %2 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over dims [1,2] (group and channel per group)
  %4 = stablehlo.reduce %3, %cst0 : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16xf32> {
    ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>):
      %add = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  } reduce_dims = [1, 2]

  // mean = sum / (16*1) = sum / 16
  %c16 = stablehlo.constant dense<16.0> : tensor<f32>
  %5 = stablehlo.divide %4, %c16 : tensor<16xf32>

  // Broadcast mean to (16,16,1)
  %6 = stablehlo.broadcast_in_dim %5 : tensor<16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0]

  // Compute (x - mean)
  %7 = stablehlo.subtract %3, %6 : tensor<16x16x1xf32>

  // Compute variance: mean of (x - mean)^2 over dims [1,2]
  %8 = stablehlo.multiply %7, %7 : tensor<16x16x1xf32>
  %9 = stablehlo.reduce %8, %cst0 : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16xf32> {
    ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>):
      %add = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  } reduce_dims = [1, 2]

  %10 = stablehlo.divide %9, %c16 : tensor<16xf32>

  // Add eps=1e-5 to variance
  %c_eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %11 = stablehlo.add %10, %c_eps : tensor<16xf32>

  // rsqrt(variance + eps)
  %12 = stablehlo.rsqrt %11 : tensor<16xf32>

  // Normalize: (x - mean) * rsqrt_var
  // Broadcast rsqrt_var to (16,16,1)
  %13 = stablehlo.broadcast_in_dim %12 : tensor<16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0]

  %14 = stablehlo.multiply %7, %13 : tensor<16x16x1xf32>

  // Apply scale (gn.weight) and bias (gn.bias)
  // Broadcast gn.weight and gn.bias to (16,16,1)
  %15 = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0]
  %16 = stablehlo.multiply %14, %15 : tensor<16x16x1xf32>

  %17 = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0]
  %18 = stablehlo.add %16, %17 : tensor<16x16x1xf32>

  // Reshape back to (16,16)
  %19 = stablehlo.reshape %18 : tensor<16x16x1xf32> to tensor<16x16xf32>

  // LeakyReLU with negative_slope=0.01
  // max(x, 0) + negative_slope * min(x, 0)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %20 = stablehlo.broadcast_in_dim %c0 : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %21 = stablehlo.maximum %19, %20 : tensor<16x16xf32>
  %22 = stablehlo.minimum %19, %20 : tensor<16x16xf32>

  %c_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %23 = stablehlo.broadcast_in_dim %c_slope : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %24 = stablehlo.multiply %22, %23 : tensor<16x16xf32>

  %25 = stablehlo.add %21, %24 : tensor<16x16xf32>

  // Element-wise sum: x + x = 2 * x
  %c2 = stablehlo.constant dense<2.0> : tensor<f32>
  %26 = stablehlo.broadcast_in_dim %c2 : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %27 = stablehlo.multiply %25, %26 : tensor<16x16xf32>

  stablehlo.return %27 : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg4: input x, shape [16,16]
  // %arg0: fc.weight, shape [16,16]
  // %arg1: fc.bias, shape [16]
  // %arg2: gn.weight (gamma), shape [16]
  // %arg3: gn.bias (beta), shape [16]

  // Step 1: Fully connected layer: x @ fc.weight^T + fc.bias
  // fc.weight shape is [16,16], but PyTorch Linear weight is [out_features, in_features]
  // So we do dot_general with lhs: x [16,16], rhs: fc.weight [16,16], contracting dim 1 of lhs and dim 1 of rhs
  // But we need to transpose fc.weight to get correct multiplication: x [16,16] @ fc.weight^T [16,16]
  // So transpose fc.weight first

  %fc_weight_t = stablehlo.transpose %arg0 : tensor<16x16xf32> to tensor<16x16xf32> {permutation = [1, 0]}

  %dot = stablehlo.dot_general %arg4, %fc_weight_t {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : tensor<16x16xf32>, tensor<16x16xf32> -> tensor<16x16xf32>

  // Add bias: broadcast fc.bias [16] to [16,16] on dim 1
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %fc_out = stablehlo.add %dot, %bias_broadcast : tensor<16x16xf32>

  // Step 2: GroupNorm with num_groups=16, num_channels=16, eps=1e-5
  // Input shape: [N=16, C=16]
  // GroupNorm reshapes input to [N, G, C//G], here G=16, so shape [16,16,1]
  // Compute mean and variance over group channels dimension (dim=2)
  // Then normalize: (x - mean) / sqrt(var + eps)
  // Then scale and shift with gamma and beta (gn.weight and gn.bias), shape [16]
  // gamma and beta are per channel, so broadcast to [16,16]

  // Reshape input to [16,16,1]
  %reshape_in = stablehlo.reshape %fc_out : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over dim=2 (channels per group)
  %cst_zero = stablehlo.constant 0 : index
  %cst_two = stablehlo.constant 2 : index

  %mean = stablehlo.reduce %reshape_in, %cst_zero {
    dimensions = [2],
    body = {
      %arg_a = stablehlo.parameter 0 : tensor<f32>
      %arg_b = stablehlo.parameter 1 : tensor<f32>
      %add = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %add : tensor<f32>
    }
  } : tensor<16x16x1xf32>, tensor<index> -> tensor<16x16xf32>

  // mean = sum / 1 (since size of dim=2 is 1)
  // So mean = sum itself, no division needed

  // Compute variance: mean of squared difference
  // diff = x - mean (broadcast mean to [16,16,1])
  %mean_broadcast = stablehlo.broadcast_in_dim %mean : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  %diff = stablehlo.subtract %reshape_in, %mean_broadcast : tensor<16x16x1xf32>

  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  %var = stablehlo.reduce %diff_sq, %cst_zero {
    dimensions = [2],
    body = {
      %arg_a = stablehlo.parameter 0 : tensor<f32>
      %arg_b = stablehlo.parameter 1 : tensor<f32>
      %add = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %add : tensor<f32>
    }
  } : tensor<16x16x1xf32>, tensor<index> -> tensor<16x16xf32>

  // variance = sum / 1 = sum itself

  // Add eps=1e-5
  %eps = stablehlo.constant 0.00001 : f32
  %eps_broadcast = stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<16x16xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) / stddev
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<16x16x1xf32>

  // Reshape norm back to [16,16]
  %norm_reshaped = stablehlo.reshape %norm : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply scale (gamma) and shift (beta)
  // gamma and beta shape [16], broadcast to [16,16] on dim 1
  %gamma_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %beta_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %norm_reshaped, %gamma_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %beta_broadcast : tensor<16x16xf32>

  // Step 3: LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant 0.0 : f32
  %zero_broadcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %max_part = stablehlo.maximum %shifted, %zero_broadcast : tensor<16x16xf32>
  %min_part = stablehlo.minimum %shifted, %zero_broadcast : tensor<16x16xf32>

  %neg_slope = stablehlo.constant 0.01 : f32
  %neg_slope_broadcast = stablehlo.broadcast_in_dim %neg_slope : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %min_scaled = stablehlo.multiply %min_part, %neg_slope_broadcast : tensor<16x16xf32>

  %leaky_relu = stablehlo.add %max_part, %min_scaled : tensor<16x16xf32>

  // Step 4: output = leaky_relu + leaky_relu (element-wise sum)
  %output = stablehlo.add %leaky_relu, %leaky_relu : tensor<16x16xf32>

  func.return %output : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Compute log(predictions) elementwise
  %log_pred = "stablehlo.log"(%arg0) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute elementwise multiplication: targets * log(predictions)
  %mul = "stablehlo.multiply"(%arg1, %log_pred) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute elementwise subtraction: targets - targets * log(predictions)
  %sub = "stablehlo.subtract"(%arg1, %mul) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Sum over all elements (reduce all dims)
  %sum = stablehlo.reduce(%sub, %cst0:f32) {
    ^bb0(%argA: f32, %argB: f32):
      %add = stablehlo.add %argA, %argB : f32
      stablehlo.return %add : f32
  } : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Compute batchmean: divide sum by batch size (6*2=12)
  %cst12 = stablehlo.constant 12.0 : f32
  %result = stablehlo.divide %sum, %cst12 : tensor<f32>

  return %result : tensor<f32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg4: input x, shape [16,16]
  // %arg0: fc.weight, shape [16,16]
  // %arg1: fc.bias, shape [16]
  // %arg2: gn.weight (gamma), shape [16]
  // %arg3: gn.bias (beta), shape [16]

  // 1) Fully connected layer: x @ fc.weight^T + fc.bias
  // fc.weight shape is [16,16], but PyTorch Linear weight is [out_features, in_features]
  // input shape: [batch=16, in_features=16]
  // So dot_general with lhs batch dim 0, contracting dim 1; rhs contracting dim 1 (weight's in_features)
  // But weight shape is [16,16], so to do x @ weight^T, we do dot_general with rhs contracting dim 0 (weight rows)
  // Actually, PyTorch Linear does x @ weight^T + bias, so weight is [out_features, in_features]
  // So we want to do dot_general with lhs contracting dim 1, rhs contracting dim 1, but weight needs to be transposed.
  // Instead, we transpose weight to [16,16] -> [16,16] (same shape), but swap dims 0 and 1.
  // So transpose weight to get weight^T.

  %weight_t = stablehlo.transpose %arg0 : tensor<16x16xf32> to tensor<16x16xf32> [1, 0]

  %fc_dot = stablehlo.dot_general %arg4, %weight_t {
    lhs_batching_dimensions = [0],
    lhs_contracting_dimensions = [1],
    rhs_batching_dimensions = [0],
    rhs_contracting_dimensions = [1]
  } : tensor<16x16xf32>, tensor<16x16xf32> -> tensor<16x16xf32>

  // Add bias: broadcast bias from [16] to [16,16] on dim 1
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %fc_out = stablehlo.add %fc_dot, %bias_broadcast : tensor<16x16xf32>

  // 2) GroupNorm with num_groups=16, num_channels=16, eps=1e-5
  // Input shape: [N=16, C=16]
  // GroupNorm reshapes input to [N, G, C//G], computes mean and variance over [C//G] dim,
  // then normalizes, then applies scale (gamma) and bias (beta).
  // Here G=16, C=16, so C//G=1
  // So reshape input [16,16] -> [16,16,1]

  %input_reshaped = stablehlo.reshape %fc_out : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over last dim (dim=2)
  %dim_two = stablehlo.constant dense<2> : tensor<i64>
  %mean = stablehlo.reduce %input_reshaped, %cst_zero = stablehlo.constant dense<0.0> : tensor<f32> {
    body {
      %arg_a = stablehlo.block_argument 0 : tensor<f32>
      %arg_b = stablehlo.block_argument 1 : tensor<f32>
      %sum = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
    }
  } : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16xf32>

  // Divide sum by size 1 (C//G=1), so mean = sum / 1 = sum
  // So mean is just squeeze last dim
  // But reduce removed dim 2, so mean shape is [16,16]

  // Reshape mean to [16,16,1] to broadcast for subtraction
  %mean_reshaped = stablehlo.reshape %mean : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute variance: mean of squared difference
  %diff = stablehlo.subtract %input_reshaped, %mean_reshaped : tensor<16x16x1xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  %var = stablehlo.reduce %sq_diff, %cst_zero : tensor<f32> {
    body {
      %a = stablehlo.block_argument 0 : tensor<f32>
      %b = stablehlo.block_argument 1 : tensor<f32>
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
    }
  } : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16xf32>

  // variance = sum / 1 = sum, so var shape [16,16]

  // Reshape var to [16,16,1]
  %var_reshaped = stablehlo.reshape %var : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Add eps=1e-5 to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<16x16x1xf32> broadcast_dimensions = []

  %var_eps = stablehlo.add %var_reshaped, %eps_broadcast : tensor<16x16x1xf32>

  // Compute rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16x1xf32>

  // Normalize: (input - mean) * inv_std
  %normalized = stablehlo.multiply %diff, %inv_std : tensor<16x16x1xf32>

  // Reshape normalized to [16,16]
  %normalized_2d = stablehlo.reshape %normalized : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply scale (gamma) and bias (beta)
  // gamma and beta shape: [16]
  // Broadcast gamma and beta to [16,16] on dim 1
  %gamma_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %beta_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %normalized_2d, %gamma_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %beta_broadcast : tensor<16x16xf32>

  // 3) LeakyReLU with negative_slope=0.01
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_broadcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %cond = stablehlo.compare "gt" %shifted, %zero_broadcast : tensor<16x16xf32>

  %neg_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %neg_slope_broadcast = stablehlo.broadcast_in_dim %neg_slope : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %mul_neg = stablehlo.multiply %shifted, %neg_slope_broadcast : tensor<16x16xf32>

  %leaky_relu = stablehlo.select %cond, %shifted, %mul_neg : tensor<16x16xf32>

  // 4) Element-wise sum: x + x = 2 * x
  %two = stablehlo.constant dense<2.0> : tensor<f32>
  %two_broadcast = stablehlo.broadcast_in_dim %two : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []

  %out = stablehlo.multiply %leaky_relu, %two_broadcast : tensor<16x16xf32>

  func.return %out : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Fully connected layer: x = fc.weight @ input + fc.bias
  // dot_general with contracting dims [1] for lhs and [0] for rhs, batching dims [0] for both
  %dot = "stablehlo.dot_general"(%arg4, %arg0) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [1],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Broadcast bias from shape [16] to [16x16] along dimension 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>

  %fc_out = "stablehlo.add"(%dot, %bias_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // GroupNorm: normalize over channels dimension (dim=1)
  // Compute mean over dim=1 (channels)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %mean = "stablehlo.reduce"(%fc_out, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // Compute mean scalar divisor 1/16
  %const_16 = "stablehlo.constant"() {value = dense<16.0> : tensor<f32>} : () -> tensor<f32>
  %inv_16 = "stablehlo.divide"(%zero, %const_16) : (tensor<f32>, tensor<f32>) -> tensor<f32> // 0/16=0, we want 1/16, so create constant 1/16 directly
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %inv_16 = "stablehlo.divide"(%one, %const_16) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  // mean_scaled = mean * (1/16)
  %mean_scaled = "stablehlo.multiply"(%mean, %inv_16) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // Broadcast mean_scaled to shape [16x16] along dimension 0
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Compute x - mean
  %x_centered = "stablehlo.subtract"(%fc_out, %mean_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = "stablehlo.multiply"(%x_centered, %x_centered) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %var_sum = "stablehlo.reduce"(%x_centered_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // var = var_sum * (1/16)
  %var = "stablehlo.multiply"(%var_sum, %inv_16) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // eps = 1e-5 constant
  %eps = "stablehlo.constant"() {value = dense<0.00001> : tensor<f32>} : () -> tensor<f32>

  // var_eps = var + eps
  %var_eps = "stablehlo.add"(%var, %eps) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // rsqrt_var_eps = rsqrt(var + eps)
  %rsqrt_var_eps = "stablehlo.rsqrt" %var_eps : tensor<16xf32> -> tensor<16xf32>

  // Broadcast rsqrt_var_eps to [16x16] along dimension 0
  %rsqrt_broadcast = "stablehlo.broadcast_in_dim"(%rsqrt_var_eps) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Normalize: x_centered * rsqrt_var_eps
  %x_norm = "stablehlo.multiply"(%x_centered, %rsqrt_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Apply group norm affine transform: weight and bias are shape [16]
  // Broadcast weight and bias to [16x16] along dimension 0
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_broadcast_gn = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // x_norm * weight + bias
  %scaled = "stablehlo.multiply"(%x_norm, %weight_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %gn_out = "stablehlo.add"(%scaled, %bias_broadcast_gn) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(x, 0) + negative_slope * min(x, 0)
  %zero_tensor = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero_tensor) {broadcast_dimensions = dense<> : tensor<0xi64>} : (tensor<f32>) -> tensor<16x16xf32>

  %max_part = "stablehlo.maximum"(%gn_out, %zero_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %min_part = "stablehlo.minimum"(%gn_out, %zero_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %neg_slope = "stablehlo.constant"() {value = dense<0.01> : tensor<f32>} : () -> tensor<f32>
  %neg_slope_broadcast = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = dense<> : tensor<0xi64>} : (tensor<f32>) -> tensor<16x16xf32>

  %min_scaled = "stablehlo.multiply"(%min_part, %neg_slope_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %leaky_relu_out = "stablehlo.add"(%max_part, %min_scaled) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Final output: x + x (element-wise sum)
  %out = "stablehlo.add"(%leaky_relu_out, %leaky_relu_out) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  return %

func.func @main(%fc_weight: tensor<16x16xf32>, %fc_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Fully connected layer: x = input @ fc_weight^T + fc_bias
  // fc.weight shape: [16,16], input shape: [16,16]
  // We want: output[i,j] = sum_k input[i,k] * fc_weight[j,k] + fc_bias[j]
  // So we transpose fc_weight to [16,16] with permutation [1,0] to get fc_weight^T
  %fc_weight_t = "stablehlo.transpose"(%fc_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %fc_out = "stablehlo.dot_general"(%input, %fc_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %fc_bias_broadcast = "stablehlo.broadcast_in_dim"(%fc_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %fc_out_bias = stablehlo.add %fc_out, %fc_bias_broadcast : tensor<16x16xf32>

  // GroupNorm with num_groups=16, num_channels=16, eps=1e-5
  // Input shape: [16,16] (batch_size=16, channels=16)
  // GroupNorm divides channels into groups of size 1 (since num_groups=16, channels=16)
  // So each group has 1 channel, so mean and variance per group is per channel per batch element
  // Compute mean and variance over group dimension (channels per group = 1), so mean and variance are just the value itself
  // But we implement the general formula:
  // Reshape input to [batch_size, num_groups, channels_per_group] = [16,16,1]
  %input_reshaped = stablehlo.reshape %fc_out_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over channels_per_group dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%input_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by channels_per_group=1 (no change)
  // mean shape: [16,16]

  // Broadcast mean back to [16,16,1]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute variance: mean of squared difference
  %diff = stablehlo.subtract %input_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by channels_per_group=1 (no change)
  // var shape: [16,16]

  // Broadcast var back to [16,16,1]
  %var_broadcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // eps constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>

  // var + eps
  %var_eps = stablehlo.add %var_broadcast, %eps : tensor<16x16x1xf32>

  // rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16x1xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %diff, %inv_std : tensor<16x16x1xf32>

  // Reshape gn.weight and gn.bias from [16] to [1,16,1] for broadcasting
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16xf32>
  %gn_weight_broadcast_3d = "stablehlo.broadcast_in_dim"(%gn_weight_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<1x16xf32>) -> tensor<1x16x1xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16xf32>
  %gn_bias_broadcast_3d = "stablehlo.broadcast_in_dim"(%gn_bias_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<1x16xf32>) -> tensor<1x16x1xf32>

  // Broadcast gn.weight and gn.bias to [16,16,1]
  %gn_weight_broadcast_16 = "stablehlo.broadcast_in_dim"(%gn_weight_broadcast_3d) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<1x16x1xf32>) -> tensor<16x16x1xf32>
  %gn_bias_broadcast_16 = "stablehlo.broadcast_in_dim"(%gn_bias_broadcast_3d) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<1x16x1xf32>) -> tensor<16x16x1xf32>

  // Apply scale and shift: x_norm * weight + bias
  %scaled = stablehlo.multiply %x_norm, %gn_weight_broadcast_16 : tensor<16x16x1xf32>
  %shifted = stablehlo.add %scaled, %gn_bias_broadcast_16 : tensor<16x16x1xf32>

  // Reshape back to [16,16]
  %gn_out = stablehlo.reshape %shifted : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // LeakyReLU with negative_slope=0.01
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %cond = "stablehlo.compare"(%gn_out, %zero) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xi1>
  %pos = %gn_out : tensor<16x16xf32>
  %neg_scaled = stablehlo.multiply %gn_out, stablehlo.constant dense<0.01> : tensor<f32> : tensor<16x16xf32>
  %leaky_relu = "stablehlo.select"(%cond, %pos, %neg_scaled) : (tensor<16x16xi1>, tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Element-wise sum: x + x = 2 * x
  %two = stablehlo.constant dense<2.0> : tensor<f32>
  %two_broadcast = "stablehlo.broadcast_in_dim"(%two) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16xf32>
  %out = stablehlo.multiply %leaky_relu, %two_broadcast : tensor<16x16xf32>

  return %out : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Compute log(predictions) elementwise
  %log_pred = "stablehlo.log"(%arg0) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute elementwise multiplication: targets * log(predictions)
  %mul = "stablehlo.multiply"(%arg1, %log_pred) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute elementwise subtraction: targets * log(targets) - targets * log(predictions)
  // But PyTorch kl_div with inputs (log_pred, targets) computes sum(targets * (log(targets) - log(predictions)))
  // So we need targets * log(targets) as well.

  // Compute log(targets)
  %log_target = "stablehlo.log"(%arg1) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute targets * log(targets)
  %target_log_target = "stablehlo.multiply"(%arg1, %log_target) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute difference: targets * log(targets) - targets * log(predictions)
  %diff = "stablehlo.subtract"(%target_log_target, %mul) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Sum over all elements (reduce all dims)
  %sum = stablehlo.reduce(%diff, %cst0:f32) (
    %x, %y -> stablehlo.add(%x, %y) : (f32, f32) -> f32
  ) : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Divide by batch size (12) to get batchmean reduction
  %cst12 = stablehlo.constant dense<12.0> : tensor<f32>
  %result = stablehlo.divide %sum, %cst12 : tensor<f32>

  func.return %result : tensor<f32>
}

func.func @main(%fc_weight: tensor<16x16xf32>, %fc_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Fully connected layer: x = input @ fc_weight^T + fc_bias
  // fc.weight shape: [16,16], input shape: [16,16]
  // We want input [16,16] * fc_weight^T [16,16] -> [16,16]
  // So transpose fc_weight to get [16,16] (actually same shape, but transpose swaps dims)
  %fc_weight_t = "stablehlo.transpose"(%fc_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %fc_out = "stablehlo.dot_general"(%input, %fc_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Add bias: broadcast bias from [16] to [16x16] on dimension 1
  %fc_bias_broadcast = "stablehlo.broadcast_in_dim"(%fc_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %fc_out_bias = stablehlo.add %fc_out, %fc_bias_broadcast : tensor<16x16xf32>

  // GroupNorm with num_groups=16, num_channels=16, eps=1e-5
  // Input shape: [N=16, C=16]
  // GroupNorm reshapes input to [N, G, C//G], here G=16, so shape [16,16,1]
  // Compute mean and variance over axis=2 (the group channels dimension)
  // Then normalize: (x - mean) / sqrt(var + eps)
  // Then scale and shift with gn_weight and gn_bias (shape [16])
  // gn_weight and gn_bias are per channel, so broadcast to [N,C]

  // Reshape input to [16,16,1]
  %input_reshaped = stablehlo.reshape %fc_out_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over axis=2 (last dim)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%input_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Compute mean by dividing sum by group size (1)
  %one_f32 = stablehlo.constant dense<1.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %one_f32 : tensor<16x16xf32>

  // Compute variance: mean of squared differences
  // diff = input_reshaped - mean (broadcast mean to [16,16,1])
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %input_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  // sum of squared differences over axis=2
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = var_sum / group_size (1)
  %var = stablehlo.divide %var_sum, %one_f32 : tensor<16x16xf32>

  // Add eps=1e-5 to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<16x16xf32>

  // Normalize: (input - mean) / stddev
  // Broadcast mean and stddev to [16,16,1]
  // Already have mean_broadcast, broadcast stddev similarly
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff_norm = stablehlo.divide %diff, %stddev_broadcast : tensor<16x16x1xf32>

  // Reshape normalized to [16,16]
  %diff_norm_reshaped = stablehlo.reshape %diff_norm : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Scale and shift: gn_weight * normalized + gn_bias
  // Broadcast gn_weight and gn_bias from [16] to [16x16] on dim 1
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %diff_norm_reshaped, %gn_weight_broadcast : tensor<16x16xf32>
  %gn_out = stablehlo.add %scaled, %gn_bias_broadcast : tensor<16x16xf32>

  // LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero_tensor = stablehlo.constant dense<0.0> : tensor<16x16xf32>
  %max_part = stablehlo.maximum %gn_out, %zero_tensor : tensor<16x16xf32>
  %min_part = stablehlo.minimum %gn_out, %zero_tensor : tensor<16x16xf32>
  %neg_slope = stablehlo.constant dense<0.01> : tensor<f32>
  // Broadcast neg_slope to [16x16]
  %neg_slope_broadcast = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %min_scaled = stablehlo.multiply %min_part, %neg_slope_broadcast : tensor<16x16xf32>
  %leaky_relu_out = stablehlo.add %max_part, %min_scaled : tensor<16x16xf32>

  // Element-wise sum: x + x = 2 * x
  %two = stablehlo.constant dense<2.0> : tensor<f32>
  %two_broadcast = "stablehlo.broadcast_in_dim"(%two) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %output = stablehlo.multiply %leaky_relu_out, %two_broadcast : tensor<16x16xf32>

  "stablehlo.return"(%output) : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
