  %log_pred = "stablehlo.log"(%arg0) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute element-wise multiplication: targets * log(predictions)
  %mul = "stablehlo.multiply"(%arg1, %log_pred) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute element-wise subtraction: targets * log(targets) - targets * log(predictions)
  // But we only have targets * log(predictions), so we need targets * log(targets) as well.
  // KL divergence formula: sum(targets * (log(targets) - log(predictions))) / batch_size
  // So compute log(targets)
  %log_target = "stablehlo.log"(%arg1) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute targets * log(targets)
  %mul_target_log = "stablehlo.multiply"(%arg1, %log_target) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute difference: targets * log(targets) - targets * log(predictions)
  %diff = "stablehlo.subtract"(%mul_target_log, %mul) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Sum over all elements (reduce all dims)
  %c0 = stablehlo.constant dense<0> : index
  %c1 = stablehlo.constant dense<1> : index
  %dims = stablehlo.constant dense<[0, 1]> : tensor<2xi64>
  %sum = stablehlo.reduce(%diff, %c0) ( {
    %a = stablehlo.add %arg0, %arg1 : f32
    stablehlo.return %a : f32
  }) {dimensions = dense<[0, 1]> : tensor<2xi64>} : (tensor<12x12xf32>, tensor<index>) -> tensor<f32>

  // Divide by batch size (12) to get batchmean reduction
  %batch_size = stablehlo.constant dense<12> : tensor<f32>
  %result = stablehlo.divide %sum, %batch_size : tensor<f32>

  return %result : tensor<f32>
}

