  // Broadcast bias over batch, height, width dims
  // Broadcast dims: bias shape [6], broadcast to [6x6x16x16]
  // The bias corresponds to the channel dimension (dim 1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x16x16xf32>

  %add = stablehlo.add %conv, %bias_broadcast : tensor<6x6x16x16xf32>

