func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32> {
  // Constants
  %c0_f32 = constant 0.0 : f32
  %c1_f32 = constant 1.0 : f32
  %epsilon = constant 1.0e-5 : f32

  // Dimensions
  // Input shape: [14,16,16,16]
  // num_groups = 8
  // channels_per_group = 16 / 8 = 2

  // Reshape input from [14,16,16,16] to [14,8,2,16,16]
  %reshape1 = stablehlo.reshape %arg2 : tensor<14x16x16x16xf32> to tensor<14x8x2x16x16xf32>

  // Compute mean over axes [2,3,4] (channels_per_group and spatial dims)
  %mean = stablehlo.reduce %reshape1, %c0_f32 {
    dimensions = [2,3,4],
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : tensor<14x8x2x16x16xf32>, tensor<f32> -> tensor<14x8xf32>

  // Number of elements per group: 2*16*16 = 512
  %num_elements = constant 512.0 : f32
  %num_elements_inv = stablehlo.div %c1_f32, %num_elements : f32

  // mean = sum / 512
  %mean_scaled = stablehlo.mul %mean, %num_elements_inv : tensor<14x8xf32>

  // Compute variance: mean of squared differences
  // diff = x - mean (broadcast mean to shape [14,8,2,16,16])
  %mean_bcast = stablehlo.broadcast_in_dim %mean_scaled : tensor<14x8xf32> to tensor<14x8x2x16x16xf32> dimensions=[0,1]
  %diff = stablehlo.subtract %reshape1, %mean_bcast : tensor<14x8x2x16x16xf32>

  // square diff
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<14x8x2x16x16xf32>

  // reduce sum of squared diff over axes [2,3,4]
  %var_sum = stablehlo.reduce %diff_sq, %c0_f32 {
    dimensions = [2,3,4],
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : tensor<14x8x2x16x16xf32>, tensor<f32> -> tensor<14x8xf32>

  // variance = var_sum / 512
  %var = stablehlo.mul %var_sum, %num_elements_inv : tensor<14x8xf32>

  // Add epsilon and sqrt to get stddev
  %var_eps = stablehlo.add %var, %epsilon : tensor<14x8xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<14x8xf32>

  // Normalize: (x - mean) / stddev
  // Broadcast stddev to [14,8,2,16,16]
  %stddev_bcast = stablehlo.broadcast_in_dim %stddev : tensor<14x8xf32> to tensor<14x8x2x16x16xf32> dimensions=[0,1]

  %norm = stablehlo.divide %diff, %stddev_bcast : tensor<14x8x2x16x16xf32>

  // Reshape normalized tensor back to [14,16,16,16]
  %norm_reshaped = stablehlo.reshape %norm : tensor<14x8x2x16x16xf32> to tensor<14x16x16x16xf32>

  // Apply affine transform: output = norm * weight + bias
  // weight and bias shape: [16]
  // Broadcast weight and bias to [14,16,16,16]
  %weight_bcast = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<14x16x16x16xf32> dimensions=[1]
  %bias_bcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<14x16x16x16xf32> dimensions=[1]

  %scaled = stablehlo.multiply %norm_reshaped, %weight_bcast : tensor<14x16x16x16xf32>
  %output = stablehlo.add %scaled, %bias_bcast : tensor<14x16x16x16xf32>

  func.return %output : tensor<14x16x16x16xf32>
}

