  %variance_broadcast = stablehlo.broadcast_in_dim %variance
    {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>} : tensor<14x8xf32> to tensor<14x8x1x1x1x1xf32>
  %variance_broadcast_reshaped = stablehlo.broadcast_in_dim %variance_broadcast
    {broadcast_dimensions = dense<[0,1,2,3,4,5]> : tensor<6xi64>} : tensor<14x8x1x1x1x1xf32> to tensor<14x8x2x16x16x16xf32>

