  %epsilon = stablehlo.constant dense<1e-5> : tensor<f32>

  // stddev = sqrt(variance + epsilon)
  %var_eps = stablehlo.add %variance_broadcast_reshaped, %epsilon : tensor<14x8x2x16x16x16xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<14x8x2x16x16x16xf32>

  // Normalize: (x - mean) / stddev
  %x_norm = stablehlo.divide %diff, %stddev : tensor<14x8x2x16x16x16xf32>

