    {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : tensor<16xf32> to tensor<1x16x1x1xf32>
  %bias_broadcast_full = stablehlo.broadcast_in_dim %bias_broadcast
    {broadcast_dimensions = dense<[0,1,2,3]> : tensor<4xi64>} : tensor<1x16x1x1xf32> to tensor<14x16x16x16xf32>

  // Apply scale and bias: y = x_norm * weight + bias
  %scaled = stablehlo.multiply %x_norm_reshaped, %weight_broadcast_full : tensor<14x16x16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_broadcast_full : tensor<14x16x16x16xf32>

  return %shifted : tensor<14x16x16x16xf32>
}

