  // num_groups = 16, out_features = 16, so each group has 1 channel (C/G=1)
  // Input shape: (N=16, C=16)
  // Reshape to (N=16, G=16, C_per_group=1)
  %3 = stablehlo.reshape %2 : tensor<16x16xf32> to tensor<16x16x1xf32>

