  %7 = stablehlo.subtract %3, %6 : tensor<16x16x1xf32>
  %8 = stablehlo.multiply %7, %7 : tensor<16x16x1xf32>

  %9 = stablehlo.reduce %8, %cst0_2 = stablehlo.constant 0.0 : tensor<f32> {
    ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>):
      %sum = stablehlo.add %arg_a, %arg_b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32> reduce_dims = [2]

  // variance = sum / C_per_group (1)
  %10 = stablehlo.divide %9, stablehlo.constant 1.0 : tensor<16x16xf32>

