  %17 = stablehlo.reshape %16 : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply affine transform: y = normalized * weight + bias
  // Broadcast weight and bias from (16) to (16x16)
  %18 = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %19 = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

