func.func @main(%x: tensor<7x3xf32>) -> tensor<7x3xf32> {
  %c0 = constant 0 : index
  %c1 = constant 1 : index
  %c2 = constant 2 : index

  // Square each element: x^2
  %x_squared = mhlo.multiply %x, %x : tensor<7x3xf32>

  // Reduce sum over axis 1 (columns) to get sum_k x[i,k]^2, shape: tensor<7xf32>
  %sum_squares = "mhlo.reduce"(%x_squared) ( {
    %arg0 = mhlo.add %arg0, %arg1 : f32
    mhlo.return %arg0 : f32
  }) {dimensions = [1]} : (tensor<7x3xf32>, tensor<>) -> tensor<7xf32>

  // sqrt of sum_squares
  %sqrt_sum = mhlo.sqrt %sum_squares : tensor<7xf32>

  // Broadcast sqrt_sum to shape <7x3> for division
  %broadcast_sqrt = mhlo.broadcast_in_dim %sqrt_sum : tensor<7xf32> to tensor<7x3xf32> broadcast_dimensions = [0]

