func.func @main(%gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
