  // GroupNorm with num_groups=16, out_features=16
  // Input shape: [16,16] (batch_size=16, channels=16)
  // GroupNorm with num_groups=16 means each channel is its own group (group size=1)
  // So normalization is per channel per batch element (mean and var over group_size=1 elements)
  // For each batch and group, compute mean and variance over group elements
  // Here group size=1, so mean = value itself, variance=0
  // But we implement the general formula anyway.

  // Reshape to [batch_size, num_groups, group_size] = [16,16,1]
  %gn_reshaped = stablehlo.reshape %gemm_out_biased : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

