  %diff = stablehlo.subtract %gn_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by group_size=1 (no change)
  // var shape: [16,16]

  // Broadcast var back to [16,16,1]
  %var_broadcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute inv_std = 1 / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %var_eps = stablehlo.add %var_broadcast, %eps : tensor<16x16x1xf32>
  %sqrt_var = stablehlo.sqrt %var_eps : tensor<16x16x1xf32>
  %inv_std = stablehlo.divide %zero_f32, %sqrt_var : tensor<16x16x1xf32> // incorrect, fix below

  // Correction: inv_std = 1 / sqrt_var
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16xf32>
  %one_broadcast_3d = "stablehlo.broadcast_in_dim"(%one_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %inv_std = stablehlo.divide %one_broadcast_3d, %sqrt_var : tensor<16x16x1xf32>

