  // Reshape normalized back to [16,16]
  %normalized_2d = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply affine transform: normalized * gn_weight + gn_bias
  // gn_weight and gn_bias shape: [16]
  // Broadcast gn_weight and gn_bias to [16,16] with broadcast_dimensions=[1]
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %normalized_2d, %gn_weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %gn_bias_broadcast : tensor<16x16xf32>

  // HardTanh clamp between -2.0 and 2.0
  %min_val = stablehlo.constant dense<-2.0> : tensor<f32>
  %max_val = stablehlo.constant dense<2.0> : tensor<f32>
  %min_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16xf32>
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16xf32>
  %clamped_min = stablehlo.maximum %shifted, %min_broadcast : tensor<16x16xf32>
