}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg4: input tensor (batch_size=16, in_features=16)
  // %arg0: gemm.weight (out_features=16, in_features=16)
  // %arg1: gemm.bias (out_features=16)
  // %arg2: group_norm.weight (out_features=16)
  // %arg3: group_norm.bias (out_features=16)

  // GEMM: x = %arg4 @ %arg0^T + %arg1
  // Note: PyTorch Linear weight shape is (out_features, in_features)
  // Input shape: (batch_size, in_features)
  // So dot_general dims: batch dims = [0], contracting dims = [1] for input and [1] for weight
  // But weight needs to be transposed to (in_features, out_features) for dot_general with contracting dims [1] and [0].
  // Instead, we do dot_general with contracting dims [1] of input and [1] of weight, but weight is (16x16),
  // so we transpose weight to (16x16) swapping dims 0 and 1.

  %weight_t = stablehlo.transpose %arg0 : tensor<16x16xf32> to tensor<16x16xf32> {permutation = [1, 0]}

  %dot = stablehlo.dot_general %arg4, %weight_t {
    lhs_batch_dims = [0],
    rhs_batch_dims = [0],
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias from [16] to [16x16]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1, 0]
  // The above broadcast_in_dim is incorrect because bias shape is [16], output shape is [16x16].
  // We want to add bias to last dimension (features), so broadcast dims = [1]
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %x1 = stablehlo.add %dot, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm:
  // num_groups = 16, out_features = 16, so group size = 1 (16/16=1)
  // Reshape x1 from [16,16] to [16,16,1] to group features
  %x1_reshaped = stablehlo.reshape %x1 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over group dimension (dim=2)
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce %x1_reshaped, %init_mean {
    dimensions = [2],
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: [16,16]

  // Compute variance: mean of squared difference
  // diff = x1_reshaped - mean (broadcast mean to [16,16,1])
  %mean_broadcast = stablehlo.broadcast_in_dim %mean : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  %diff = stablehlo.subtract %x1_reshaped, %mean_broadcast : tensor<16x16x1xf32>

  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = stablehlo.reduce %diff_sq, %init_var {
    dimensions = [2],
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // var shape: [16,16]

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>

  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>

  %stddev = stablehlo.sqrt %var_eps : tensor<16x16xf32>

  // Broadcast stddev to [16,16,1]
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  %x_norm = stablehlo.divide %diff, %stddev_broadcast : tensor<16x16x1xf32>

  // Remove group dimension: reshape back to [16,16]
  %x_norm_reshaped = stablehlo.reshape %x_norm : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply affine transform: weight * x_norm + bias
  // weight and bias shape: [16]
  // Broadcast weight and bias to [16x16], broadcasting on feature dim (dim=1)
  %weight_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %bias_gn_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]

  %x_scaled = stablehlo.multiply %x_norm_reshaped, %weight_broadcast : tensor<16x16xf32>
  %x_shifted = stablehlo.add %x_scaled, %bias_gn_broadcast : tensor<16x16xf32>

  // HardTanh clamp between -2.0 and 2.0
  %min_val = stablehlo.constant dense<-2.0> : tensor<f32>
  %max_val = stablehlo.constant dense<2.0> : tensor<f32>

  %min_broadcast = stablehlo.broadcast_in_dim %min_val : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
