func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute the difference: diff = predictions - targets
  %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

  // Compute absolute difference: abs_diff = abs(diff)
  %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

  // Create constant 1.0f for comparison and computation
  %cst_1 = stablehlo.constant dense<1.0> : tensor<f32>

  // Broadcast 1.0 to shape <6x6> for elementwise ops
  %cst_1_broadcast = stablehlo.broadcast_in_dim %cst_1
    : tensor<f32> to tensor<6x6xf32> broadcast_dimensions = []

  // Compare abs_diff < 1.0 -> predicate tensor<i1>
  %lt_1 = stablehlo.compare %abs_diff, %cst_1_broadcast
    direction = "LT" : tensor<6x6xf32>, tensor<6x6xf32> -> tensor<i1>

  // Compute 0.5 * diff^2
  %diff_squared = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
  %cst_0_5 = stablehlo.constant dense<0.5> : tensor<f32>
  %cst_0_5_broadcast = stablehlo.broadcast_in_dim %cst_0_5
    : tensor<f32> to tensor<6x6xf32> broadcast_dimensions = []
  %half_diff_squared = stablehlo.multiply %cst_0_5_broadcast, %diff_squared : tensor<6x6xf32>

  // Compute abs_diff - 0.5
  %abs_diff_minus_half = stablehlo.subtract %abs_diff, %cst_0_5_broadcast : tensor<6x6xf32>

  // Select: if abs_diff < 1 then 0.5*diff^2 else abs_diff - 0.5
  %smooth_l1_per_element = stablehlo.select %lt_1, %half_diff_squared, %abs_diff_minus_half : tensor<i1>, tensor<6x6xf32>, tensor<6x6xf32>

  // Reduce sum over all elements to get scalar loss
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %loss = stablehlo.reduce %smooth_l1_per_element, %init
    dimensions = [0, 1] : tensor<6x6xf32>, tensor<f32> -> tensor<f32> {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }

  return %loss : tensor<f32>
}

func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute the difference: diff = predictions - targets
  %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

  // Compute absolute difference: abs_diff = abs(diff)
  %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

  // Create constant 1.0 tensor for comparison
  %cst_one = stablehlo.constant dense<1.0> : tensor<f32>
  %cst_one_tensor = stablehlo.broadcast_in_dim %cst_one 
    : tensor<f32> to tensor<6x6xf32> broadcast_dimensions = []

  // Compare abs_diff < 1.0 -> predicate tensor<i1>
  %lt_one = stablehlo.compare %abs_diff, %cst_one_tensor 
    direction = "LT" : tensor<6x6xf32> -> tensor<6x6xi1>

  // Compute squared loss part: 0.5 * diff^2
  %diff_squared = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
  %cst_half = stablehlo.constant dense<0.5> : tensor<f32>
  %cst_half_tensor = stablehlo.broadcast_in_dim %cst_half 
    : tensor<f32> to tensor<6x6xf32> broadcast_dimensions = []
  %sq_loss = stablehlo.multiply %cst_half_tensor, %diff_squared : tensor<6x6xf32>

  // Compute linear loss part: abs_diff - 0.5
  %cst_half_tensor_for_sub = %cst_half_tensor
  %lin_loss = stablehlo.subtract %abs_diff, %cst_half_tensor_for_sub : tensor<6x6xf32>

  // Select between squared loss and linear loss based on abs_diff < 1.0
  %loss = stablehlo.select %lt_one, %sq_loss, %lin_loss : tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32> -> tensor<6x6xf32>

  // Reduce sum over all elements to get scalar loss
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = stablehlo.reduce %loss, %init dimensions = [0, 1] : tensor<6x6xf32>, tensor<f32> -> tensor<f32>

  // Compute mean loss by dividing sum by number of elements (36)
  %cst_36 = stablehlo.constant dense<36.0> : tensor<f32>
  %mean_loss = stablehlo.divide %sum, %cst_36 : tensor<f32>

  func.return %mean_loss : tensor<f32>
}

