  %pred_mask = stablehlo.compare %abs_diff, %cst_one_tensor 
    direction lt : tensor<6x6xf32>

  // Compute squared term: 0.5 * diff^2
  %diff_squared = stablehlo.mul %diff, %diff : tensor<6x6xf32>
  %cst_half = stablehlo.constant dense<0.5> : tensor<f32>
  %cst_half_tensor = stablehlo.broadcast_in_dim %cst_half 
    : tensor<f32> to tensor<6x6xf32> broadcast_dimensions = []
  %sq_term = stablehlo.mul %cst_half_tensor, %diff_squared : tensor<6x6xf32>

