  %cst_half_tensor_2 = stablehlo.broadcast_in_dim %cst_half 
    : tensor<f32> to tensor<6x6xf32> broadcast_dimensions = []
  %lin_term = stablehlo.sub %abs_diff, %cst_half_tensor_2 : tensor<6x6xf32>

