  %smooth_l1 = stablehlo.select %pred_mask, %sq_term, %lin_term : tensor<6x6xf32>

  // Reduce sum over all elements to get scalar loss
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %loss = stablehlo.reduce %smooth_l1, %zero 
    dimensions = [0, 1] : tensor<6x6xf32>, tensor<f32> -> tensor<f32>

  func.return %loss : tensor<f32>
}

