  // window_strides = [1,1,1]
  // padding = 0 (valid convolution)
  // lhs_dilation = [1,1,1]
  // rhs_dilation = [1,1,1]
  // feature_group_count = 1
  // batch_group_count = 1
  //
  // dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, o, 2, 3, 4]>
  // which means:
  // lhs: batch=b=0, in_channels=i=1, spatial dims=2,3,4 (D,H,W)
  // rhs: out_channels=o=0, in_channels=i=1, spatial dims=2,3,4 (kd,kh,kw)
  // output: batch=b=0, out_channels=o=1, spatial dims=2,3,4

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, o, 2, 3, 4]>,
