    batch_group_count = 1 : i64
  } : (tensor<6x3x7x8x8xf32>, tensor<7x3x3x3x3xf32>) -> tensor<6x7x5x6x6xf32>

  // Add bias: %arg1 shape is tensor<7xf32>, need to broadcast to conv output shape tensor<6x7x5x6x6xf32>
