  // diff = scaled - mean
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %scaled, %mean_bcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
