  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>
  %rsqrt_var_eps = stablehlo.rsqrt %var_eps : tensor<7xf32>
  %rsqrt_bcast = "stablehlo.broadcast_in_dim"(%rsqrt_var_eps) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %normalized = stablehlo.multiply %diff, %rsqrt_bcast : tensor<6x7xf32>

  // Apply batchnorm affine transform: normalized * bn_weight + bn_bias
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled_bn = stablehlo.multiply %normalized, %bn_weight_bcast : tensor<6x7xf32>
  %out = stablehlo.add %scaled_bn, %bn_bias_bcast : tensor<6x7xf32>

  return %out : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = scale (7)
  // %arg1 = gemm.weight (7x7)
  // %arg2 = gemm.bias (7)
  // %arg3 = bn.weight (7)
  // %arg4 = bn.bias (7)
  // %arg5 = input (6x7)

  // Step 1: gemm: x @ W^T + b
  // PyTorch Linear: output = input @ weight.T + bias
  // input: [6x7], weight: [7x7], weight.T: [7x7]
  // dot_general with contracting dims: input dim 1 and weight dim 1
  // Result shape: [6x7]

  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [1]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias (broadcast bias from [7] to [6x7])
  %1 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // Step 2: multiply by scale
  // scale shape: [7], broadcast to [6x7]
  %3 = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %4 = stablehlo.mul %2, %3 : tensor<6x7xf32>

  // Step 3: batch norm (training mode)
  // BatchNorm1d over features dimension (dim=1)
  // Compute mean over batch dim (dim=0)
  %5 = stablehlo.reduce %4, %cst0 = stablehlo.constant 0.0 : tensor<6x7xf32>, tensor<f32> {
    dimensions = [0]
    body() {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute mean = sum / 6
  %c6 = stablehlo.constant 6.0 : tensor<f32>
  %6 = stablehlo.div %5, %c6 : tensor<7xf32>

  // Compute variance: mean of (x - mean)^2 over batch dim 0
  // Broadcast mean [7] to [6x7]
  %7 = "stablehlo.broadcast_in_dim"(%6) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %8 = stablehlo.sub %4, %7 : tensor<6x7xf32>
  %9 = stablehlo.mul %8, %8 : tensor<6x7xf32>

  %10 = stablehlo.reduce %9, %cst0_2 = stablehlo.constant 0.0 : tensor<6x7xf32>, tensor<f32> {
    dimensions = [0]
    body() {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  %11 = stablehlo.div %10, %c6 : tensor<7xf32>

  // Add eps=1e-5 to variance
  %eps = stablehlo.constant 1.00000001e-5 : tensor<f32>
  %12 = stablehlo.add %11, %eps : tensor<7xf32>

  // rsqrt(variance + eps)
  %13 = stablehlo.rsqrt %12 : tensor<7xf32>

  // Normalize: (x - mean) * rsqrt_var
  // Broadcast rsqrt_var [7] to [6x7]
  %14 = "stablehlo.broadcast_in_dim"(%13) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %15 = stablehlo.mul %8, %14 : tensor<6x7xf32>

  // Scale and shift: y = weight * normalized + bias
  // Broadcast bn.weight and bn.bias [7] to [6x7]
  %16 = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %17 = stablehlo.mul %15, %16 : tensor<6x7xf32>
  %18 = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %19 = stablehlo.add %17, %18 : tensor<6x7xf32>

  stablehlo.return %19 : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = scale (7)
  // %arg1 = gemm.weight (7x7)
  // %arg2 = gemm.bias (7)
  // %arg3 = bn.weight (7)
  // %arg4 = bn.bias (7)
  // %arg5 = input (6x7)

  // Step 1: gemm: x @ W^T + b
  // PyTorch Linear: output = input @ weight.T + bias
  // input: [6x7], weight: [7x7], so weight.T: [7x7]
  // dot_general with contracting dims: input dim 1 and weight dim 1
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [1]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias (broadcast bias from [7] to [6x7])
  %1 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // Step 2: multiply by scale (elementwise multiply by scale of shape [7])
  // Broadcast scale from [7] to [6x7]
  %3 = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %4 = stablehlo.multiply %2, %3 : tensor<6x7xf32>

  // Step 3: batch norm in training mode
  // BatchNorm1d with affine parameters:
  // output = (x - mean) / sqrt(var + eps) * weight + bias
  // mean and var computed over batch dimension (dim 0)
  // input shape: [6,7], normalize over batch dim 0 for each feature dim 1

  // Compute mean over batch dim 0: result shape [7]
  %5 = "stablehlo.reduce"(%4) ( {
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  }) {dimensions = [0], keep_dims = false} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Divide sum by batch size 6 to get mean
  %c6 = stablehlo.constant 6.0 : f32
  %6 = stablehlo.div %5, %c6 : tensor<7xf32>

