  // First compute (x - mean) with broadcasting mean [7] to [6x7]
  %7 = "stablehlo.broadcast_in_dim"(%6) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %8 = stablehlo.subtract %4, %7 : tensor<6x7xf32>

