  %10 = "stablehlo.reduce"(%9) ( {
    ^bb0(%arg_a: f32, %arg_b: f32):
      %add = stablehlo.add %arg_a, %arg_b : f32
      stablehlo.return %add : f32
  }) {dimensions = [0], keep_dims = false} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Divide by batch size 6 to get variance
  %11 = stablehlo.div %10, %c6 : tensor<7xf32>

  // Add eps=1e-5 to variance
  %c_eps = stablehlo.constant 0.00001 : f32
  %12 = stablehlo.add %11, %c_eps : tensor<7xf32>

  // Compute rsqrt(variance + eps)
  %13 = stablehlo.rsqrt %12 : tensor<7xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %14 = stablehlo.multiply %8, "stablehlo.broadcast_in_dim"(%13) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Apply affine transform: * weight + bias
  // Broadcast bn.weight and bn.bias from [7] to [6x7]
  %15 = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %16 = stablehlo.multiply %14, %15 : tensor<6x7xf32>
  %17 = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = [1], output_shape = [6,7]} : (tensor<7xf32>) -> tensor<6x7xf32>
  %18 = stablehlo.add %16, %17 : tensor<6x7xf32>

  // Return final output
  stablehlo.return %18 : tensor<6x7xf32>
}

func.func @main(%scale: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %x1 = gemm: linear layer: x * weight^T + bias
  // weight shape: [7,7], input: [6,7]
  // We want input [6,7] dot weight^T [7,7]^T = [6,7] dot [7,7] = [6,7]
  // So transpose weight to [7,7] (actually same shape), but we need to contract last dim of input with last dim of weight transposed
  // dot_general with contracting dims: input last dim 1, weight last dim 1, batch dims none
  // Actually, weight is [7,7], we want to contract input dim 1 with weight dim 0 (since weight is [7,7], we want to do input * weight^T)
  // So we transpose weight to get weight^T: [7,7] -> [7,7] with permutation [1,0]
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %x1 = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // add bias: bias shape [7], broadcast to [6,7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x2 = stablehlo.add %x1, %bias_broadcast : tensor<6x7xf32>

  // multiply by scale: scale shape [7], broadcast to [6,7]
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x3 = stablehlo.multiply %x2, %scale_broadcast : tensor<6x7xf32>

  // batch norm forward (training mode):
  // batch norm formula:
  // mean = reduce_mean(x3, dim=0)
  // variance = reduce_mean((x3 - mean)^2, dim=0)
  // normalized = (x3 - mean) / sqrt(variance + eps)
  // output = normalized * bn_weight + bn_bias

  // compute mean over batch dim 0: reduce sum then divide by 6
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%x3, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // constant 6.0 for division
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  // broadcast six to [7]
  // Actually scalar tensor, can divide elementwise
  %mean = stablehlo.divide %sum, %six : tensor<7xf32>

  // compute variance:
  // x3 - mean broadcasted
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %x3, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  // sum of squared differences over batch dim 0
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // variance = var_sum / 6
  %variance = stablehlo.divide %var_sum, %six : tensor<7xf32>

  // eps constant
  %eps = stablehlo.constant dense<1e-5> : tensor<f32>
  // broadcast eps to [7]
  // add variance + eps
  %var_eps = stablehlo.add %variance, %eps : tensor<7xf32>
  // sqrt(variance + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // normalized = (x3 - mean) / stddev
  // broadcast stddev to [6x7]
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %normalized = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7xf32>

  // apply bn_weight and bn_bias: both shape [7], broadcast to [6x7]
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %scaled = stablehlo.multiply %normalized, %bn_weight_broadcast : tensor<6x7xf32>
  %out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  return %out : tensor<6x7xf32>
}

