  %scaled = "stablehlo.multiply"(%add_bias, %scale_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 4: batch normalization
  // BatchNorm1d forward in training mode:
  // Given input x (N,C) = scaled (6x7)
  // mean = reduce_mean over batch dim (dim 0)
  // var = reduce_var over batch dim (dim 0)
  // normalized = (x - mean) / sqrt(var + eps)
  // output = normalized * bn.weight + bn.bias

