  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = dense<[]>} : (tensor<f32>) -> tensor<f32>
  %mean_div = "stablehlo.divide"(%mean, %six_broadcast) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>

  // Broadcast mean to (6x7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = dense<[1]>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Compute variance: var = mean((x - mean)^2)
