  %sq_diff = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  %var_sum = "stablehlo.reduce"(%sq_diff, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = dense<[0]>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  %var = "stablehlo.divide"(%var_sum, %six_broadcast) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>

  // Add eps = 1e-5 to variance
