  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = dense<[]>} : (tensor<f32>) -> tensor<f32>
  %var_eps = "stablehlo.add"(%var, %eps_broadcast) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute rsqrt(var + eps)
