  %rsqrt_var_broadcast = "stablehlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = dense<[1]>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %normalized = "stablehlo.multiply"(%diff, %rsqrt_var_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Apply bn.weight and bn.bias: output = normalized * bn.weight + bn.bias
  // Broadcast bn.weight and bn.bias to (6x7)
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = dense<[1]>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = dense<[1]>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %scaled_bn = "stablehlo.multiply"(%normalized, %bn_weight_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
