  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_pool = stablehlo.reduce %maxpool, %init_zero {
    ^bb0(%x: f32, %y: f32):
      %z = stablehlo.add %x, %y : f32
