  %cst_28_broadcast = stablehlo.broadcast_in_dim %cst_28 : tensor<f32> to tensor<6x16x1x1x1xf32> broadcast_dimensions = []
  %avg_pool = stablehlo.divide %sum_pool, %cst_28_broadcast : tensor<6x16x1x1x1xf32>

