  // conv.weight: %arg1 shape: [16, 8, 3, 3, 3] = [out_channels, in_channels, kd, kh, kw]
  // conv.bias: %arg2 shape: [16]
  // bias: %arg0 shape: [16, 1, 1, 1]
  // divisor = 2.0 (constant)
  // max_pool kernel size = (2, 2, 2)
  // global avg pool output shape = [batch, out_channels, 1, 1, 1]
  // sum_dim = 1 (sum over out_channels dimension)

  // Step 1: convolution
  %conv = stablehlo.convolution %arg3, %arg1 {
    window_strides = [1, 1, 1],
    padding = [0, 0, 0, 0, 0, 0],
    lhs_dilation = [],
    rhs_dilation = [],
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2, 3, 4],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2, 3, 4],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3, 4]
    },
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {}
  } : tensor<6x8x16x7x7xf32>, tensor<16x8x3x3x3xf32> -> tensor<6x16x14x5x5xf32>
  // Explanation: Input spatial dims 16x7x7 convolved with 3x3x3 kernel, stride 1, no padding
  // Output spatial dims: depth: 16-3+1=14, height: 7-3+1=5, width: 7-3+1=5

  // Step 2: add conv.bias (shape [16]) to conv output (broadcast over batch and spatial dims)
  %conv_bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<6x16x14x5x5xf32> broadcast_dimensions = [1]

  %conv_with_bias = stablehlo.add %conv, %conv_bias_broadcast : tensor<6x16x14x5x5xf32>

