  %divisor = stablehlo.constant dense<2.0> : tensor<f32>
  %divisor_broadcast = stablehlo.broadcast_in_dim %divisor : tensor<f32> to tensor<6x16x14x5x5xf32> broadcast_dimensions = []
  %divided = stablehlo.divide %conv_with_bias, %divisor_broadcast : tensor<6x16x14x5x5xf32>

  // Step 4: max pooling with kernel size (2, 2, 2), stride = kernel size (default), no padding
