      stablehlo.return %sel : f32
  }

  // Step 5: global average pooling to (1, 1, 1)
  // Input shape: [6, 16, 7, 2, 2]
  // We want to average pool spatial dims 2,3,4 to size 1 each
  // So reduce mean over dims 2,3,4

  // Compute sum over dims 2,3,4
  %init_val = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_reduce = stablehlo.reduce %maxpool, %init_val {
    dimensions = [2, 3, 4]
  } : tensor<6x16x7x2x2xf32>, tensor<f32> -> tensor<6x16xf32>

  // Compute divisor for mean: 7*2*2 = 28
  %divisor_mean = stablehlo.constant dense<28.0> : tensor<f32>
  %divisor_mean_broadcast = stablehlo.broadcast_in_dim %divisor_mean : tensor<f32> to tensor<6x16xf32> broadcast_dimensions = []

  %avg_pool = stablehlo.divide %sum_reduce, %divisor_mean_broadcast : tensor<6x16xf32>

  // Reshape avg_pool from [6,16] to [6,16,1,1,1]
  %avg_pool_reshaped = stablehlo.reshape %avg_pool : tensor<6x16xf32> to tensor<6x16x1x1x1xf32>

  // Step 6: add bias (shape [16,1,1,1]) broadcasted over batch dim
  %bias_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<16x1x1x1xf32> to tensor<6x16x1x1x1xf32> broadcast_dimensions = [1, 2, 3, 4]

  %biased = stablehlo.add %avg_pool_reshaped, %bias_broadcast : tensor<6x16x1x1x1xf32>

  // Step 7: sum along dimension 1 (out_channels)
  %init_val_sum = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_out = stablehlo.reduce %biased, %init_val_sum {
    dimensions = [1]
  } : tensor<6x16x1x1x1xf32>, tensor<f32> -> tensor<6x1x1x1xf32>

  return %sum_out : tensor<6x1x1x1xf32>
}

func.func @main(%arg0: tensor<16x1x1x1xf32>, %arg1: tensor<16x8x3x3x3xf32>, %arg2: tensor<16xf32>, %arg3: tensor<6x8x16x7x7xf32>) -> tensor<6x1x1x1xf32> {
