  // max_pool3d on spatial dims (D,H,W)
  // input shape: [6,16,14,5,5]
  // output shape:
  // D_out = floor((14 - 2)/2 + 1) = floor(6 + 1) = 7
  // H_out = floor((5 - 2)/2 + 1) = floor(1.5 + 1) = 2
