  %biased = stablehlo.add %avg_reshaped, %bias_broadcast : tensor<6x16x1x1x1xf32>

  // Step 6: sum along dimension 1 (channel dim)
  // input shape: [6,16,1,1,1]
  // output shape: [6,1,1,1]
  %init_sum = constant 0.0 : f32
  %sum_dim1 = stablehlo.reduce %biased, %init_sum {
    dimensions = [1]
  } : (tensor<6x16x1x1x1xf32>, tensor<f32>) -> tensor<6x1x1x1xf32>

  // return result
  return %sum_dim1 : tensor<6x1x1x1xf32>
}

