func.func @main(%arg0: tensor<16x1x1x1xf32>, %arg1: tensor<16x8x3x3x3xf32>, %arg2: tensor<16xf32>, %arg3: tensor<6x8x16x7x7xf32>) -> tensor<6x1x1x1xf32> {
  // %arg0 = bias parameter (16x1x1x1)
  // %arg1 = conv.weight parameter (16x8x3x3x3)
  // %arg2 = conv.bias parameter (16)
  // %arg3 = input tensor (6x8x16x7x7)

  // 1) Convolution: input %arg3 (N=6, C=8, D=16, H=7, W=7)
  // conv.weight %arg1 (O=16, I=8, KD=3, KH=3, KW=3)
  // conv.bias %arg2 (16)
  // dimension_numbers for Conv3D: 
  // input: [N, C, D, H, W] = [0,1,2,3,4]
  // kernel: [O, I, KD, KH, KW] = [0,1,2,3,4]
  // output: [N, O, D_out, H_out, W_out] = [0,1,2,3,4]
