  %biased = stablehlo.add %mean_reshaped, %bias_broadcast2 : tensor<6x16x1x1x1xf32>

  // 6) Sum along dimension 1 (the channel dimension)
  %init_zero_sum = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_dim1 = "stablehlo.reduce"(%biased, %init_zero_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x16x1x1x1xf32>, tensor<f32>) -> tensor<6x1x1x1xf32>

  // Return result
  return %sum_dim1 : tensor<6x1x1x1xf32>
}

