  %4 = stablehlo.reduce %3, %cst0 : tensor<6x7xf32>, tensor<f32> {
         dimensions = dense<[1]> : tensor<1xi64>,
         body = {
           %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
           stablehlo.return %a : tensor<f32>
         }
       } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // max over dim=1 keepdim=True: reduce max over dim 1 (size 1), output shape (6x1)
  %5 = stablehlo.reduce %4, %cst_minf : tensor<6x1xf32>, tensor<f32> {
         dimensions = dense<[1]> : tensor<1xi64>,
         body = {
           %a = stablehlo.maximum %arg0, %arg1 : tensor<f32>, tensor<f32>
           stablehlo.return %a : tensor<f32>
         }
       } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // mean over dim=1 keepdim=True: reduce sum over dim 1 then divide by 1 (dim size)
  // Here dim=1 size=1, so mean is identity, but we do it explicitly for correctness
  %6 = stablehlo.reduce %5, %cst0 : tensor<6x1xf32>, tensor<f32> {
         dimensions = dense<[1]> : tensor<1xi64>,
         body = {
           %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
           stablehlo.return %a : tensor<f32>
         }
       } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // divide by 1 (dim size)
  %7 = stablehlo.constant 1.0 : tensor<f32>
  %8 = stablehlo.div %6, %7 : tensor<6x1xf32>, tensor<f32>

  // logsumexp over dim=1 keepdim=True twice
  // logsumexp(x) = log(sum(exp(x)))
  // First logsumexp:
  %9 = stablehlo.exp %8 : tensor<6x1xf32>

  %10 = stablehlo.reduce %9, %cst0 : tensor<6x1xf32>, tensor<f32> {
          dimensions = dense<[1]> : tensor<1xi64>,
          body = {
            %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
            stablehlo.return %a : tensor<f32>
          }
        } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  %11 = stablehlo.log %10 : tensor<6x1xf32>

  // Second logsumexp:
  %12 = stablehlo.exp %11 : tensor<6x1xf32>

  %13 = stablehlo.reduce %12, %cst0 : tensor<6x1xf32>, tensor<f32> {
          dimensions = dense<[1]> : tensor<1xi64>,
          body = {
            %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
            stablehlo.return %a : tensor<f32>
          }
        } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  %14 = stablehlo.log %13 : tensor<6x1xf32>

  stablehlo.return %14 : tensor<6x1xf32>
}

