func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: y = x @ W^T + b
  // %arg0 = linear.weight (7x7), %arg1 = linear.bias (7), %arg2 = input (6x7)
  // We want (6x7) @ (7x7)^T = (6x7) @ (7x7) -> (6x7)
  // So transpose weight to (7x7) (actually same shape), but we treat arg0 as (out_features x in_features)
  // So dot_general with lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[1], no batching dims
  // lhs: (6x7), rhs: (7x7)
  // Contract lhs dim 1 with rhs dim 1 means rhs dim 1 is contracting, so rhs dim 1 is in_features
  // But weight shape is (out_features, in_features) = (7,7)
  // We want to do x @ W^T, so W^T shape is (7,7), so we can do dot_general with rhs_contracting_dimensions=[0]
  // Actually, to do x @ W^T, lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[0]
  // lhs: (6x7), rhs: (7x7)
  // Result shape: (6x7)
  %dot = "stablehlo.dot_general"(%arg2, %arg0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // sum over dim=1 keepdim=True -> shape (6x1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%linear_out, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Add back dim for keepdim=True: reshape (6) -> (6x1)
  %sum_reshaped = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // max over dim=1 keepdim=True on (6x1) tensor: max over dim=1 of size 1 is the same tensor
  // So max over dim=1 of shape (6x1) is (6x1), max is identity here
  // But to follow the spec, do reduce with max
  %minf = stablehlo.constant dense<-inf> : tensor<f32>
  %max = "stablehlo.reduce"(%sum_reshaped, %minf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // reshape back to (6x1)
  %max_reshaped = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // mean over dim=1 keepdim=True on (6x1) tensor: mean over dim=1 of size 1 is the same tensor
  // But do reduce sum and divide by 1
  %zero2 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum2 = "stablehlo.reduce"(%max_reshaped, %zero2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // divide by 1 (size of dim=1)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %mean = stablehlo.divide %sum2, %one : tensor<6xf32>
  // reshape to (6x1)
  %mean_reshaped = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // logsumexp over dim=1 keepdim=True on (6x1)
  // logsumexp(x) = log(sum(exp(x)))
  // exp
  %exp1 = stablehlo.exponential %mean_reshaped : tensor<6x1xf32>
  %zero3 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp1 = "stablehlo.reduce"(%exp1, %zero3) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // reshape to (6x1)
  %sum_exp1_reshaped = "stablehlo.broadcast_in_dim"(%sum_exp1) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  // log
  %log1 = stablehlo.log %sum_exp1_reshaped : tensor<6x1xf32>

  // second logsumexp over dim=1 keepdim=True on (6x1)
  %exp2 = stablehlo.exponential %log1 : tensor<6x1xf32>
  %zero4 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp2 = "stablehlo.reduce"(%exp2, %zero4) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // reshape to (6x1)
  %sum_exp2_reshaped = "stablehlo.broadcast_in_dim"(%sum_exp2) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  // log
  %log2 = stablehlo.log %sum_exp2_reshaped : tensor<6x1xf32>

  "stablehlo.return"(%log2) : tensor<6x1xf32>
}

