func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape [16,16]
  // %arg1: gemm.weight, shape [16,16]
  // %arg2: gemm.bias, shape [16]
  // %arg0: bias (to add after gemm), shape [16]
  // %arg3: groupnorm.weight, shape [16]
  // %arg4: groupnorm.bias, shape [16]

  // GEMM: x @ gemm.weight^T + gemm.bias
  // dot_general with batch dims [0], contracting dims [1]
  %0 = stablehlo.dot_general %arg5, %arg1 {
    lhs_batch_dims = [0],
    rhs_batch_dims = [0],
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %1 = stablehlo.add %0, (stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32>) {broadcast_dimensions = [1]} : tensor<16x16xf32>

  // Add bias (arg0) after gemm + gemm.bias
  %2 = stablehlo.add %1, (stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32>) {broadcast_dimensions = [1]} : tensor<16x16xf32>

  // Hardtanh clamp between 0 and 1
  %3 = stablehlo.maximum %2, (stablehlo.constant dense<0.0> : tensor<f32>) : tensor<16x16xf32>
  %4 = stablehlo.minimum %3, (stablehlo.constant dense<1.0> : tensor<f32>) : tensor<16x16xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %5 = stablehlo.exponential %4 : tensor<16x16xf32>
  %6 = stablehlo.add %5, (stablehlo.constant dense<1.0> : tensor<f32>) : tensor<16x16xf32>
  %7 = stablehlo.log %6 : tensor<16x16xf32>
  %8 = stablehlo.tanh %7 : tensor<16x16xf32>
  %9 = stablehlo.multiply %4, %8 : tensor<16x16xf32>

  // GroupNorm:
  // input shape: [N=16, C=16]
  // num_groups=16 => group size = 1 channel per group
  // reshape to [N, G=16, group_size=1]
  %10 = stablehlo.reshape %9 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over group_size dim (dim=2)
  %11 = stablehlo.reduce %10, (stablehlo.constant dense<0.0> : tensor<f32>) {
    dimensions = [2],
    body = {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean = sum / group_size = sum / 1 = sum
  %mean = %11

  // Compute variance: mean((x - mean)^2)
  %12 = stablehlo.subtract %10, (stablehlo.broadcast_in_dim %mean : tensor<16x16xf32> to tensor<16x16x1xf32>) {broadcast_dimensions = [0,1]} : tensor<16x16x1xf32>
  %13 = stablehlo.multiply %12, %12 : tensor<16x16x1xf32>

  %14 = stablehlo.reduce %13, (stablehlo.constant dense<0.0> : tensor<f32>) {
    dimensions = [2],
    body = {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = mean of squared diffs = sum / 1 = sum
  %variance = %14

  // epsilon for numerical stability
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>

  // inv_std = rsqrt(variance + eps)
  %15 = stablehlo.add %variance, (stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<16x16xf32>) {} : tensor<16x16xf32>
  %inv_std = stablehlo.rsqrt %15 : tensor<16x16xf32>

  // Normalize: (x - mean) * inv_std
  %16 = stablehlo.subtract %9, (stablehlo.broadcast_in_dim %mean : tensor<16x16xf32> to tensor<16x16xf32>) {broadcast_dimensions = [0,1]} : tensor<16x16xf32>
  %17 = stablehlo.multiply %16, %inv_std : tensor<16x16xf32>

  // Apply groupnorm.weight (arg3) and groupnorm.bias (arg4)
  // broadcast weight and bias along batch dim (dim=0)
  %18 = stablehlo.multiply %17, (stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32>) {broadcast_dimensions = [1]} : tensor<16x16xf32>
  %19 = stablehlo.add %18, (stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32>) {broadcast_dimensions = [1]} : tensor<16x16xf32>

  stablehlo.return %19 : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape [16,16]
  // %arg1: gemm.weight [16,16]
  // %arg2: gemm.bias [16]
  // %arg0: bias [16]
  // %arg3: groupnorm.weight [16]
  // %arg4: groupnorm.bias [16]

  // GEMM: x @ weight^T + gemm.bias
  // dot_general with batch dims = [0], contracting dims = [1]
  %0 = stablehlo.dot_general %arg5, %arg1 {
    lhs_batch_dims = [0],
    rhs_batch_dims = [0],
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [1]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add gemm.bias (broadcast over batch dim)
  %1 = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions=[1]
  %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

  // Add bias (broadcast over batch dim)
  %3 = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions=[1]
  %4 = stablehlo.add %2, %3 : tensor<16x16xf32>

  // Hardtanh clamp between 0 and 1
  %5 = stablehlo.maximum %4, %cst_0 : tensor<16x16xf32>
  %6 = stablehlo.minimum %5, %cst_1 : tensor<16x16xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %7 = stablehlo.exponential %6 : tensor<16x16xf32>
  %8 = stablehlo.add %7, %cst_1 : tensor<16x16xf32>
  %9 = stablehlo.log %8 : tensor<16x16xf32>
  %10 = stablehlo.tanh %9 : tensor<16x16xf32>
  %11 = stablehlo.multiply %6, %10 : tensor<16x16xf32>

  // GroupNorm:
  // input shape: [N=16, C=16]
  // num_groups=16 => group_size = C/num_groups = 1
  // reshape to [N, G=16, group_size=1]
  %12 = stablehlo.reshape %11 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over group_size dim (dim=2)
  %13 = stablehlo.reduce %12, %cst_0 : tensor<16x16x1xf32>, tensor<f32> {
    dimensions = [2],
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean = sum / group_size = sum / 1 = sum
  %mean = %13 : tensor<16x16xf32>

  // Compute variance: mean((x - mean)^2)
  // Broadcast mean to shape [16,16,1]
  %14 = stablehlo.broadcast_in_dim %mean : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions=[0,1]

  %15 = stablehlo.subtract %12, %14 : tensor<16x16x1xf32>
  %16 = stablehlo.multiply %15, %15 : tensor<16x16x1xf32>

  %17 = stablehlo.reduce %16, %cst_0 : tensor<16x16x1xf32>, tensor<f32> {
    dimensions = [2],
    body {
      %a = stablehlo.add %arg0, %arg1 : tensor<f32>, tensor<f32>
      stablehlo.return %a : tensor<f32>
    }
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = sum / group_size = sum / 1 = sum
  %variance = %17 : tensor<16x16xf32>

  // epsilon for numerical stability
  %epsilon = stablehlo.constant 1.000000e-05 : f32

  // variance + epsilon
  %18 = stablehlo.add %variance, %epsilon : tensor<16x16xf32>

  // rsqrt(variance + epsilon)
  %19 = stablehlo.rsqrt %18 : tensor<16x16xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %20 = stablehlo.subtract %11, %mean : tensor<16x16xf32>
  %21 = stablehlo.multiply %20, %19 : tensor<16x16xf32>

  // Apply groupnorm.weight and groupnorm.bias
  // %arg3: weight [16], %arg4: bias [16]
  // broadcast weight and bias over batch dim (dim=0)
  %22 = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions=[1]
  %23 = stablehlo.multiply %21, %22 : tensor<16x16xf32>
  %24 = stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions=[1]
  %25 = stablehlo.add %23, %24 : tensor<16x16xf32>

  stablehlo.return %25 : tensor<16x16xf32>
}

