func.func @main(%bias: tensor<16xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %groupnorm_weight: tensor<16xf32>, %groupnorm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // GEMM: x = input @ gemm_weight^T + gemm_bias
  // gemm_weight shape: [16,16], input shape: [16,16]
  // We want to do dot_general with contracting dims: input dim 1 and gemm_weight dim 1 (transposed)
  // So transpose gemm_weight to [16x16] (actually same shape, but we swap dims)
  %gemm_weight_t = "stablehlo.transpose"(%gemm_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_gemm = "stablehlo.dot_general"(%input, %gemm_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_gemm_bias = stablehlo.add %x_gemm, "stablehlo.broadcast_in_dim"(%gemm_bias) {broadcast_dimensions = array<i64: 1} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Add bias (bias argument %bias) after gemm_bias addition
  %x_bias = stablehlo.add %x_gemm_bias, "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Hardtanh: clamp between 0 and 1 (default Hardtanh min_val=0, max_val=1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16xf32>
  %x_clamped_min = stablehlo.maximum %x_bias, %zero_broadcast : tensor<16x16xf32>
  %x_hardtanh = stablehlo.minimum %x_clamped_min, %one_broadcast : tensor<16x16xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %x_exp = stablehlo.exponential %x_hardtanh : tensor<16x16xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16xf32> // reuse one_broadcast
  %x_exp_plus_one = stablehlo.add %x_exp, %one_broadcast : tensor<16x16xf32>
  %x_softplus = stablehlo.log %x_exp_plus_one : tensor<16x16xf32>
  %x_tanh_softplus = stablehlo.tanh %x_softplus : tensor<16x16xf32>
  %x_mish = stablehlo.multiply %x_hardtanh, %x_tanh_softplus : tensor<16x16xf32>

  // GroupNorm with num_groups=16, num_channels=16, input shape [16,16]
