  // Then normalize: (x - mean) / sqrt(var + eps)
  // Then scale and shift with groupnorm_weight and groupnorm_bias (broadcasted)

  // Reshape x_mish to [16,16,1]
  %x_reshaped = stablehlo.reshape %x_mish : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over axis 2
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x_reshaped, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide sum by size 1 (axis 2 size)
  %one_scalar = stablehlo.constant dense<1.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %one_scalar : tensor<16x16xf32>

  // Broadcast mean back to [16,16,1]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

