  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16x1xf32>

