  // Broadcast gn_weight and gn_bias to [16,16,1]
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<1x16x1xf32>) -> tensor<16x16x1xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%gn_bias_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<1x16x1xf32>) -> tensor<16x16x1xf32>

  // Scale and shift: x_norm * weight + bias
