  %shifted = stablehlo.add %scaled, %gn_bias_broadcast : tensor<16x16x1xf32>

  // Reshape back to [16,16]
  %output = stablehlo.reshape %shifted : (tensor<16x16x1xf32>) ->

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape [16,16]
  // %arg1: gemm.weight, shape [16,16]
  // %arg2: gemm.bias, shape [16]
  // %arg0: bias (to add after gemm), shape [16]
  // %arg3: groupnorm.weight (gamma), shape [16]
  // %arg4: groupnorm.bias (beta), shape [16]

  // Step 1: gemm = x @ gemm.weight^T + gemm.bias
  // gemm.weight shape is [16,16], but PyTorch Linear uses weight shape [out_features, in_features]
  // So gemm.weight is [16,16], input is [16,16], so gemm = input @ weight^T
  // We do dot_general with contracting dims: input dim 1 and weight dim 1 (last dim)
  // But weight needs to be transposed to match PyTorch Linear semantics (weight shape is [out_features, in_features])
  // So we do dot_general with lhs_batching_dims=[0], rhs_batching_dims=[], lhs_contracting_dims=[1], rhs_contracting_dims=[1]
  // Actually, since input is [batch, in_features], weight is [out_features, in_features], we want to do input @ weight^T
  // So we transpose weight to [in_features, out_features] and then do dot_general with contracting dims [1] and [0]
  %weight_t = stablehlo.transpose %arg1 {permutation = dense<[1, 0]>} : tensor<16x16xf32> -> tensor<16x16xf32>
  %gemm = stablehlo.dot_general %arg5, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add gemm.bias (%arg2) broadcasted on dim 1
  %gemm_bias_bcast = stablehlo.broadcast_in_dim %arg2 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>
  %gemm_bias_add = stablehlo.add %gemm, %gemm_bias_bcast : tensor<16x16xf32>

  // Step 2: add bias (%arg0) broadcasted on dim 1
  %bias_bcast = stablehlo.broadcast_in_dim %arg0 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>
  %biased = stablehlo.add %gemm_bias_add, %bias_bcast : tensor<16x16xf32>

  // Step 3: Hardtanh clamp between 0 and 1 (default PyTorch Hardtanh min_val=0, max_val=1)
  // clamp(x, 0, 1) = min(max(x,0),1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_bcast = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = array<i64>} : tensor<f32> -> tensor<16x16xf32>
  %one_bcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64>} : tensor<f32> -> tensor<16x16xf32>
  %max0 = stablehlo.maximum %biased, %zero_bcast : tensor<16x16xf32>
  %hardtanh = stablehlo.minimum %max0, %one_bcast : tensor<16x16xf32>

  // Step 4: Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  // stablehlo has log_plus_one and exponential
  %exp_hardtanh = stablehlo.exponential %hardtanh : tensor<16x16xf32>
  %softplus = stablehlo.log_plus_one %exp_hardtanh : tensor<16x16xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<16x16xf32>
  %mish = stablehlo.multiply %hardtanh, %tanh_softplus : tensor<16x16xf32>

  // Step 5: GroupNorm with num_groups=16, num_channels=16, input shape [N,C] = [16,16]
  // GroupNorm divides channels into groups and normalizes each group independently.
  // Here, num_groups = num_channels = 16, so each channel is its own group.
  // So GroupNorm reduces to LayerNorm per channel: normalize each channel over batch dimension.
  // So for each channel c, compute mean and variance over batch dimension (dim 0).
  // Then normalize: (x - mean) / sqrt(var + eps)
  // Then scale by groupnorm.weight (%arg3) and shift by groupnorm.bias (%arg4)
  // eps = 1e-5 (PyTorch default)

  // Compute mean over batch dim 0: shape [16]
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce %mish, %init_zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[0]>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // mean = sum / batch_size (16)
  %batch_size = stablehlo.constant dense<16.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %batch_size : tensor<16xf32>

  // Broadcast mean to [16x16] for subtraction
  %mean_bcast = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>

  // Compute variance: mean of squared differences
  %diff = stablehlo.subtract %mish, %mean_bcast : tensor<16x16xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16xf32>

  %init_zero_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = stablehlo.reduce %diff_sq, %init_zero_var {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[0]>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  %var = stablehlo.divide %var_sum, %batch_size : tensor<16xf32>

  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<1.00000001e-5> : tensor<f32>
  %eps_bcast = stablehlo.broadcast_in_dim %eps {broadcast_dimensions = array<i64>} : tensor<f32> -> tensor<16xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<16xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<16xf32>

  // Broadcast stddev to [16x16]
  %stddev_bcast = stablehlo.broadcast_in_dim %stddev {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev_bcast : tensor<16x16xf32>

  // Scale and shift: norm * groupnorm.weight + groupnorm.bias
  %weight_bcast = stablehlo.broadcast_in_dim %arg3 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>
  %bias_bcast_gn = stablehlo.broadcast_in_dim %arg4 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>

  %scaled = stablehlo.multiply %norm, %weight_bcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %bias_bcast_gn : tensor<16x16xf32>

  return %out : tensor<16x16xf32>
}

func.func @main(%x: tensor<6xf32>) -> tensor<16xf32> {
  %cst_0 = stablehlo.constant 0.0 : f32
  %cst_0_tensor = stablehlo.constant dense<0> : tensor<1xi64>
  %cst_2_tensor = stablehlo.constant dense<2> : tensor<1xi64>
  %cst_1_tensor = stablehlo.constant dense<1> : tensor<1xi64>
  %cst_3_tensor = stablehlo.constant dense<3> : tensor<1xi64>

