func.func @main(%bias: tensor<16xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %groupnorm_weight: tensor<16xf32>, %groupnorm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // GEMM: x = input @ gemm_weight^T + gemm_bias
  // gemm_weight shape: [16,16], we want to do input [16x16] * gemm_weight^T [16x16]
  // So transpose gemm_weight to [16x16] (actually same shape, but transpose swaps dims)
  %gemm_weight_t = "stablehlo.transpose"(%gemm_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_gemm = "stablehlo.dot_general"(%input, %gemm_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_gemm_bias = stablehlo.add %x_gemm, "stablehlo.broadcast_in_dim"(%gemm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16x16xf32>

  // Add bias (bias argument %bias) after gemm_bias addition
  // The PyTorch code adds bias after gemm, so x = x + bias
  // bias shape: [16], broadcast to [16x16] on dim 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x_bias = stablehlo.add %x_gemm_bias, %bias_broadcast : tensor<16x16xf32>

  // Hardtanh: clamp x between 0 and 1 (default Hardtanh min_val=0, max_val=1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %x_clamped_min = stablehlo.maximum %x_bias, %zero_broadcast : tensor<16x16xf32>
  %x_hardtanh = stablehlo.minimum %x_clamped_min, %one_broadcast : tensor<16x16xf32>

  // Mish activation: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
  %x_exp = stablehlo.exponential %x_hardtanh : tensor<16x16xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32> // reuse
  %x_exp_plus_one = stablehlo.add %x_exp, %one_broadcast : tensor<16x16xf32>
  %x_softplus = stablehlo.log %x_exp_plus_one : tensor<16x16xf32>
  %x_tanh = stablehlo.tanh %x_softplus : tensor<16x16xf32>
  %x_mish = stablehlo.multiply %x_hardtanh, %x_tanh : tensor<16x16xf32>

  // GroupNorm:
  // input shape: [N=16, C=16]
  // num_groups=16, so each group has 1 channel
  // Reshape x_mish to [N, G, C_per_group] = [16,16,1]
  %x_reshaped = stablehlo.reshape %x_mish : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over C_per_group dimension (dim=2)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_zero_reshaped = "stablehlo.broadcast_in_dim"(%init_zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32> // dummy for reduce init
  %mean = "stablehlo.reduce"(%x_reshaped, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: [16x16], divide by C_per_group=1 (no change)
  // Reshape mean to [16x16x1] for broadcasting
  %mean_reshaped = stablehlo.reshape %mean : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // x_centered = x_reshaped - mean
  %x_centered = stablehlo.subtract %x_reshaped, %mean_reshaped : tensor<16x16x1xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%x_centered_sq, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance divide by C_per_group=1 (no change)
  %var_reshaped = stablehlo.reshape %var : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1e-5> : tensor<f32>
  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16x1xf32>

  // inv_std = rsqrt(var + epsilon)
  %var_eps = stablehlo.add %var_reshaped, %epsilon_broadcast : tensor<16x16x1xf32>
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16x1xf32>

  // Normalize: x_norm = x_centered * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std : tensor<16x16x1xf32>

  // Reshape groupnorm_weight and groupnorm_bias from [16] to [1x16x1] for broadcasting
  %gn_weight_reshaped = stablehlo.reshape %groupnorm_weight : (tensor<16xf32>) -> tensor<1x16x1xf32>
  %gn_bias_reshaped = stablehlo.reshape %groupnorm_bias : (tensor<16xf32>) -> tensor<1x16x1xf32>

  // Broadcast gn_weight and gn_bias to [16x16x1]
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<1x16x1xf32>) -> tensor<16x16x1xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%gn_bias_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<1x16x1xf32>) -> tensor<16x16x1xf32>

  // Apply scale and shift: y = x_norm * weight + bias
  %y_scaled = stablehlo.multiply %x_norm, %gn_weight_broadcast : tensor<16x16x1xf32>
  %y_shifted = stablehlo.add %y_scaled, %gn_bias_broadcast : tensor<16x16x1xf32>

  // Reshape back to [16x16]
  %y = stablehlo.reshape %y_shifted : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  return %y : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // 1. GEMM: x = %arg5 @ %arg1^T
  // PyTorch Linear: output = input @ weight.T + bias
  // Here weight shape is (16,16), input shape (16,16)
  // We want to do dot_general with contracting dims: input dim 1 and weight dim 1 (weight is transposed)
  // So we transpose weight to get shape (16,16) -> (16,16) (actually same shape, but we swap contracting dims)
  // We'll do dot_general with lhs_batching_dims=[0], rhs_batching_dims=[], lhs_contracting_dims=[1], rhs_contracting_dims=[1]
  // But since weight is (16x16), and input is (16x16), to do input @ weight.T, we do dot_general with rhs_contracting_dims=0 (first dim)
  // So better to transpose weight first to get weight.T shape (16x16)
  %weight_t = stablehlo.transpose %arg1 {permutation = [1, 0]} : tensor<16x16xf32> -> tensor<16x16xf32>
  %gemm = stablehlo.dot_general %arg5, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // 2. Add bias (%arg0) to gemm output
  // %arg0 shape: [16], gemm shape: [16,16]
  // Broadcast bias on dimension 1 (features)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %add_bias = stablehlo.add %gemm, %bias_broadcast : tensor<16x16xf32>

  // 3. Hardtanh activation: clamp between 0 and 1
  // Hardtanh clamps input to [min_val, max_val], default min=0, max=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_broadcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %clamp_min = stablehlo.maximum %add_bias, %zero_broadcast : tensor<16x16xf32>
  %hardtanh = stablehlo.minimum %clamp_min, %one_broadcast : tensor<16x16xf32>

  // 4. Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  // stablehlo has math.exponential_minus_one and math.log_plus_one, but we can do exp(x), add 1, then log
  %exp_hardtanh = stablehlo.exponential %hardtanh : tensor<16x16xf32>
  %one_tensor = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast2 = stablehlo.broadcast_in_dim %one_tensor : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %exp_plus_one = stablehlo.add %exp_hardtanh, %one_broadcast2 : tensor<16x16xf32>
  %softplus = stablehlo.log %exp_plus_one : tensor<16x16xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<16x16xf32>
  %mish = stablehlo.multiply %hardtanh, %tanh_softplus : tensor<16x16xf32>

  // 5. GroupNorm with num_groups=16, num_channels=16, input shape (N=16, C=16)
  // GroupNorm divides channels into groups, here each channel is its own group (16 groups for 16 channels)
  // So group size = 1 channel per group
  // For each group, compute mean and variance over group channels and batch dimension
  // But since group size=1, mean and variance are over batch dimension only (dim 0)
  // So for each channel c, compute mean and variance over batch dimension (dim 0)
  // Then normalize: (x - mean) / sqrt(var + eps)
  // Then scale and shift by groupnorm.weight (%arg3) and groupnorm.bias (%arg4)
  // Shapes:
  // mish: tensor<16x16xf32> (N,C)
  // mean: tensor<16xf32> (per channel)
  // variance: tensor<16xf32> (per channel)
  // weight and bias: tensor<16xf32>

  // Compute mean over batch dimension (dim 0)
