  } {dimensions = [2]} : (tensor<16x1x14x14xf32>, tensor<f32>) -> tensor<16x1x1x14xf32>

  // GELU activation
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %half = stablehlo.constant dense<0.5> : tensor<f32>
